import React, { useEffect, useMemo, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '@/shared/components/ui/button';
import { Input } from '@/shared/components/ui/input';
import { InlineFieldError } from '@/shared/components/ui/InlineFieldError';
import { CheckCircle, Eye, EyeOff, Key, Loader2 } from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AuthService } from '@/core/auth';
import { useAuth } from '@/core/auth/hooks/useAuth';
import { getAuthErrorMessage } from '@/core/auth/utils/authMessages';
import { getAuthPasswordRequirementStatus } from '@/core/auth/utils/passwordPolicy';
import { useToast } from '@/shared/hooks/use-toast';
import {
  ResetPasswordFormSchema,
  type ResetPasswordFormInput,
} from '@/shared/validation/schemas/user.schema';

type RecoveryState = 'checking' | 'ready' | 'invalid';

export default function ResetPasswordPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { toast } = useToast();
  const { user, updatePassword, resetPasswordByIdentifier } = useAuth();
  const [showPassword, setShowPassword] = useState(false);
  const [done, setDone] = useState(false);
  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    // Se chegou com ?expired=1, já sabemos que é inválido
    searchParams.get('expired') === '1' ? 'invalid' : 'checking'
  );
  const [resendEmail, setResendEmail] = useState('');
  const [isSendingLink, setIsSendingLink] = useState(false);

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<ResetPasswordFormInput>({
    resolver: zodResolver(ResetPasswordFormSchema),
    mode: 'onBlur',
  });

  // Derivado do watch para o PasswordStrengthIndicator em tempo real
  const newPasswordValue = watch('newPassword') ?? '';
  const passwordRequirements = useMemo(
    () => getAuthPasswordRequirementStatus(newPasswordValue),
    [newPasswordValue],
  );

  useEffect(() => {
    // Se já sabemos que é inválido (ex: ?expired=1), não precisa verificar
    if (recoveryState === 'invalid') return;

    // Caso 1: hash da URL tem access_token + type=recovery (implicit flow)
    // Com flowType='implicit' o SDK processa automaticamente, mas como fallback
    // também tentamos via setSession caso o hash ainda esteja disponível
    const hashParams = AuthService.captureAuthHash();
    const accessToken = hashParams.get('access_token');
    const refreshToken = hashParams.get('refresh_token');
    const hashType = hashParams.get('type');

    if (accessToken && hashType === 'recovery') {
      AuthService.applyRecoverySession(accessToken, refreshToken).then((isApplied) => {
        setRecoveryState(isApplied ? 'ready' : 'invalid');
      });
      return;
    }

    // Caso 2: URL já tem o marcador de recovery (redirect com ?mode=recovery)
    if (AuthService.isRecoveryRedirect()) {
      setRecoveryState('ready');
      return;
    }

    // Caso 3: usuário já autenticado via sessão de recovery ativa
    if (user) {
      setRecoveryState('ready');
      return;
    }

    // Caso 4: aguardar evento PASSWORD_RECOVERY do SDK Supabase (PKCE flow com ?code=)
    const unsubscribeRecovery = AuthService.onPasswordRecovery(() => {
      setRecoveryState('ready');
    });

    // Timeout de segurança: se nenhum evento chegar em 3s, link é inválido
    const invalidTimer = window.setTimeout(() => {
      setRecoveryState((current) => (current === 'checking' ? 'invalid' : current));
    }, 3000);

    return () => {
      window.clearTimeout(invalidTimer);
      unsubscribeRecovery();
    };
  }, [user]);

  const onValid = async (data: ResetPasswordFormInput) => {
    if (recoveryState !== 'ready') {
      toast({
        title: 'Link invalido ou expirado',
        description: 'Solicite um novo email de recuperacao.',
        variant: 'destructive',
      });
      return;
    }

    try {
      await updatePassword(data.newPassword);
      setDone(true);
      toast({ title: 'Senha redefinida com sucesso.' });
      window.setTimeout(() => navigate('/'), 2000);
    } catch (error) {
      toast({
        title: 'Erro ao redefinir senha',
        description: getAuthErrorMessage(error),
        variant: 'destructive',
      });
    }
  };

  const handleResendLink = async () => {
    if (!resendEmail.trim()) {
      toast({ title: 'Informe seu email para reenviar o link.', variant: 'destructive' });
      return;
    }
    setIsSendingLink(true);
    try {
      await resetPasswordByIdentifier(resendEmail.trim());
      toast({ title: 'Link enviado', description: 'Verifique sua caixa de entrada.' });
    } catch (error) {
      toast({ title: 'Erro ao enviar', description: getAuthErrorMessage(error), variant: 'destructive' });
    } finally {
      setIsSendingLink(false);
    }
  };

  if (done) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <div className="text-center space-y-3">
          <CheckCircle className="h-12 w-12 text-primary mx-auto" />
          <h1 className="text-xl font-bold">Senha redefinida</h1>
          <p className="text-sm text-muted-foreground">Redirecionando...</p>
        </div>
      </div>
    );
  }

  if (recoveryState === 'invalid') {
    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <div className="w-full max-w-sm space-y-6 rounded-2xl border border-border bg-card p-6 text-center">
          <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center mx-auto">
            <Key className="h-6 w-6 text-primary" />
          </div>
          <div className="space-y-2">
            <h1 className="text-xl font-bold">Link expirado</h1>
            <p className="text-sm text-muted-foreground">
              O link de recuperacao de senha expirou. Informe seu email para receber um novo link.
            </p>
          </div>
          <div className="space-y-3 text-left">
            <label className="text-xs font-medium text-muted-foreground block">Email</label>
            <Input
              type="email"
              placeholder="seu@email.com"
              value={resendEmail}
              onChange={(e) => setResendEmail(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleResendLink()}
            />
            <Button className="w-full" onClick={handleResendLink} disabled={isSendingLink}>
              {isSendingLink ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : null}
              Enviar novo link
            </Button>
          </div>
          <Button variant="ghost" className="w-full text-sm" onClick={() => navigate('/login')}>
            Voltar ao login
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-sm space-y-6">
        <div className="text-center">
          <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-3">
            <Key className="h-6 w-6 text-primary" />
          </div>
          <h1 className="text-xl font-bold font-display">Redefinir senha</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Defina uma nova senha segura para acessar sua conta.
          </p>
        </div>

        <form
          onSubmit={handleSubmit(onValid)}
          className="space-y-4 rounded-2xl border border-border bg-card p-5"
          noValidate
        >
          <div>
            <label className="text-xs font-medium text-muted-foreground mb-1 block">
              Nova senha
            </label>
            <div className="relative">
              <Input
                type={showPassword ? 'text' : 'password'}
                placeholder="Minimo 8 caracteres"
                autoComplete="new-password"
                aria-describedby={errors.newPassword ? 'new-password-error' : undefined}
                {...register('newPassword')}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground"
                aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}
              >
                {showPassword ? (
                  <EyeOff className="h-4 w-4" />
                ) : (
                  <Eye className="h-4 w-4" />
                )}
              </button>
            </div>
            <InlineFieldError id="new-password-error" message={errors.newPassword?.message} />
          </div>

          {/* PasswordStrengthIndicator — alimentado por watch('newPassword') */}
          <div className="space-y-1 rounded-xl border border-border/60 bg-secondary/30 p-3">
            {passwordRequirements.map((requirement) => (
              <div
                key={requirement.id}
                className={`text-xs ${requirement.satisfied ? 'text-success' : 'text-muted-foreground'}`}
              >
                {requirement.satisfied ? 'OK' : '•'} {requirement.label}
              </div>
            ))}
          </div>

          <div>
            <label className="text-xs font-medium text-muted-foreground mb-1 block">
              Confirmar senha
            </label>
            <Input
              type="password"
              placeholder="Repita a nova senha"
              autoComplete="new-password"
              aria-describedby={errors.confirmNewPassword ? 'confirm-password-error' : undefined}
              {...register('confirmNewPassword')}
            />
            <InlineFieldError
              id="confirm-password-error"
              message={errors.confirmNewPassword?.message}
            />
          </div>

          <Button
            type="submit"
            disabled={isSubmitting || recoveryState !== 'ready'}
            className="w-full"
          >
            {isSubmitting ? (
              <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
            ) : null}
            Redefinir senha
          </Button>
        </form>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import { Label } from "@/shared/components/ui/label";
import { Switch } from "@/shared/components/ui/switch";
import { Input } from "@/shared/components/ui/input";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import { useToast } from "@/shared/hooks/use-toast";
import { Settings, MapPin, TrendingUp, Save, RefreshCw } from "lucide-react";
import { logger } from "@/shared/utils/logger";
import { useLocationContext } from "@/core/location";
import { adminMobilityRuntimeService } from "@/core/admin/services/AdminMobilityRuntimeService";

interface MobilitySettings {
  prioritize_destination_residents: {
    enabled: boolean;
    bonus_points: number;
  };
}

const DEFAULT_SETTINGS: MobilitySettings = {
  prioritize_destination_residents: {
    enabled: true,
    bonus_points: 10,
  },
};

export function MobilitySettingsPanel() {
  const { toast } = useToast();
  const { activeLocation } = useLocationContext();

  const activeLocationId = activeLocation?.id ?? null;
  const activeLocationName = activeLocation?.name ?? "Nenhuma localizacao selecionada";

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [motoboyModeEnabled, setMotoboyModeEnabled] = useState(true);
  const [settings, setSettings] = useState<MobilitySettings>(DEFAULT_SETTINGS);

  useEffect(() => {
    void loadSettings();
  }, [activeLocationId]);

  const loadSettings = async () => {
    setLoading(true);
    try {
      setSettings(DEFAULT_SETTINGS);

      if (!activeLocationId) {
        setMotoboyModeEnabled(false);
        return;
      }

      const enabled = await adminMobilityRuntimeService.isMotoboyEnabled(activeLocationId);
      setMotoboyModeEnabled(enabled);
    } catch (error) {
      logger.error("Erro ao carregar configuracoes:", error);
      toast({
        title: "Erro",
        description: "Nao foi possivel carregar as configuracoes de mobilidade.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async () => {
    if (!activeLocationId) {
      toast({
        title: "Localizacao obrigatoria",
        description: "Selecione uma localizacao ativa para salvar o modo motoboy.",
        variant: "destructive",
      });
      return;
    }

    setSaving(true);
    try {
      await adminMobilityRuntimeService.setMotoboyEnabled(activeLocationId, motoboyModeEnabled);

      toast({
        title: "Configuracoes salvas",
        description: `Modo motoboy ${motoboyModeEnabled ? "ativado" : "desativado"} para ${activeLocationName}.`,
      });
    } catch (error) {
      logger.error("Erro ao salvar configuracoes:", error);
      toast({
        title: "Erro",
        description: "Nao foi possivel salvar as configuracoes.",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  const updateDestinationPriority = (
    field: "enabled" | "bonus_points",
    value: boolean | number,
  ) => {
    setSettings((prev) => ({
      ...prev,
      prioritize_destination_residents: {
        ...prev.prioritize_destination_residents,
        [field]: value,
      },
    }));
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <RefreshCw className="h-6 w-6 animate-spin text-muted-foreground" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Settings className="h-5 w-5 text-primary" />
              <CardTitle>Configuracoes de Mobilidade</CardTitle>
            </div>
            <Badge variant="outline" className="text-xs">
              {activeLocationName}
            </Badge>
          </div>
          <CardDescription>
            Configure recursos operacionais por localizacao ativa.
          </CardDescription>
        </CardHeader>
      </Card>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Settings className="h-5 w-5 text-primary" />
            <CardTitle>Modo Motoboy</CardTitle>
          </div>
          <CardDescription>
            Ativa ou desativa novas solicitacoes de entrega por motoboy.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between p-4 rounded-lg border bg-muted/50">
            <div className="space-y-1">
              <Label htmlFor="motoboy-enabled" className="text-sm font-semibold">
                Permitir entregas por motoboy
              </Label>
              <p className="text-xs text-muted-foreground">
                Quando desligado, novas entregas sao bloqueadas no fluxo operacional.
              </p>
            </div>
            <Switch
              id="motoboy-enabled"
              checked={motoboyModeEnabled}
              onCheckedChange={setMotoboyModeEnabled}
              disabled={!activeLocationId}
            />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <MapPin className="h-5 w-5 text-primary" />
            <CardTitle>Prioridade por Destino</CardTitle>
          </div>
          <CardDescription>
            Prioriza motoristas que moram no bairro de destino da corrida.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex items-center justify-between p-4 rounded-lg border bg-muted/50">
            <div className="space-y-1">
              <Label
                htmlFor="destination-priority"
                className="text-sm font-semibold"
              >
                Ativar prioridade por destino
              </Label>
              <p className="text-xs text-muted-foreground">
                Motoristas que moram no destino recebem pontos extras no match.
              </p>
            </div>
            <Switch
              id="destination-priority"
              checked={settings.prioritize_destination_residents.enabled}
              onCheckedChange={(checked) =>
                updateDestinationPriority("enabled", checked)
              }
            />
          </div>

          {settings.prioritize_destination_residents.enabled && (
            <div className="space-y-3 p-4 rounded-lg border bg-card">
              <div className="flex items-center justify-between">
                <Label htmlFor="bonus-points" className="text-sm font-semibold">
                  Pontos de bonus
                </Label>
                <Badge variant="secondary" className="text-xs">
                  {settings.prioritize_destination_residents.bonus_points} pontos
                </Badge>
              </div>
              <Input
                id="bonus-points"
                type="range"
                min="0"
                max="20"
                step="1"
                value={settings.prioritize_destination_residents.bonus_points}
                onChange={(e) =>
                  updateDestinationPriority(
                    "bonus_points",
                    Number(e.target.value),
                  )
                }
                className="w-full"
              />
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>0 (desativado)</span>
                <span>10 (recomendado)</span>
                <span>20 (maximo)</span>
              </div>
              <p className="text-xs text-muted-foreground mt-2">
                Motoristas que moram no bairro de destino ganham {" "}
                {settings.prioritize_destination_residents.bonus_points} pontos extras no score de prioridade.
              </p>
            </div>
          )}

          <div className="p-4 rounded-lg border bg-accent/5 space-y-2">
            <div className="flex items-center gap-2">
              <TrendingUp className="h-4 w-4 text-accent" />
              <span className="text-sm font-semibold text-accent">
                Como funciona
              </span>
            </div>
            <div className="text-xs text-muted-foreground space-y-1">
              <p>
                - Passageiro pede corrida para <strong>Bairro A</strong>
              </p>
              <p>- Motorista 1 (mora Bairro B): 2km {'->'} Score: 85</p>
              <p>
                - Motorista 2 (mora Bairro A): 3km {'->'} Score: 90 (+
                {settings.prioritize_destination_residents.bonus_points} bonus)
              </p>
              <p className="text-accent font-semibold">
                Motorista 2 ganha (mora no destino)
              </p>
            </div>
          </div>

          <div className="p-4 rounded-lg border bg-primary/5 space-y-2">
            <span className="text-sm font-semibold text-primary">
              Vantagens
            </span>
            <ul className="text-xs text-muted-foreground space-y-1 list-disc list-inside">
              <li>Motorista termina corrida perto de casa</li>
              <li>Conhece melhor o bairro de destino</li>
              <li>Pode voltar para casa depois da corrida</li>
              <li>Mais seguranca (area conhecida)</li>
              <li>Menos corridas de retorno vazias</li>
            </ul>
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end gap-3">
        <Button variant="outline" onClick={loadSettings} disabled={saving}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Recarregar
        </Button>
        <Button
          onClick={saveSettings}
          disabled={saving}
          className="bg-primary hover:bg-primary/90"
        >
          <Save className="h-4 w-4 mr-2" />
          {saving ? "Salvando..." : "Salvar Configuracoes"}
        </Button>
      </div>

      <Card className="border-warning/20 bg-warning/5">
        <CardContent className="p-4">
          <p className="text-xs text-muted-foreground">
            <strong>Nota:</strong> O toggle de motoboy e persistido em
            <code> module_rollouts.config </code>
            da localizacao ativa. A prioridade por destino permanece local ate o schema dedicado ser publicado.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * useDriverManagement
 *
 * Hook para gerenciar motoristas (carregar, aprovar, rejeitar, suspender, etc).
 * SSOT: persistencia de moderacao em profiles.
 */

import { useEffect, useState } from "react";
import { useToast } from "@/shared/hooks/use-toast";
import { profileService } from "@/core/profiles/services/ProfileService";
import { logger } from "@/shared/utils/logger";
import type { DriverRequest, FilterStatus, SuspensionHistoryEntry } from "../sections/types";
import { RIDE_STATUS } from "@/shared/types/constants";
import {
  adminMobilityRuntimeService,
  type DriverModerationAction,
} from "@/core/admin/services/AdminMobilityRuntimeService";
import { AdminDriverModerationService, type DriverModerationRow } from "@/core/admin/services/AdminDriverModerationService";

export function useDriverManagement(filter: FilterStatus, canModerate: boolean, isChecking: boolean) {
  const { toast } = useToast();
  const [drivers, setDrivers] = useState<DriverRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);

  const appendModerationEvent = async (params: {
    driverProfileId: string;
    action: DriverModerationAction;
    reason?: string;
    metadata?: Record<string, unknown>;
  }) => {
    try {
      const adminProfile = await profileService.getActiveProfile();
      await adminMobilityRuntimeService.createDriverModerationEvent({
        driverProfileId: params.driverProfileId,
        adminProfileId: adminProfile?.id ?? null,
        action: params.action,
        reason: params.reason,
        metadata: params.metadata,
      });
    } catch (error) {
      logger.warn("useDriverManagement.appendModerationEvent", error);
    }
  };

  useEffect(() => {
    if (!isChecking && canModerate) {
      void loadDrivers();
    }
  }, [filter, canModerate, isChecking]);

  const loadDrivers = async () => {
    setLoading(true);
    try {
      const { data: driversData, error } = await adminMobilityRuntimeService.getDriverProfiles();

      if (error) {
        logger.error("Erro ao carregar motoristas:", error as Error);
        toast({
          title: "Erro ao carregar motoristas",
          description: "Nao foi possivel carregar a lista de motoristas.",
          variant: "destructive",
        });
        setDrivers([]);
        return;
      }

      const profileIds = (driversData || [])
        .map((d: any) => d.profile_id)
        .filter((id: unknown): id is string => typeof id === "string" && id.length > 0);

      let moderationMap = new Map<string, DriverModerationRow>();
      if (profileIds.length > 0) {
        moderationMap = await AdminDriverModerationService.getModerationRows(profileIds);
      }

      const driversWithContext = await Promise.all(
        (driversData || []).map(async (d: any) => {
          const profileContext = d.user_id
            ? await profileService.getProfileContext(d.user_id)
            : null;

          const moderation = moderationMap.get(d.profile_id);

          return {
            id: d.profile_id,
            profile_id: d.profile_id,
            name: d.name,
            avatar_url: d.avatar_url,
            vehicle_plate: d.vehicle_plate,
            vehicle_model: d.vehicle_model,
            vehicle_year: d.vehicle_year,
            cnh_image_url: d.cnh_image_url,
            profileContext,
            is_online: d.is_online || false,
            subscription_plan: d.subscription_plan || "padrao",
            rating: d.avg_rating || 0,
            total_rides: d.total_rides || 0,
            total_earnings: d.total_earnings || 0,
            created_at: d.created_at,
            updated_at: d.updated_at,
            neighborhood: d.neighborhood,
            city: d.city,
            verification_status: moderation?.verification_status ?? null,
            verification_rejection_reason: moderation?.verification_rejection_reason ?? null,
            is_suspended: moderation?.is_suspended ?? false,
            suspended_at: moderation?.suspended_at ?? null,
            suspended_until: moderation?.suspended_until ?? null,
            suspension_reason: moderation?.suspension_reason ?? null,
          } as DriverRequest;
        }),
      );

      let filtered = driversWithContext;
      if (filter === RIDE_STATUS.PENDING) {
        filtered = driversWithContext.filter(
          (d) =>
            AdminDriverModerationService.resolveVerificationStatus({
              verificationStatus: d.verification_status,
              fallbackVerified: Boolean(d.profileContext?.verified),
            }) === "pending",
        );
      } else if (filter === "approved") {
        filtered = driversWithContext.filter(
          (d) =>
            AdminDriverModerationService.resolveVerificationStatus({
              verificationStatus: d.verification_status,
              fallbackVerified: Boolean(d.profileContext?.verified),
            }) === "verified",
        );
      } else if (filter === "rejected") {
        filtered = driversWithContext.filter(
          (d) =>
            AdminDriverModerationService.resolveVerificationStatus({
              verificationStatus: d.verification_status,
              fallbackVerified: Boolean(d.profileContext?.verified),
            }) === "rejected",
        );
      }

      setDrivers(filtered);
    } catch (error) {
      logger.error("Erro ao carregar motoristas:", error as Error);
      toast({
        title: "Erro ao carregar motoristas",
        description: "Nao foi possivel carregar a lista de motoristas.",
        variant: "destructive",
      });
      setDrivers([]);
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (driver: DriverRequest) => {
    setProcessing(true);
    try {
      await profileService.approveVerification(driver.profile_id);
      await appendModerationEvent({
        driverProfileId: driver.profile_id,
        action: "approved",
      });

      toast({
        title: "Motorista aprovado",
        description: `${driver.name ?? "Motorista"} agora pode aceitar corridas.`,
      });
      await loadDrivers();
    } catch (error: any) {
      toast({
        title: "Erro",
        description: error?.message || "Nao foi possivel aprovar o motorista.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const handleReject = async (driver: DriverRequest, reason: string) => {
    if (!reason.trim()) {
      toast({
        title: "Motivo obrigatorio",
        description: "Informe o motivo da rejeicao.",
        variant: "destructive",
      });
      return;
    }

    setProcessing(true);
    try {
      await profileService.rejectVerification(driver.profile_id, reason.trim());
      await adminMobilityRuntimeService.updateDriverOnlineStatus(driver.profile_id, false).catch((err) =>
        logger.warn("useDriverManagement.handleReject - online status fallback", err),
      );
      await appendModerationEvent({
        driverProfileId: driver.profile_id,
        action: "rejected",
        reason: reason.trim(),
        metadata: { forced_offline: true },
      });

      toast({
        title: "Cadastro rejeitado",
        description: `${driver.name ?? "Motorista"} foi marcado como rejeitado.`,
      });
      await loadDrivers();
    } catch (error: any) {
      toast({
        title: "Erro",
        description: error?.message || "Nao foi possivel rejeitar o cadastro.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const handleToggleOnline = async (driver: DriverRequest, newOnlineStatus: boolean) => {
    setProcessing(true);
    try {
      await adminMobilityRuntimeService.updateDriverOnlineStatus(driver.profile_id, newOnlineStatus);
      await appendModerationEvent({
        driverProfileId: driver.profile_id,
        action: newOnlineStatus ? "set_online" : "set_offline",
      });

      toast({
        title: newOnlineStatus ? "Motorista online" : "Motorista offline",
        description: `${driver.name ?? "Motorista"} foi colocado ${newOnlineStatus ? "online" : "offline"}.`,
      });

      await loadDrivers();
    } catch (error) {
      logger.error("Erro ao alterar status:", error as Error);
      toast({
        title: "Erro",
        description: "Nao foi possivel alterar o status do motorista.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const handleSuspend = async (driver: DriverRequest, reason: string) => {
    setProcessing(true);
    try {
      const suspensionReason = reason || "Suspenso pelo administrador";
      await profileService.suspendUser(
        driver.profile_id,
        "30 days",
        suspensionReason,
      );

      await adminMobilityRuntimeService.updateDriverOnlineStatus(driver.profile_id, false).catch((err) =>
        logger.warn("Aviso ao atualizar driver_data:", err),
      );
      await appendModerationEvent({
        driverProfileId: driver.profile_id,
        action: "suspended",
        reason: suspensionReason,
      });

      toast({
        title: "Motorista suspenso",
        description: `${driver.name ?? "Motorista"} foi suspenso e nao podera aceitar corridas.`,
      });

      await loadDrivers();
    } catch (error) {
      logger.error("Erro ao suspender motorista:", error as Error);
      toast({
        title: "Erro",
        description: "Nao foi possivel suspender o motorista.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const handleReactivate = async (driver: DriverRequest) => {
    setProcessing(true);
    try {
      await profileService.unsuspendUser(driver.profile_id);
      await appendModerationEvent({
        driverProfileId: driver.profile_id,
        action: "reactivated",
      });

      toast({
        title: "Motorista reativado",
        description: `${driver.name ?? "Motorista"} foi reativado e pode voltar a aceitar corridas.`,
      });

      await loadDrivers();
    } catch (error) {
      logger.error("Erro ao reativar motorista:", error as Error);
      toast({
        title: "Erro",
        description: "Nao foi possivel reativar o motorista.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const loadSuspensionHistory = async (driverProfileId: string): Promise<SuspensionHistoryEntry[]> => {
    try {
      const events = await adminMobilityRuntimeService.listDriverModerationEvents(driverProfileId);
      if (events.length > 0) {
        return events.map((event) => ({
          id: event.id,
          action: event.action,
          reason: event.reason || undefined,
          admin_name: event.admin_name || "Admin",
          created_at: event.created_at,
        }));
      }

      return await AdminDriverModerationService.getFallbackSuspensionHistory(driverProfileId) as SuspensionHistoryEntry[];
    } catch (error) {
      logger.error("useDriverManagement.loadSuspensionHistory", error as Error);
      return [];
    }
  };

  return {
    drivers,
    loading,
    processing,
    loadDrivers,
    handleApprove,
    handleReject,
    handleToggleOnline,
    handleSuspend,
    handleReactivate,
    loadSuspensionHistory,
  };
}

