/**
 * CreatePostModal - Modal para criação de posts
 *
 * SSOT - Usa postService via hook
 * UX - Validação em tempo real
 * Performance - Memoização de componentes
 * Acessibilidade - ARIA labels completos
 */

import React from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import { Button } from "@/shared/components/ui/button";
import { Textarea } from "@/shared/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/components/ui/avatar";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import {
  Image,
  BarChart2,
  MapPin,
  MessageSquare,
  Calendar,
  Newspaper,
  Globe,
  Home,
  Navigation,
  X,
  AlertCircle,
} from "lucide-react";
import { useSessionContext } from "@/core/session";
import { useCreatePostForm } from "../../hooks/composer/useCreatePostForm";
import { postService } from "@/core/posts/services";
import { toast } from "sonner";
import { cn } from "@/shared/utils/cn";
import type { PostType } from "@/core/posts/types/Post";
import { useMultiProfileContext } from "@/core/profiles/contexts/multi-profile-runtime-context";
import { ActiveProfileBadge } from "@/core/profiles/components/ActiveProfileBadge";
import { useTerritoryFilter } from "@/core/location/hooks/useTerritoryFilter";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";

interface CreatePostModalProps {
  open: boolean;
  onClose: () => void;
  defaultType?: PostType;
}

interface ProfileForPost {
  id: string;
  displayName: string;
  avatarUrl?: string;
  locationId?: string;
  profileType?: string;
}

function toProfileForPost(profile: unknown): ProfileForPost | null {
  if (!profile || typeof profile !== "object") {
    return null;
  }

  const record = profile as Record<string, unknown>;
  const id = typeof record.id === "string" ? record.id : null;
  if (!id) return null;

  const displayName =
    (typeof record.display_name === "string" && record.display_name) ||
    (typeof record.displayName === "string" && record.displayName) ||
    (typeof record.name === "string" && record.name) ||
    "Usuario";

  const avatarUrl =
    (typeof record.avatar_url === "string" && record.avatar_url) ||
    (typeof record.avatarUrl === "string" && record.avatarUrl) ||
    undefined;

  const locationId =
    (typeof record.location_id === "string" && record.location_id) ||
    (typeof record.locationId === "string" && record.locationId) ||
    undefined;

  const profileType =
    (typeof record.profile_type === "string" && record.profile_type) ||
    (typeof record.profileType === "string" && record.profileType) ||
    undefined;

  return {
    id,
    displayName,
    avatarUrl,
    locationId,
    profileType,
  };
}

const POST_TYPES: {
  value: PostType;
  label: string;
  icon: React.ElementType;
  description: string;
  color: string;
}[] = [
  { value: "discussao", label: "Discussão", icon: MessageSquare, description: "Inicie uma conversa com a vizinhança", color: "text-blue-400" },
  { value: "recomendacao", label: "Recomendação", icon: MapPin, description: "Indique um lugar, serviço ou pessoa", color: "text-green-400" },
  { value: "evento", label: "Evento", icon: Calendar, description: "Divulgue um evento local", color: "text-purple-400" },
  { value: "noticia", label: "Notícia", icon: Newspaper, description: "Compartilhe uma notícia do bairro", color: "text-yellow-400" },
  { value: "enquete", label: "Enquete", icon: BarChart2, description: "Crie uma votação para a comunidade", color: "text-orange-400" },
];

const REACH_OPTIONS = [
  { value: "street", label: "Minha rua", icon: Navigation, description: "Visível apenas para moradores da sua rua" },
  { value: "neighborhood", label: "Meu bairro", icon: Home, description: "Visível para todo o bairro" },
  { value: "city", label: "Cidade", icon: Globe, description: "Visível para toda a cidade" },
];

export function CreatePostModal({ open, onClose, defaultType }: CreatePostModalProps) {
  const { activeProfile: sessionProfile } = useSessionContext();
  const { effectiveProfile } = useMultiProfileContext();
  // effectiveProfile = contextual (business/professional/driver) ?? personal
  const rawProfile = effectiveProfile ?? sessionProfile;
  const profile = toProfileForPost(rawProfile);
  const form = useCreatePostForm();
  const [publishing, setPublishing] = React.useState(false);
  const territoryFilter = useTerritoryFilter();

  React.useEffect(() => {
    if (open) {
      form.setType(defaultType ?? "discussao");
    }
  }, [open, defaultType]);

  const displayName = profile?.displayName || "Usuário";
  const initials = displayName.split(" ").map((n: string) => n[0]).join("").toUpperCase().slice(0, 2);
  const currentType = POST_TYPES.find((t) => t.value === form.type);
  const currentReach = REACH_OPTIONS.find((r) => r.value === form.reach);

  const charPercent = (form.characterCount / 2000) * 100;
  const charColor = charPercent > 90 ? "text-red-400" : charPercent > 70 ? "text-yellow-400" : "text-muted-foreground/50";

  // SPRINT 2 FASE 3: Resolução de location_id para criação
  const getLocationIdForPost = (): { location_id: string | null; error: string | null } => {
    // 1. Se território ativo for group, usar localização do perfil quando disponível
    if (territoryFilter.scope === "group") {
      if (profile?.locationId) {
        return {
          location_id: profile.locationId,
          error: null,
        };
      }

      return {
        location_id: null,
        error: "Selecione um bairro/cidade no filtro ou atualize sua localização no perfil",
      };
    }

    // 2. Se território ativo for location, usar
    if (territoryFilter.scope === "location") {
      return {
        location_id: territoryFilter.location_id,
        error: null,
      };
    }

    // 3. Fallback para profile.locationId (compatível com camel/snake no adaptador)
    if (profile?.locationId) {
      return {
        location_id: profile.locationId,
        error: null,
      };
    }

    // 4. Sem localização disponível
    return {
      location_id: null,
      error: "Configure sua localização no perfil antes de publicar",
    };
  };

  const { location_id: resolvedLocationId, error: locationError } = getLocationIdForPost();
  const canPublish = form.isValid && !locationError && !publishing;

  const handlePublish = async () => {
    if (!form.validateForm()) return;
    if (!profile) {
      toast.error("Faça login para publicar");
      return;
    }

    if (locationError) {
      toast.error(locationError);
      return;
    }

    if (!resolvedLocationId) {
      toast.error("Erro ao resolver localização");
      return;
    }

    setPublishing(true);
    try {
      const data = form.getFormData();

      // SPRINT 2 FASE 3: Usar createPost() com location_id
      await postService.createPost({
        author_profile_id: profile.id,
        content: data.content,
        type: data.type,
        location_id: resolvedLocationId,
        reach: data.reach,
        images: data.images,
      });

      toast.success("Post publicado!");
      form.resetForm();
      onClose();
    } catch (error: unknown) {
      const errorCode =
        typeof error === "object" &&
        error !== null &&
        "code" in error &&
        typeof (error as { code?: unknown }).code === "string"
          ? (error as { code: string }).code
          : null;
      // Tratar erros específicos do service
      if (errorCode === "INVALID_LOCATION_TYPE") {
        toast.error("Esta localização não permite criação de posts");
      } else if (errorCode === "INACTIVE_LOCATION") {
        toast.error("Localização inativa");
      } else {
        toast.error("Erro ao publicar");
      }
    } finally {
      setPublishing(false);
    }
  };

  const handleClose = () => {
    form.resetForm();
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[540px] bg-card border-border p-0 gap-0 overflow-hidden">
        {/* Header */}
        <DialogHeader className="px-5 py-4 border-b border-border bg-card">
          <DialogTitle className="text-base font-semibold text-foreground">
            Criar novo post
          </DialogTitle>
        </DialogHeader>

        {/* Form */}
        <>
          <div className="px-5 py-4 flex flex-col gap-4 max-h-[65vh] overflow-y-auto">
            {/* SPRINT 2 FASE 3: Alerta de bloqueio territorial */}
            {locationError && (
              <Alert variant="destructive" className="border-destructive/50 bg-destructive/10">
                <AlertCircle className="h-4 w-4" />
                <AlertDescription className="text-sm">
                  {locationError}
                </AlertDescription>
              </Alert>
            )}

            {/* Author + autoria explícita */}
            <div className="flex flex-col gap-2">
              <div className="flex items-center gap-3">
                <Avatar className="h-9 w-9 ring-2 ring-border">
                  <AvatarImage src={profile?.avatarUrl} />
                  <AvatarFallback className="bg-primary/20 text-primary text-sm font-semibold">{initials}</AvatarFallback>
                </Avatar>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-foreground">{displayName}</p>
                  <div className="flex items-center gap-1 mt-0.5">
                    {currentReach && (
                      <span className="text-xs text-muted-foreground flex items-center gap-1">
                        <currentReach.icon className="h-3 w-3" />
                        {currentReach.label}
                      </span>
                    )}
                    {currentType && (
                      <>
                        <span className="text-muted-foreground/40 text-xs">·</span>
                        <span className={cn("text-xs", currentType.color)}>{currentType.label}</span>
                      </>
                    )}
                  </div>
                </div>
              </div>
              {/* Badge de autoria - visível quando não é o perfil personal padrão */}
              {effectiveProfile && effectiveProfile.profile_type !== "personal" && (
                <ActiveProfileBadge profile={effectiveProfile} action="publicando como" />
              )}
            </div>

            {/* Textarea */}
            <div className="relative">
              <Textarea
                placeholder="No que você está pensando?"
                value={form.content}
                onChange={(e) => form.setContent(e.target.value)}
                className="min-h-[120px] resize-none bg-background border-border text-foreground placeholder:text-muted-foreground/40 focus-visible:ring-1 text-sm leading-relaxed"
                maxLength={2000}
              />
              <span className={cn("absolute bottom-2 right-3 text-[10px] tabular-nums", charColor)}>
                {form.characterCount}/2000
              </span>
            </div>

            {/* Type grid */}
            <div>
              <p className="text-xs text-muted-foreground/70 mb-2 font-medium uppercase tracking-wide text-[10px]">Tipo de post</p>
              <div className="grid grid-cols-3 gap-1.5">
                {POST_TYPES.map((t) => {
                  const Icon = t.icon;
                  const active = form.type === t.value;
                  return (
                    <Tooltip key={t.value}>
                      <TooltipTrigger asChild>
                        <button
                          type="button"
                          onClick={() => form.setType(t.value)}
                          className={cn(
                            "flex flex-col items-center gap-1 p-2.5 rounded-lg border text-xs font-medium transition-all",
                            active
                              ? `border-current bg-current/10 ${t.color}`
                              : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground hover:bg-secondary/50"
                          )}
                        >
                          <Icon className={cn("h-4 w-4", active ? t.color : "")} />
                          {t.label}
                        </button>
                      </TooltipTrigger>
                      <TooltipContent side="bottom" className="text-xs">{t.description}</TooltipContent>
                    </Tooltip>
                  );
                })}
              </div>
            </div>

            {/* Reach pills + media */}
            <div className="flex items-center gap-2 flex-wrap">
              <p className="text-[10px] text-muted-foreground/70 font-medium uppercase tracking-wide">Visível para:</p>
              {REACH_OPTIONS.map((r) => {
                const Icon = r.icon;
                const active = form.reach === r.value;
                return (
                  <Tooltip key={r.value}>
                    <TooltipTrigger asChild>
                      <button
                        type="button"
                        onClick={() => form.setReach(r.value)}
                        className={cn(
                          "flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-xs transition-all",
                          active
                            ? "border-primary bg-primary/10 text-primary"
                            : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground"
                        )}
                      >
                        <Icon className="h-3 w-3" />{r.label}
                      </button>
                    </TooltipTrigger>
                    <TooltipContent side="top" className="text-xs">{r.description}</TooltipContent>
                  </Tooltip>
                );
              })}
              <div className="ml-auto">
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-foreground" onClick={form.handleAddImage} type="button">
                      <Image className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent className="text-xs">Adicionar foto ou vídeo</TooltipContent>
                </Tooltip>
              </div>
            </div>

            {/* Image previews */}
            {form.images.length > 0 && (
              <div className="flex gap-2 flex-wrap">
                {form.images.map((img, i) => (
                  <div key={i} className="relative group">
                    <img src={img} alt="" className="h-16 w-16 object-cover rounded-lg border border-border" />
                    <button
                      type="button"
                      onClick={() => form.handleRemoveImage(i)}
                      className="absolute -top-1.5 -right-1.5 h-5 w-5 rounded-full bg-destructive text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </div>
                ))}
                {form.images.length < 3 && (
                  <button
                    type="button"
                    onClick={form.handleAddImage}
                    className="h-16 w-16 rounded-lg border-2 border-dashed border-border text-muted-foreground hover:border-primary/50 hover:text-primary transition-colors flex items-center justify-center"
                  >
                    <Image className="h-5 w-5" />
                  </button>
                )}
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="px-5 py-3 border-t border-border flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              {locationError
                ? "Localização inválida"
                : form.isValid
                  ? "Pronto para publicar"
                  : `Mínimo 20 caracteres (${Math.max(0, 20 - form.characterCount)} restantes)`}
            </p>
            <div className="flex gap-2">
              <Button variant="ghost" size="sm" onClick={handleClose} className="text-muted-foreground text-xs">
                Cancelar
              </Button>
              <Button
                size="sm"
                onClick={handlePublish}
                disabled={!canPublish}
                className="text-xs font-semibold min-w-[100px] bg-primary hover:bg-primary/90 text-primary-foreground"
              >
                {publishing ? "Publicando..." : "Publicar"}
              </Button>
            </div>
          </div>
        </>

        <input ref={form.fileInputRef} type="file" accept="image/*,video/*" multiple className="hidden" onChange={form.handleFileSelect} />
      </DialogContent>
    </Dialog>
  );
}

/**
 * useRecomendacaoDetail — Hook para detalhes de perguntas e respostas Q&A
 */

import { useState, useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useToast } from "@/shared/hooks/use-toast";
import { useAuth } from "@/core/auth/hooks/useAuth";
import { useAppUrls } from "@/core/routing/hooks/useAppUrls";
import { logger } from "@/shared/utils/logger";
import { CommunityQAService } from "@/core/community/services/CommunityQAService";
import type {
  CommunityQuestion,
  CommunityAnswer,
  MentionResult,
} from "@/core/community/qa-types";

export type Question = CommunityQuestion;
export type Answer = CommunityAnswer;

export function useRecomendacaoDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { toast } = useToast();
  const { user } = useAuth();
  const appUrls = useAppUrls();

  const [question, setQuestion] = useState<CommunityQuestion | null>(null);
  const [answers, setAnswers] = useState<CommunityAnswer[]>([]);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);

  const [answerText, setAnswerText] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const [mentionSearch, setMentionSearch] = useState("");
  const [mentionResults, setMentionResults] = useState<MentionResult[]>([]);
  const [selectedPro, setSelectedPro] = useState<string | null>(null);
  const [selectedBiz, setSelectedBiz] = useState<string | null>(null);
  const [showMention, setShowMention] = useState(false);

  const loadQuestion = useCallback(async () => {
    if (!id) return;
    const questionData = await CommunityQAService.getQuestionById(id);
    if (!questionData) {
      setNotFound(true);
      setLoading(false);
      return;
    }
    setQuestion(questionData);
    await loadAnswers();
    setLoading(false);
  }, [id]);

  useEffect(() => {
    loadQuestion();
  }, [loadQuestion]);

  const loadAnswers = async () => {
    if (!id) return;
    const answersData = await CommunityQAService.getAnswersByQuestionId(id, user?.id);
    setAnswers(answersData);
  };

  const submitAnswer = async (): Promise<boolean> => {
    if (!user) {
      toast({ title: "Faça login para responder", variant: "destructive" });
      navigate(appUrls.auth.login);
      return false;
    }
    if (!answerText.trim()) return false;

    setSubmitting(true);
    try {
      const newAnswer = await CommunityQAService.createAnswer({
        question_id: id!,
        autor_id: user.id,
        texto: answerText.trim(),
        professional_id: selectedPro || null,
        business_id: selectedBiz || null,
      });
      if (!newAnswer) throw new Error("Failed to create answer");
      setAnswerText("");
      setSelectedPro(null);
      setSelectedBiz(null);
      setShowMention(false);
      toast({ title: "Resposta enviada!" });
      await loadAnswers();
      return true;
    } catch (error) {
      logger.error("Error submitting answer:", error);
      toast({ title: "Erro ao responder", variant: "destructive" });
      return false;
    } finally {
      setSubmitting(false);
    }
  };

  const toggleLike = async (answerId: string) => {
    if (!user) {
      toast({ title: "Faça login para curtir", variant: "destructive" });
      return;
    }
    const result = await CommunityQAService.toggleAnswerLike(answerId, user.id);
    if (result) {
      setAnswers((prev) =>
        prev.map((a) =>
          a.id === answerId
            ? { ...a, liked: result.liked, curtidas: result.newCount }
            : a,
        ),
      );
    }
  };

  const markBestAnswer = async (answerId: string) => {
    if (!user || question?.autor_id !== user.id) return;
    const success = await CommunityQAService.markBestAnswer(id!, answerId);
    if (success) {
      toast({ title: "Melhor resposta marcada!" });
      loadQuestion();
    }
  };

  const searchMentions = async (query: string) => {
    setMentionSearch(query);
    if (query.length < 2) { setMentionResults([]); return; }
    const results = await CommunityQAService.searchMentions(query);
    setMentionResults(results);
  };

  const selectMention = (result: MentionResult) => {
    if (result.type === "professional") {
      setSelectedPro(result.id);
      setSelectedBiz(null);
    } else {
      setSelectedBiz(result.id);
      setSelectedPro(null);
    }
    setShowMention(false);
    setMentionSearch("");
    setMentionResults([]);
  };

  const clearMention = () => { setSelectedPro(null); setSelectedBiz(null); };
  const handleGoBack = () => navigate(-1);
  const isAuthor = user?.id === question?.autor_id;

  return {
    question, answers, loading, notFound, user,
    answerText, setAnswerText, submitting,
    mentionSearch, mentionResults, selectedPro, selectedBiz, showMention, setShowMention,
    isAuthor,
    submitAnswer, toggleLike, markBestAnswer, searchMentions, selectMention, clearMention, handleGoBack,
  };
}

/**
 * useRecomendacoes — Hook para listar perguntas Q&A
 *
 * Q&A é territorial: filtra por location_id ou location_ids.
 * Usa useTerritoryFilter para resolver o território ativo.
 */

import { useEffect, useCallback, useRef } from "react";
import {
  useInfiniteScroll,
  usePaginatedState,
} from "@/shared/hooks/useInfiniteScroll";
import { CommunityQAService } from "@/core/community/services/CommunityQAService";
import {
  territoryFilterKey,
  useTerritoryFilter,
} from "@/core/location/hooks/useTerritoryFilter";
import type { CommunityQuestion, QuestionFilters } from "@/core/community/qa-types";
import type { ResolvedTerritory } from "@/core/routing/hooks/useResolveTerritoryFromUrl";
import type { TerritoryFilter } from "@/core/location";

export type QuestionItem = CommunityQuestion;

interface UseRecomendacoesProps {
  filter?: string;
  search?: string;
  routeResolved?: ResolvedTerritory | null;
  activeMemberIds?: string[];
  territoryFilter?: TerritoryFilter;
}

export function useRecomendacoes({
  filter = "todos",
  search = "",
  routeResolved,
  activeMemberIds,
  territoryFilter,
}: UseRecomendacoesProps = {}) {
  const {
    items: questions,
    page,
    hasMore,
    loading,
    initialLoading,
    setLoading,
    setInitialLoading,
    appendItems,
    nextPage,
    reset,
    PAGE_SIZE,
  } = usePaginatedState<CommunityQuestion>();

  // Filtro territorial canônico — suporta location e group
  const routeTerritoryFilter = useTerritoryFilter(routeResolved, activeMemberIds);
  const activeTerritoryFilter = territoryFilter ?? routeTerritoryFilter;
  const activeTerritoryFilterKey = territoryFilterKey(activeTerritoryFilter);
  const activeTerritoryFilterRef = useRef(activeTerritoryFilter);

  useEffect(() => {
    activeTerritoryFilterRef.current = activeTerritoryFilter;
  }, [activeTerritoryFilterKey, activeTerritoryFilter]);

  const fetchPage = useCallback(
    async (pageNum: number) => {
      const resolvedTerritoryFilter = activeTerritoryFilterRef.current;

      // Não buscar sem território resolvido
      if (resolvedTerritoryFilter.scope === 'none') {
        setInitialLoading(false);
        return;
      }

      setLoading(true);
      const from = pageNum * PAGE_SIZE;

      const filters: QuestionFilters = {
        category: filter !== "todos" ? filter : undefined,
        limit: PAGE_SIZE,
        offset: from,
        // Filtro territorial
        ...(resolvedTerritoryFilter.scope === 'location'
          ? { location_id: resolvedTerritoryFilter.location_id }
          : { location_ids: resolvedTerritoryFilter.location_ids }),
      };

      const data = await CommunityQAService.getQuestions(filters);
      appendItems(data, pageNum === 0);

      setLoading(false);
      setInitialLoading(false);
    },
    [filter, PAGE_SIZE, activeTerritoryFilterKey, setLoading, setInitialLoading, appendItems],
  );

  useEffect(() => {
    reset();
    fetchPage(0);
  }, [reset, fetchPage]);

  useEffect(() => {
    if (page > 0) fetchPage(page);
  }, [page, fetchPage]);

  const { sentinelRef } = useInfiniteScroll({
    hasMore,
    loading,
    onLoadMore: nextPage,
  });

  const filteredQuestions = questions.filter((question) => {
    if (!search) return true;
    const searchLower = search.toLowerCase();
    return (
      question.titulo?.toLowerCase().includes(searchLower) ||
      question.description?.toLowerCase().includes(searchLower)
    );
  });

  return {
    questions: filteredQuestions,
    loading,
    initialLoading,
    hasMore,
    sentinelRef,
    refetch: () => { reset(); fetchPage(0); },
  };
}

import { useState, useEffect, useCallback } from "react";
import type { CommunityPost } from "../types";
import { logger } from "@/shared/utils/logger";
/**
 * Hook profissional para busca de posts
 *
 * Features:
 * - Busca em tempo real com debounce
 * - Filtros: texto, tags, autor, tipo
 * - Histórico de buscas
 * - Sugestões inteligentes
 * - Performance otimizada
 */

interface SearchFilters {
  query: string;
  tags?: string[];
  author?: string;
  type?: string;
  dateRange?: {
    start: Date;
    end: Date;
  };
}

interface SearchResult {
  posts: CommunityPost[];
  total: number;
  suggestions: string[];
}

export function useSearch() {
  const [query, setQuery] = useState("");
  const [filters, setFilters] = useState<SearchFilters>({ query: "" });
  const [results, setResults] = useState<SearchResult>({
    posts: [],
    total: 0,
    suggestions: [],
  });
  const [isSearching, setIsSearching] = useState(false);
  const [searchHistory, setSearchHistory] = useState<string[]>([]);

  /**
   * Debounce para evitar buscas excessivas
   */
  const debounce = <T extends (...args: any[]) => any>(
    func: T,
    wait: number,
  ): ((...args: Parameters<T>) => void) => {
    let timeout: NodeJS.Timeout;
    return (...args: Parameters<T>) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => func(...args), wait);
    };
  };

  /**
   * Executa a busca
   */
  const performSearch = async (searchFilters: SearchFilters) => {
    if (!searchFilters.query.trim()) {
      setResults({ posts: [], total: 0, suggestions: [] });
      return;
    }

    setIsSearching(true);

    try {
      // TODO: Implementar chamada à API real do Supabase
      // const response = await searchPosts(searchFilters);

      // Simular delay de rede
      await new Promise((resolve) => setTimeout(resolve, 300));

      // Retornar resultados vazios até implementar busca real
      const mockResults: CommunityPost[] = [];
      const mockSuggestions: string[] = [];

      setResults({
        posts: mockResults,
        total: mockResults.length,
        suggestions: mockSuggestions,
      });

      // Adicionar ao histórico
      if (searchFilters.query.trim()) {
        setSearchHistory((prev) => {
          const newHistory = [
            searchFilters.query,
            ...prev.filter((q) => q !== searchFilters.query),
          ].slice(0, 5); // Manter apenas 5 últimas

          // Salvar no localStorage
          localStorage.setItem("search_history", JSON.stringify(newHistory));
          return newHistory;
        });
      }
    } catch (error) {
      logger.error("Erro na busca:", error);
      setResults({ posts: [], total: 0, suggestions: [] });
    } finally {
      setIsSearching(false);
    }
  };

  /**
   * Busca com debounce
   */
  const debouncedSearch = useCallback(
    debounce((searchFilters: SearchFilters) => {
      performSearch(searchFilters);
    }, 500),
    [],
  );

  /**
   * Atualiza query e dispara busca
   */
  const search = (newQuery: string) => {
    setQuery(newQuery);
    const newFilters = { ...filters, query: newQuery };
    setFilters(newFilters);
    debouncedSearch(newFilters);
  };

  /**
   * Limpa busca
   */
  const clearSearch = () => {
    setQuery("");
    setFilters({ query: "" });
    setResults({ posts: [], total: 0, suggestions: [] });
  };

  /**
   * Remove item do histórico
   */
  const removeFromHistory = (item: string) => {
    setSearchHistory((prev) => {
      const newHistory = prev.filter((q) => q !== item);
      localStorage.setItem("search_history", JSON.stringify(newHistory));
      return newHistory;
    });
  };

  /**
   * Carrega histórico do localStorage
   */
  useEffect(() => {
    const saved = localStorage.getItem("search_history");
    if (saved) {
      try {
        setSearchHistory(JSON.parse(saved));
      } catch (error) {
        logger.error("Error load histórico:", error);
      }
    }
  }, []);

  return {
    query,
    results,
    isSearching,
    searchHistory,
    search,
    clearSearch,
    removeFromHistory,
  };
}

