  );
}

/**
 * TerritorySelectorV2
 * 
 * Seletor com dois modos para usuários cadastrados:
 * - "Meu Bairro": conteúdo filtrado apenas pelo bairro do morador
 * - "Minha Cidade": conteúdo da cidade inteira com filtros por bairro
 * 
 * Visitantes veem apenas modo cidade com filtros públicos.
 * O bairro ativo NUNCA muda para outro bairro que não o do morador.
 */

import { useState, useMemo, useCallback } from 'react';
import { useNavigate, useLocation as useRouterLocation } from 'react-router-dom';
import { MapPin, ChevronDown, Search, X, Home, Building2 } from 'lucide-react';
import { cn } from '@/shared/utils/cn';
import { useSelectorTerritories } from '../hooks/useSelectorTerritories';
import { useUserTerritory } from '../hooks/useUserTerritory';
import { useActiveTerritory } from '../hooks/useActiveTerritory';
import { useFormattedTerritoryLabel } from '../hooks/useFormattedTerritoryLabel';
import { useFriendlyModuleUrls } from '@/core/routing/hooks/useFriendlyModuleUrls';
import { extractRouteContext, geoPathToPublicUrl } from '@/core/routing/utils/territoryUrls';
import { normalizeTerritoryPath } from '@/core/routing/utils/pathNormalization'; // SSOT
import { getContextMessageFromPath } from '@/config/modules';
import { TerritoryButton, type TerritoryButtonData } from './TerritoryButton';
import { LocationType } from '../types';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/shared/components/ui/dialog';
import { ScrollArea } from '@/shared/components/ui/scroll-area';
import { Input } from '@/shared/components/ui/input';

interface TerritorySelectorV2Props {
  compact?: boolean;
}

export function TerritorySelectorV2({
  compact = false,
}: TerritorySelectorV2Props) {
  const [open, setOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const navigate = useNavigate();
  const routerLocation = useRouterLocation();
  const { homeDistrict, homeCity, hasHome } = useUserTerritory();
  const { activeLocation, territoryMode, setTerritoryMode } = useActiveTerritory();
  const { data: selectorTerritories = [] } = useSelectorTerritories();
  const formattedLabel = useFormattedTerritoryLabel();
  const urls = useFriendlyModuleUrls();

  // SSOT: Path canônico do território ativo
  const currentPath = useMemo(() => {
    if (urls.base) return urls.base;
    if (activeLocation) return geoPathToPublicUrl(activeLocation.geographic_path);
    return null;
  }, [urls.base, activeLocation]);

  const contextMessage = getContextMessageFromPath(routerLocation.pathname);

  // Detectar contexto da rota (APENAS módulo)
  const routeContext = useMemo(() => {
    return extractRouteContext(routerLocation.pathname);
  }, [routerLocation.pathname]);

  // Label do modo atual para o trigger
  const modeLabel = useMemo(() => {
    if (!hasHome) return 'Cidade';
    if (territoryMode === 'bairro' && homeDistrict) return 'Meu Bairro';
    return 'Minha Cidade';
  }, [hasHome, territoryMode, homeDistrict]);

  const isAtHome = useMemo(() => {
    if (!homeDistrict || !activeLocation) return false;
    return activeLocation.id === homeDistrict.id;
  }, [homeDistrict, activeLocation]);

  const isAtHomeCity = useMemo(() => {
    if (!homeCity || !activeLocation) return false;
    return activeLocation.id === homeCity.id;
  }, [homeCity, activeLocation]);

  // Handler: selecionar modo bairro
  const handleSelectBairro = useCallback(() => {
    if (!homeDistrict) return;
    const normalizedPath = normalizeTerritoryPath(homeDistrict.path);
    setTerritoryMode('bairro');
    
    let finalPath = normalizedPath;
    if (routeContext.module) {
      finalPath = `/${routeContext.module}${normalizedPath}`;
    }
    navigate(finalPath);
    setOpen(false);
    setSearchQuery('');
  }, [homeDistrict, normalizeTerritoryPath, setTerritoryMode, routeContext, navigate]);

  // Handler: selecionar modo cidade
  const handleSelectCidade = useCallback(() => {
    if (!homeCity) return;
    const normalizedPath = normalizeTerritoryPath(homeCity.path);
    setTerritoryMode('cidade');
    
    let finalPath = normalizedPath;
    if (routeContext.module) {
      finalPath = `/${routeContext.module}${normalizedPath}`;
    }
    navigate(finalPath);
    setOpen(false);
    setSearchQuery('');
  }, [homeCity, normalizeTerritoryPath, setTerritoryMode, routeContext, navigate]);

  // Handler: selecionar outro território (visitantes ou explorar)
  const handleSelect = useCallback((path: string) => {
    let finalPath = path;
    if (routeContext.module) {
      finalPath = `/${routeContext.module}${path}`;
    }
    // Visitantes: sem modo. Cadastrados: força modo cidade ao explorar
    if (hasHome) {
      setTerritoryMode('cidade');
    }
    navigate(finalPath);
    setOpen(false);
    setSearchQuery('');
  }, [navigate, routeContext, hasHome, setTerritoryMode]);

  // Territórios disponíveis para explorar (excluindo bairro/cidade do usuário)
  const availableTerritories = useMemo((): TerritoryButtonData[] => {
    const seenIds = new Set<string>();
    if (homeDistrict) seenIds.add(homeDistrict.id);
    if (homeCity) seenIds.add(homeCity.id);

    return selectorTerritories
      .filter(t => !seenIds.has(t.id))
      .map(t => ({
        id: t.id,
        name: t.name,
        path: normalizeTerritoryPath(t.path),
        description: t.description,
        icon: t.kind === 'location' && t.type === LocationType.CITY ? 'city' as const : 'district' as const,
      }));
  }, [homeDistrict, homeCity, selectorTerritories, normalizeTerritoryPath]);

  // Busca unificada
  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return null;
    const q = searchQuery.toLowerCase();
    const all: TerritoryButtonData[] = [];

    if (homeDistrict && homeDistrict.name.toLowerCase().includes(q)) {
      all.push({
        id: homeDistrict.id,
        name: homeDistrict.name,
        path: normalizeTerritoryPath(homeDistrict.path),
        badge: 'MEU BAIRRO',
        icon: 'home',
      });
    }
    if (homeCity && homeCity.name.toLowerCase().includes(q)) {
      all.push({
        id: homeCity.id,
        name: homeCity.name,
        path: normalizeTerritoryPath(homeCity.path),
        badge: 'MINHA CIDADE',
        icon: 'city',
      });
    }
    availableTerritories.forEach(t => {
      if (t.name.toLowerCase().includes(q)) all.push(t);
    });

    return all;
  }, [searchQuery, homeDistrict, homeCity, availableTerritories, normalizeTerritoryPath]);

  const handleSearchSelection = useCallback((territory: TerritoryButtonData) => {
    if (homeDistrict && territory.id === homeDistrict.id) {
      handleSelectBairro();
      return;
    }

    if (homeCity && territory.id === homeCity.id) {
      handleSelectCidade();
      return;
    }

    handleSelect(territory.path);
  }, [homeDistrict, homeCity, handleSelectBairro, handleSelectCidade, handleSelect]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button
          className={cn(
            "flex items-center gap-2 hover:bg-accent/50 transition-colors text-left rounded-md",
            compact
              ? "px-3 py-1.5 border border-border hover:border-primary/40"
              : "w-full px-4 py-3 border-b border-border"
          )}
        >
          <MapPin
            className={cn(
              "h-4 w-4 flex-shrink-0",
              compact ? "text-primary" : isAtHome ? "text-primary" : "text-muted-foreground"
            )}
          />
          
          {compact ? (
            <div className="flex items-center gap-1.5">
              <div className="flex md:hidden items-center gap-1">
                <span className="text-xs font-semibold text-foreground truncate max-w-[120px]">
                  {formattedLabel.short}
                </span>
                <ChevronDown className="h-3 w-3 text-muted-foreground flex-shrink-0" />
              </div>
              
              <div className="hidden md:flex items-center gap-1.5">
                {contextMessage && (
                  <span className="text-xs text-muted-foreground font-medium">
                    {contextMessage}
                  </span>
                )}
                <span className="text-sm font-bold text-foreground whitespace-nowrap">
                  {formattedLabel.full}
                </span>
                {hasHome && (
                  <span className="text-[10px] text-muted-foreground font-medium px-1.5 py-0.5 bg-accent rounded">
                    {modeLabel}
                  </span>
                )}
                <ChevronDown className="h-3.5 w-3.5 text-muted-foreground flex-shrink-0" />
              </div>
            </div>
          ) : (
            <>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-foreground truncate">
                  {formattedLabel.short}
                </p>
                <p className="text-[10px] text-muted-foreground">
                  {modeLabel}
                </p>
              </div>
              <ChevronDown className="h-3.5 w-3.5 text-muted-foreground flex-shrink-0" />
            </>
          )}
        </button>
      </DialogTrigger>

      <DialogContent className="sm:max-w-md max-h-[85vh] flex flex-col p-0 gap-0">
        <DialogHeader className="px-4 pt-4 pb-2">
          <DialogTitle className="text-base">
            {hasHome ? 'Escolha seu modo' : 'Onde você está?'}
          </DialogTitle>
        </DialogHeader>

        {/* Modo toggle para usuários cadastrados */}
        {hasHome && (
          <div className="px-4 pb-3 space-y-2">
            {/* Modo Bairro */}
            {homeDistrict && (
              <button
                onClick={handleSelectBairro}
                className={cn(
                  "w-full flex items-center gap-3 px-4 py-3 rounded-lg border transition-all text-left",
                  territoryMode === 'bairro' && isAtHome
                    ? "border-primary bg-primary/5 ring-1 ring-primary/20"
                    : "border-border hover:border-primary/40 hover:bg-accent/50"
                )}
              >
                <div className={cn(
                  "flex items-center justify-center h-9 w-9 rounded-full flex-shrink-0",
                  territoryMode === 'bairro' && isAtHome
                    ? "bg-primary/10 text-primary"
                    : "bg-accent text-muted-foreground"
                )}>
                  <Home className="h-4 w-4" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-semibold text-foreground">{homeDistrict.name}</span>
                    <span className="text-[10px] font-bold text-primary uppercase tracking-wider">
                      Meu Bairro
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Apenas conteúdo do seu bairro
                  </p>
                </div>
                {territoryMode === 'bairro' && isAtHome && (
                  <div className="h-2 w-2 rounded-full bg-primary flex-shrink-0" />
                )}
              </button>
            )}

            {/* Modo Cidade */}
            {homeCity && (
              <button
                onClick={handleSelectCidade}
                className={cn(
                  "w-full flex items-center gap-3 px-4 py-3 rounded-lg border transition-all text-left",
                  territoryMode === 'cidade' && isAtHomeCity
                    ? "border-primary bg-primary/5 ring-1 ring-primary/20"
                    : "border-border hover:border-primary/40 hover:bg-accent/50"
                )}
              >
                <div className={cn(
                  "flex items-center justify-center h-9 w-9 rounded-full flex-shrink-0",
                  territoryMode === 'cidade' && isAtHomeCity
                    ? "bg-primary/10 text-primary"
                    : "bg-accent text-muted-foreground"
                )}>
                  <Building2 className="h-4 w-4" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-semibold text-foreground">{homeCity.name}</span>
                    <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
                      Minha Cidade
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Toda a cidade com filtros por bairro
                  </p>
                </div>
                {territoryMode === 'cidade' && isAtHomeCity && (
                  <div className="h-2 w-2 rounded-full bg-primary flex-shrink-0" />
                )}
              </button>
            )}
          </div>
        )}

        {/* Search */}
        <div className="px-4 pb-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              type="text"
              placeholder="Buscar cidade ou bairro..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-9"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>
        </div>

        <ScrollArea className="flex-1 max-h-[60vh]">
          {/* Resultados de Busca */}
          {searchQuery && searchResults && (
            <div className="px-3 pb-4 space-y-2">
              {searchResults.length > 0 ? (
                <>
                  <p className="px-1 py-2 text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">
                    Resultados
                  </p>
                  {searchResults.map(territory => (
                    <TerritoryButton
                      key={territory.id}
                      territory={territory}
                      isActive={currentPath === territory.path}
                      onClick={() => handleSearchSelection(territory)}
                    />
                  ))}
                </>
              ) : (
                <div className="py-8 text-center">
                  <p className="text-sm text-muted-foreground">
                    Nenhum resultado para "{searchQuery}"
                  </p>
                </div>
              )}
            </div>
          )}

          {/* Territórios disponíveis (quando não busca) */}
          {!searchQuery && availableTerritories.length > 0 && (
            <div className="px-3 pb-4 space-y-3">
              <div className="flex items-center gap-3">
                <div className="flex-1 h-px bg-border" />
                <span className="text-[10px] text-muted-foreground uppercase tracking-wider">
                  {hasHome ? 'Explorar outros locais' : 'Territórios disponíveis'}
                </span>
                <div className="flex-1 h-px bg-border" />
              </div>

              {availableTerritories.map(territory => (
                <TerritoryButton
                  key={territory.id}
                  territory={territory}
                  isActive={currentPath === territory.path}
                  onClick={() => handleSelect(territory.path)}
                />
              ))}

              <div className="px-2 pt-2">
                <p className="text-[10px] text-muted-foreground text-center">
                  Em breve em mais cidades e bairros do Brasil
                </p>
              </div>
            </div>
          )}
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

/**
 * useMapClustering - Hook para clustering de marcadores no mapa
 * 
 * Gerencia clustering automático baseado em zoom e viewport.
 * 
 * @module core/maps/hooks
 */

import { useMemo, useEffect, useRef } from 'react';
import { clusteringService } from '../services/ClusteringService';
import type { MapMarker, BoundingBox } from '../types/core';
import type { ClusterPoint } from '../services/ClusteringService';

export interface UseMapClusteringOptions {
  markers: MapMarker[];
  bounds: BoundingBox | null;
  zoom: number;
  enabled?: boolean;
  radius?: number;
  maxZoom?: number;
  minPoints?: number;
}

export interface UseMapClusteringResult {
  clusters: ClusterPoint[];
  isReady: boolean;
}

/**
 * Hook para clustering de marcadores no mapa
 * 
 * @example
 * ```tsx
 * const { clusters, isReady } = useMapClustering({
 *   markers: allMarkers,
 *   bounds: mapBounds,
 *   zoom: mapZoom,
 *   enabled: true
 * });
 * 
 * // Renderizar clusters no mapa
 * clusters.forEach(cluster => {
 *   if (cluster.properties.cluster) {
 *     // Renderizar cluster
 *     renderCluster(cluster);
 *   } else {
 *     // Renderizar marcador individual
 *     renderMarker(cluster.properties.marker);
 *   }
 * });
 * ```
 */
export function useMapClustering(options: UseMapClusteringOptions): UseMapClusteringResult {
  const {
    markers,
    bounds,
    zoom,
    enabled = true,
    radius = 60,
    maxZoom = 16,
    minPoints = 2,
  } = options;

  const isInitialized = useRef(false);

  // Carregar marcadores no clustering quando mudarem
  useEffect(() => {
    if (!enabled || markers.length === 0) {
      clusteringService.clear();
      isInitialized.current = false;
      return;
    }

    clusteringService.load(markers, {
      radius,
      maxZoom,
      minPoints,
    });

    isInitialized.current = true;
  }, [markers, enabled, radius, maxZoom, minPoints]);

  // Obter clusters para o viewport atual
  const clusters = useMemo(() => {
    if (!enabled || !isInitialized.current || !bounds) {
      // Retornar marcadores individuais sem clustering
      // ✅ SSOT: Filtrar marcadores com coordenadas válidas
      return markers
        .filter((marker) => marker?.coordinates?.longitude != null && marker?.coordinates?.latitude != null)
        .map((marker, index) => ({
          type: 'Feature' as const,
          id: index,
          properties: {
            cluster: false,
            marker,
          },
          geometry: {
            type: 'Point' as const,
            coordinates: [
              marker.coordinates.longitude,
              marker.coordinates.latitude,
            ] as [number, number],
          },
        }));
    }

    return clusteringService.getClusters(bounds, zoom);
  }, [enabled, bounds, zoom, markers, isInitialized.current]);

  return {
    clusters,
    isReady: isInitialized.current,
  };
}

/**
 * TerritorialLayout
 *
 * Layout base para rotas territoriais.
 * Resolve o território a partir da URL, gerencia estados e
 * expõe identidade territorial + navegação de módulos.
 *
 * Etapa 8: expõe groupAvailability no contexto do Outlet e exibe
 * banner de cobertura parcial quando availability === 'partial'.
 */

import { Loader2, AlertTriangle } from 'lucide-react';
import { Outlet, useOutletContext, useParams, useLocation } from 'react-router-dom';
import { useEffect } from 'react';
import { useResolveTerritoryFromUrl } from '../hooks/useResolveTerritoryFromUrl';
import { TerritorialNotFound } from './TerritorialNotFound';
import { TerritorialSEO } from '../seo/TerritorialSEO';
import { MODULE_SLUGS, isEntityDetailRoute } from '../utils/territoryUrls';
import { useGroupAvailability } from '@/core/territorial/hooks/useGroupAvailability';
import { ModuleKey } from '@/core/rollout/types';
import { lastTerritoryStore } from '../stores/LastTerritoryStore';
import { TERRITORY_CONFIG } from '@/config/territory';
import { ErrorBoundary } from '@/shared/components/errors/ErrorBoundary';
import type { ResolvedTerritory } from '../hooks/useResolveTerritoryFromUrl';
import type { GroupModuleAvailability } from '@/core/territorial/types';

// ── Contexto do Outlet ───────────────────────────────────────────────────────

export type TerritorialLayoutContext = {
  resolved: ResolvedTerritory;
  /**
   * URL base do território atual, calculada deterministicamente via useParams.
   * Ex: /ba/salvador/nordeste-de-amaralina
   *     /ba/salvador/complexo-do-nordeste-de-amaralina
   *
   * NUNCA depende da ordem dos membros do grupo.
   * Usar este valor em vez de recalcular baseUrl dentro dos filhos.
   */
  baseUrl: string;
  /**
   * Disponibilidade do módulo atual no grupo.
   * Apenas relevante quando resolved.kind === 'group'.
   * Para location, sempre 'full' (rollout é por bairro individual).
   */
  groupAvailability: GroupModuleAvailability;
  /**
   * IDs dos membros do grupo com rollout ativo para o módulo atual.
   * Usar em useTerritoryFilter(resolved, activeMemberIds) para filtrar queries.
   */
  activeMemberIds: string[];
};

export function useTerritorialContext() {
  return useOutletContext<TerritorialLayoutContext>();
}

export function useTerritorialContextOptional() {
  return useOutletContext<TerritorialLayoutContext | null>() ?? null;
}

// ── Mapeamento de slug de módulo para ModuleKey ──────────────────────────────

const SLUG_TO_MODULE_KEY: Record<string, ModuleKey> = {
  [MODULE_SLUGS.community]:   ModuleKey.COMMUNITY,
  [MODULE_SLUGS.business]:    ModuleKey.BUSINESS,
  [MODULE_SLUGS.services]:    ModuleKey.SERVICES,
  [MODULE_SLUGS.classifieds]: ModuleKey.CLASSIFIEDS,
  [MODULE_SLUGS.mobility]:    ModuleKey.MOBILITY,
  [MODULE_SLUGS.gastronomy]:  ModuleKey.GASTRONOMY,
  [MODULE_SLUGS.events]:      ModuleKey.EVENTS,
  [MODULE_SLUGS.jobs]:        ModuleKey.JOBS,
};

function resolveModuleKeyFromSlug(slug: string): ModuleKey | null {
  switch (slug) {
    case MODULE_SLUGS.community:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.community];
    case MODULE_SLUGS.business:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.business];
    case MODULE_SLUGS.services:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.services];
    case MODULE_SLUGS.classifieds:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.classifieds];
    case MODULE_SLUGS.mobility:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.mobility];
    case MODULE_SLUGS.gastronomy:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.gastronomy];
    case MODULE_SLUGS.events:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.events];
    case MODULE_SLUGS.jobs:
      return SLUG_TO_MODULE_KEY[MODULE_SLUGS.jobs];
    default:
      return null;
  }
}

// ── Banner de cobertura parcial ──────────────────────────────────────────────

function PartialCoverageBanner({
  activeCount,
  totalCount,
}: {
  activeCount: number;
  totalCount: number;
}) {
  return (
    <div className="flex items-center gap-2 px-4 py-2 bg-amber-500/10 border-b border-amber-500/20 text-xs text-amber-700 dark:text-amber-400">
      <AlertTriangle className="h-3.5 w-3.5 flex-shrink-0" />
      <span>
        Cobertura parcial — {activeCount} de {totalCount} bairros disponíveis neste módulo.
      </span>
    </div>
  );
}

// ── Banner de módulo indisponível ────────────────────────────────────────────

function UnavailableModuleBanner() {
  return (
    <div className="flex items-center gap-2 px-4 py-3 bg-muted/60 border-b border-border text-xs text-muted-foreground">
      <AlertTriangle className="h-3.5 w-3.5 flex-shrink-0" />
      <span>Este módulo ainda não está disponível neste território.</span>
    </div>
  );
}

// ── Layout principal ─────────────────────────────────────────────────────────

export function TerritorialLayout() {
  const { status, resolved, error } = useResolveTerritoryFromUrl();
  const { pathname } = useLocation();
  const params = useParams<{
    country?: string; state?: string; city?: string;
    groupSlugOrDistrict?: string;
  }>();

  const state = params.state;
  const city = params.city;
  const slug = params.groupSlugOrDistrict;

  const isFriendlyModule = pathname.startsWith('/empresas/') || 
      pathname.startsWith('/servicos/') || 
      pathname.startsWith('/classificados/') ||
      pathname.startsWith('/comunidade/');

  const country = params.country ?? TERRITORY_CONFIG.defaultCountry;

  // Resolve o módulo atual a partir do pathname
  const currentModuleSlug = pathname.split('/').filter(Boolean)[0] ?? '';
  const currentModuleKey = resolveModuleKeyFromSlug(currentModuleSlug);

  // Resolve availability do grupo (só relevante quando resolved.kind === 'group')
  const groupId = resolved?.kind === 'group' ? resolved.group.id : null;
  const { availability, active_member_ids, result: availabilityResult, isLoading: availabilityLoading } = useGroupAvailability(
    groupId,
    currentModuleKey,
  );

  // baseUrl = landing do território (sem módulo)
  // SSOT: usa geographic_path da location resolvida, não os params da URL
  const baseUrl = resolved
    ? resolved.kind === 'group'
      ? (() => {
          // Para grupo: pega a cidade âncora do primeiro membro
          const firstMember = resolved.group.members[0];
          if (!firstMember?.geographic_path) return `/${state}/${city}/${resolved.group.slug}`;
          const parts = firstMember.geographic_path.split('/').filter(Boolean);
          return `/${parts[1]}/${parts[2]}/${resolved.group.slug}`;
        })()
      : (() => {
          // Para location: usa geographic_path removendo /br
          const parts = resolved.location.geographic_path.split('/').filter(Boolean);
          return '/' + parts.slice(1).join('/');
        })()
    : slug
      ? `/${state}/${city}/${slug}`
      : `/${state}/${city}`;

  const territoryName = resolved
    ? resolved.kind === 'group'
      ? resolved.group.name
      : resolved.location.name
    : '';

  // Persiste o território resolvido para uso fora das rotas territoriais (header, sidebar)
  // useEffect deve ficar ANTES de qualquer early return — Rules of Hooks
  // 
  useEffect(() => {
    if (status === 'resolved_location' || status === 'resolved_group') {
      if (territoryName && baseUrl && !isEntityDetailRoute(pathname)) {
        lastTerritoryStore.set({ name: territoryName, baseUrl });
      }
    }
  }, [status, territoryName, baseUrl, pathname]);

  if (status === 'idle' || status === 'loading') {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  if (status === 'not_found') {
    return <TerritorialNotFound message={error ?? undefined} />;
  }

  if (status === 'inactive') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-2 p-8 text-center">
        <p className="text-lg font-medium">Território inativo</p>
        <p className="text-sm text-muted-foreground max-w-sm">
          {error ?? 'Este território não está disponível no momento.'}
        </p>
      </div>
    );
  }

  if (status === 'restricted') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-4 p-8 text-center">
        <div className="bg-amber-500/10 border border-amber-500/20 rounded-full p-4">
          <AlertTriangle className="h-12 w-12 text-amber-600 dark:text-amber-500" />
        </div>
        <div className="space-y-2 max-w-md">
          <p className="text-xl font-semibold text-foreground">Território indisponível</p>
          <p className="text-sm text-muted-foreground leading-relaxed">
            {error ?? 'Este território não está disponível para navegação pública no momento.'}
          </p>
          <p className="text-xs text-muted-foreground mt-4">
            Você pode voltar ou navegar para a visão mais ampla da cidade.
          </p>
        </div>
        <div className="flex gap-3 mt-4">
          <button
            onClick={() => window.history.back()}
            className="px-4 py-2 text-sm font-medium text-muted-foreground hover:text-foreground border border-border rounded-lg hover:bg-muted/50 transition-colors"
          >
            Voltar
          </button>
          <button
            onClick={() => window.location.href = `/${state}/${city}`}
            className="px-4 py-2 text-sm font-medium text-primary-foreground bg-primary hover:bg-primary/90 rounded-lg transition-colors"
          >
            Ver Cidade Completa
          </button>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    // Render outlet anyway so pages with mock data can still render
    const fallbackContext: TerritorialLayoutContext = {
      resolved: resolved as any,
      baseUrl,
      groupAvailability: 'full',
      activeMemberIds: [],
    };
    return (
      <ErrorBoundary>
        <Outlet context={fallbackContext} />
      </ErrorBoundary>
    );
  }

  // Para location, availability é sempre 'full' (rollout é por bairro individual)
  const effectiveAvailability: GroupModuleAvailability =
    resolved?.kind === 'group' ? availability : 'full';

  const outletContext: TerritorialLayoutContext = {
    resolved,
    baseUrl,
    groupAvailability: effectiveAvailability,
    activeMemberIds: resolved?.kind === 'group' ? active_member_ids : [],
  };

  return (
    <>
      <TerritorialSEO resolved={resolved} baseUrl={baseUrl} />

      {/* Banners de disponibilidade — apenas em contexto de grupo */}
      {resolved?.kind === 'group' && currentModuleKey && (
        <>
          {effectiveAvailability === 'partial' && availabilityResult && (
            <PartialCoverageBanner
              activeCount={availabilityResult.active_module_members}
              totalCount={availabilityResult.total_active_members}
            />
          )}
          {effectiveAvailability === 'none' && !availabilityLoading && <UnavailableModuleBanner />}
        </>
      )}

      <ErrorBoundary>
        <Outlet context={outletContext} />
      </ErrorBoundary>
    </>
  );
}

/**
 * useResolveTerritoryFromUrl
 *
 * Resolve o território ativo a partir dos params da URL.
 *
 * Padrões suportados:
 *   FORMATO LEGADO:
 *   /:country/:state/:city/:district        → Location (district)
 *   /:country/:state/:city/:groupSlug       → TerritorialGroup
 *   
 *   FORMATO AMIGÁVEL (URLs reais, não redirects):
 *   /empresas/:state/:city/:district?       → Location (infere country='br')
 *   /servicos/:state/:city/:district?       → Location (infere country='br')
 *   /classificados/:state/:city/:district?  → Location (infere country='br')
 *   /comunidade/:state/:city/:district?     → Location (infere country='br')
 *
 * Comportamento:
 *   - Sem fallback hardcoded
 *   - Inexistente → status 'not_found'
 *   - Inativo     → status 'inactive'
 *   - Location resolvida → grava no locationContextStore
 *   - Group resolvido    → retorna como dado, NÃO grava no ActiveTerritory (Etapa 3)
 */

import { useEffect, useState } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import { createLocationRepository } from '@/core/location/repositories/createLocationRepository';
import { createTerritorialGroupRepository } from '@/core/location/repositories/createTerritorialGroupRepository';
import { locationContextStore } from '@/core/location/stores/LocationContextStore';
import { TERRITORY_CONFIG } from '@/config/territory';
import type { Location, TerritorialGroupWithMembers } from '@/core/location';
import { isTerritoryPubliclyNavigable } from '../utils/territoryVisibility';

export const TERRITORY_RESOLVE_STATUS = {
  IDLE: 'idle',
  LOADING: 'loading',
  RESOLVED_LOCATION: 'resolved_location',
  RESOLVED_GROUP: 'resolved_group',
  NOT_FOUND: 'not_found',
  INACTIVE: 'inactive',
  RESTRICTED: 'restricted',
  ERROR: 'error',
} as const;

export type TerritoryResolveStatus =
  (typeof TERRITORY_RESOLVE_STATUS)[keyof typeof TERRITORY_RESOLVE_STATUS];

export type ResolvedTerritory =
  | { kind: 'location'; location: Location }
  | { kind: 'group'; group: TerritorialGroupWithMembers }
  | null;

export interface TerritoryResolveResult {
  status: TerritoryResolveStatus;
  resolved: ResolvedTerritory;
  error: string | null;
}

export function useResolveTerritoryFromUrl(): TerritoryResolveResult {
  const location = useLocation();
  const params = useParams<{
    country?: string;
    state?: string;
    city?: string;
    groupSlugOrDistrict?: string;
    district?: string; // ✅ Suporte para rotas de módulo que usam :district
  }>();

  const pathname = location.pathname;
  const state = params.state;
  const city = params.city;
  // slug único: pode ser bairro ou grupo — resolvido pelo banco
  // Prioridade: district (rotas de módulo) > groupSlugOrDistrict (rotas territoriais)
  // "_" é tratado como placeholder para "sem distrito" (resolve apenas cidade)
  let slug = params.district || params.groupSlugOrDistrict;
  if (slug === '_') slug = undefined; // Placeholder para "sem distrito"
  
  // HACK: Para rotas do módulo guide com 3 segmentos, se o slug não for encontrado
  // como distrito/grupo, devemos resolver apenas a cidade (não retornar not_found)
  const isGuideRoute = pathname.startsWith('/pontos-turisticos/') || pathname.startsWith('/guia/pontos-turisticos/');

  const country = params.country ?? TERRITORY_CONFIG.defaultCountry;

  const [result, setResult] = useState<TerritoryResolveResult>({
    status: TERRITORY_RESOLVE_STATUS.IDLE,
    resolved: null,
    error: null,
  });

  useEffect(() => {
    if (!country || !state || !city) return;

    let cancelled = false;
    setResult({ status: TERRITORY_RESOLVE_STATUS.LOADING, resolved: null, error: null });

    async function resolve() {
      try {
        const locationRepo = createLocationRepository();

        const cityPath = `/${country}/${state}/${city}`;
        const cityLocation = await locationRepo.findByPath(cityPath);

        if (!cityLocation) {
          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.NOT_FOUND, resolved: null, error: `Cidade não encontrada: ${cityPath}` });
          return;
        }

        // --- Sem slug: resolve cidade ---
        if (!slug) {
          if (cityLocation.status !== 'active') {
            if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.INACTIVE, resolved: null, error: `Cidade inativa: ${cityLocation.name}` });
            return;
          }
          if (!isTerritoryPubliclyNavigable(cityLocation.metadata)) {
            if (!cancelled) {
              setResult({
                status: TERRITORY_RESOLVE_STATUS.RESTRICTED,
                resolved: null,
                error: `${cityLocation.name} não está disponível para navegação pública no momento.`,
              });
            }
            return;
          }
          // ✅ NÃO define território ativo automaticamente - deixa TerritoryModeInitializer gerenciar
          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.RESOLVED_LOCATION, resolved: { kind: 'location', location: cityLocation }, error: null });
          return;
        }

        // --- Com slug: tenta grupo primeiro, depois bairro ---
        const groupRepo = createTerritorialGroupRepository();
        const group = await groupRepo.findBySlugAndCity(slug, cityLocation.id);

        if (group) {
          // É um grupo territorial
          if (group.status !== 'active') {
            if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.INACTIVE, resolved: null, error: `Grupo inativo: ${group.name}` });
            return;
          }
          
          // URL pública respeita apenas flag de navegação, não visibilidade do seletor.
          const isPubliclyNavigable = isTerritoryPubliclyNavigable(group.metadata);

          if (!isPubliclyNavigable) {
            if (!cancelled) setResult({ 
              status: TERRITORY_RESOLVE_STATUS.RESTRICTED, 
              resolved: null, 
              error: `${group.name} não está disponível para navegação pública no momento.` 
            });
            return;
          }
          
          const withMembers = await groupRepo.findWithMembers(group.id);
          if (!withMembers) {
            if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.NOT_FOUND, resolved: null, error: `Grupo sem membros: ${slug}` });
            return;
          }
          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.RESOLVED_GROUP, resolved: { kind: 'group', group: withMembers }, error: null });
          return;
        }

        if (!isTerritoryPubliclyNavigable(cityLocation.metadata)) {
          if (!cancelled) {
            setResult({
              status: TERRITORY_RESOLVE_STATUS.RESTRICTED,
              resolved: null,
              error: `${cityLocation.name} não está disponível para navegação pública no momento.`,
            });
          }
          return;
        }

        // É um bairro (district)
        const districtPath = `${cityPath}/${slug}`;
        const districtLocation = await locationRepo.findByPath(districtPath);

        if (!districtLocation) {
          // Para rotas do módulo guide, se não encontrar distrito/grupo,
          // resolve apenas a cidade (assume que o slug é de um ponto turístico)
          if (isGuideRoute) {
            if (cityLocation.status !== 'active') {
              if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.INACTIVE, resolved: null, error: `Cidade inativa: ${cityLocation.name}` });
              return;
            }
            if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.RESOLVED_LOCATION, resolved: { kind: 'location', location: cityLocation }, error: null });
            return;
          }

          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.NOT_FOUND, resolved: null, error: `Local não encontrado: ${districtPath}` });
          return;
        }

        if (districtLocation.status !== 'active') {
          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.INACTIVE, resolved: null, error: `Bairro inativo: ${districtLocation.name}` });
          return;
        }

        if (districtLocation.parent_id !== cityLocation.id) {
          if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.NOT_FOUND, resolved: null, error: `Bairro ${slug} não pertence a ${city}` });
          return;
        }

        // URL pública respeita flag de navegação; seletor não deve bloquear deep-link.
        const isPubliclyNavigable = isTerritoryPubliclyNavigable(
          districtLocation.metadata,
        );

        if (!isPubliclyNavigable) {
          if (!cancelled) setResult({ 
            status: TERRITORY_RESOLVE_STATUS.RESTRICTED, 
            resolved: null, 
            error: `${districtLocation.name} não está disponível para navegação pública no momento.` 
          });
          return;
        }

        // ✅ NÃO define território ativo automaticamente - deixa TerritoryModeInitializer gerenciar
        if (!cancelled) setResult({ status: TERRITORY_RESOLVE_STATUS.RESOLVED_LOCATION, resolved: { kind: 'location', location: districtLocation }, error: null });

      } catch (err) {
        if (!cancelled) {
          setResult({ status: TERRITORY_RESOLVE_STATUS.ERROR, resolved: null, error: err instanceof Error ? err.message : 'Erro desconhecido' });
        }
      }
    }

    resolve();
    return () => { cancelled = true; };
  }, [country, state, city, slug]);

  return result;
}

import { logger } from '@/shared/utils/logger';
import React, { createContext, useState, useEffect } from "react";
import { SessionState } from "../state/SessionState";
import { SessionService } from "../services/SessionService";
import type { SessionContext } from "../types";
/**
 * SessionReactContext - The React context object.
 * Exported so useSessionContext.ts can import it.
 *
 * NOTE: The TypeScript interface `SessionContext` (from ../types) and this
 * context object are intentionally named differently to avoid collision.
 */
export const SessionReactContext = createContext<SessionContext | undefined>(
  undefined,
);
/**
 * SessionProvider - React provider that reads from SessionState (SSOT).
 *
 * On mount:
 *  1. Calls SessionService.initialize() to set up onAuthStateChange.
 *  2. Subscribes to SessionState changes so the provider re-renders on updates.
 *  3. Calls SessionService.initializeSession() to load the initial session.
 *
 * Exposes async handlers (switchProfile, refreshSession) that manage
 * isLoading and error state.
 *
 * Does NOT export useSessionContext — that lives in hooks/useSessionContext.ts.
 */
export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [sessionData, setSessionData] = useState(() => SessionState.getState());
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    // Subscreve ANTES de inicializar para não perder nenhum evento
    const unsubscribe = SessionState.subscribe(() => {
      setSessionData(SessionState.getState());
    });

    // Registra onAuthStateChange — isso dispara INITIAL_SESSION/SIGNED_IN automaticamente
    // O SessionService atualiza o SessionState via subscribe acima
    SessionService.initialize();

    // Aguarda o primeiro evento de auth para liberar o isLoading
    // Timeout de segurança caso o SDK não dispare nenhum evento
    const timeout = setTimeout(() => {
      logger.warn("⚠️ SessionProvider: auth init timeout — liberando UI");
      setIsLoading(false);
    }, 3000);

    SessionService.initializeSession().then(() => {
      clearTimeout(timeout);
      setSessionData(SessionState.getState());
      setIsLoading(false);
    }).catch(() => {
      clearTimeout(timeout);
      setIsLoading(false);
    });

    return () => {
      clearTimeout(timeout);
      unsubscribe();
      // Cleanup do auth listener para evitar memory leaks
      SessionService.cleanup();
    };
  }, []);

  // 6.6 / 6.7 switchProfile handler with isLoading + error management
  const switchProfile = async (profileId: string): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);
      await SessionService.switchProfile(profileId);
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  // 6.6 / 6.7 refreshSession handler with isLoading + error management
  const refreshSession = async (): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);
      await SessionService.refreshSession();
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setIsLoading(false);
    }
  };

  const value: SessionContext = {
    user: sessionData.user,
    activeProfile: sessionData.activeProfile,
    profiles: sessionData.profiles,
    isLoading,
    error,
    switchProfile,
    refreshSession,
  };

  return (
    <SessionReactContext.Provider value={value}>
      {children}
    </SessionReactContext.Provider>
  );
}

/**
 * DistrictSelector
 *
 * Seletor de bairros canônicos para grupos territoriais.
 * Leitura via useLocationOptions (LocationRepository) — sem query direta.
 *
 * Regras:
 * - Apenas locations.type = 'district', status = 'active'
 * - Apenas bairros da cidade âncora selecionada
 * - Sem input manual de texto
 * - Multiselect com busca
 */

import { useState, useEffect } from 'react';
import { Input } from '@/shared/components/ui/input';
import { Checkbox } from '@/shared/components/ui/checkbox';
import { Badge } from '@/shared/components/ui/badge';
import { Button } from '@/shared/components/ui/button';
import { Search, MapPin, Loader2 } from 'lucide-react';
import { useCities, useDistricts } from '../hooks/useLocationOptions';

interface DistrictSelectorProps {
  anchorCityId: string;
  onAnchorCityChange: (cityId: string) => void;
  selectedDistricts: string[];
  onDistrictsChange: (districtIds: string[]) => void;
  disabled?: boolean;
}

export function DistrictSelector({
  anchorCityId,
  onAnchorCityChange,
  selectedDistricts,
  onDistrictsChange,
  disabled,
}: DistrictSelectorProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [showOnlySelected, setShowOnlySelected] = useState(false);

  const { data: cities = [], isLoading: loadingCities } = useCities();
  const { data: districts = [], isLoading: loadingDistricts } = useDistricts(anchorCityId || undefined);

  const filtered = districts.filter((d) => {
    const matchesSearch =
      d.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.slug.toLowerCase().includes(searchTerm.toLowerCase());
    
    if (showOnlySelected) {
      return matchesSearch && selectedDistricts.includes(d.id);
    }
    
    return matchesSearch;
  });

  // Ao trocar cidade, descartar seleções que não pertencem à nova cidade
  useEffect(() => {
    if (!anchorCityId || selectedDistricts.length === 0) return;
    const validIds = new Set(districts.map((d) => d.id));
    const kept = selectedDistricts.filter((id) => validIds.has(id));
    if (kept.length !== selectedDistricts.length) onDistrictsChange(kept);
  }, [anchorCityId, districts]);

  const toggle = (id: string) =>
    onDistrictsChange(
      selectedDistricts.includes(id)
        ? selectedDistricts.filter((x) => x !== id)
        : [...selectedDistricts, id],
    );

  return (
    <div className="space-y-5">
      {/* Cidade âncora */}
      <div className="space-y-2">
        <label className="text-sm font-medium block">Cidade Âncora</label>
        {loadingCities ? (
          <div className="flex items-center gap-2 text-sm text-muted-foreground py-3 px-4 border border-border rounded-lg bg-muted/20">
            <Loader2 className="h-4 w-4 animate-spin" /> Carregando cidades...
          </div>
        ) : (
          <>
            <select
              value={anchorCityId}
              onChange={(e) => onAnchorCityChange(e.target.value)}
              disabled={disabled}
              className="w-full px-4 py-2.5 border border-border rounded-lg bg-background text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all"
            >
              <option value="">Selecione uma cidade</option>
              {cities.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name}
                </option>
              ))}
            </select>
            <p className="text-xs text-muted-foreground">
              Apenas bairros desta cidade poderão ser selecionados
            </p>
          </>
        )}
      </div>

      {/* Bairros */}
      {anchorCityId && (
        <div>
          <div className="flex items-center justify-between mb-3">
            <label className="text-sm font-medium">
              Bairros Membros
            </label>
            <Badge variant="secondary" className="text-xs">
              {selectedDistricts.length} de {districts.length} selecionados
            </Badge>
          </div>

          {/* Barra de ações */}
          <div className="flex items-center gap-2 mb-3">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Buscar bairro..."
                className="pl-9 h-9"
                disabled={disabled}
              />
            </div>
            <label
              className={`flex items-center gap-2 h-9 px-3 rounded-md border transition-colors cursor-pointer ${
                showOnlySelected 
                  ? 'bg-primary text-primary-foreground border-primary' 
                  : 'bg-background border-border hover:bg-accent'
              } ${disabled || selectedDistricts.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <Checkbox 
                checked={showOnlySelected} 
                onCheckedChange={() => !disabled && selectedDistricts.length > 0 && setShowOnlySelected(!showOnlySelected)}
                disabled={disabled || selectedDistricts.length === 0}
                className="pointer-events-none"
              />
              <span className="text-sm whitespace-nowrap">Apenas selecionados</span>
            </label>
          </div>

          {/* Ações rápidas */}
          <div className="flex gap-2 mb-3">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="text-xs h-7 flex-1"
              disabled={disabled || filtered.length === 0}
              onClick={() => {
                const allFilteredIds = filtered.map((d) => d.id);
                const newSelection = [...new Set([...selectedDistricts, ...allFilteredIds])];
                onDistrictsChange(newSelection);
              }}
            >
              Selecionar {showOnlySelected ? 'filtrados' : 'todos'}
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="text-xs h-7 flex-1"
              disabled={disabled || selectedDistricts.length === 0}
              onClick={() => onDistrictsChange([])}
            >
              Limpar seleção
            </Button>
          </div>

          {loadingDistricts ? (
            <div className="flex items-center justify-center py-12 text-sm text-muted-foreground border border-border rounded-lg bg-muted/20">
              <Loader2 className="h-5 w-5 animate-spin mr-2" /> Carregando bairros...
            </div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-12 border border-border rounded-lg bg-muted/20">
              <MapPin className="h-8 w-8 text-muted-foreground mx-auto mb-2 opacity-50" />
              <p className="text-sm text-muted-foreground">
                {searchTerm 
                  ? 'Nenhum bairro encontrado com esse termo' 
                  : showOnlySelected
                  ? 'Nenhum bairro selecionado ainda'
                  : 'Nenhum bairro disponível nesta cidade'}
              </p>
            </div>
          ) : (
            <div className="border border-border rounded-lg max-h-80 overflow-y-auto bg-card">
              <div className="divide-y divide-border">
                {filtered.map((d) => {
                  const isSelected = selectedDistricts.includes(d.id);
                  return (
                    <label
                      key={d.id}
                      className={`flex items-center gap-3 px-4 py-3 hover:bg-accent/50 cursor-pointer transition-colors ${
                        isSelected ? 'bg-primary/5' : ''
                      }`}
                    >
                      <Checkbox
                        checked={isSelected}
                        onCheckedChange={() => toggle(d.id)}
                        disabled={disabled}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-medium truncate">{d.name}</span>
                          {isSelected && (
                            <Badge variant="secondary" className="text-[10px] px-1.5 py-0">
                              ✓
                            </Badge>
                          )}
                        </div>
                        <span className="text-xs text-muted-foreground truncate block font-mono">
                          {d.slug}
                        </span>
                      </div>
                      <MapPin className={`h-4 w-4 shrink-0 ${isSelected ? 'text-primary' : 'text-muted-foreground'}`} />
                    </label>
                  );
                })}
              </div>
            </div>
          )}

          <div className="mt-3 p-3 bg-muted/30 rounded-lg border border-border">
            <p className="text-xs text-muted-foreground">
              💡 Dica: Use o filtro "Apenas selecionados" para revisar os bairros já adicionados ao grupo
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

﻿import React from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { TrendIndicator, TrendData } from "./TrendIndicator";
