                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-xs leading-relaxed line-clamp-2">
                            {item.label}
                          </p>
                          <span className="text-[10px] text-muted-foreground">
                            {formatRelative(item.date)}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useSessionContext } from "@/core/session";
import { AuthorizationEngine } from "@/core/authorization";
import { Input } from "@/shared/components/ui/input";
import { Loader2, Search, Shield } from "lucide-react";
import { Badge } from "@/shared/components/ui/badge";
import { USER_ROLE } from "@/shared/types/constants";
import { useModeration } from "@/modules/admin/hooks/useModeration";
import { useModerationFilters } from "@/modules/admin/hooks/useModerationFilters";
import { ModerationTabs } from "@/modules/admin/components/moderation/ModerationTabs";
import { StatusFilter } from "@/modules/admin/components/moderation/StatusFilter";
import { ReportCard } from "@/modules/admin/components/moderation/ReportCard";
import { WarningCard } from "@/modules/admin/components/moderation/WarningCard";
import { AuditLogCard } from "@/modules/admin/components/moderation/AuditLogCard";
import { ReportDetailDialog } from "@/modules/admin/components/moderation/ReportDetailDialog";
import { WarnUserDialog } from "@/modules/admin/components/moderation/WarnUserDialog";

export default function AdminModeracao() {
  const { activeProfile } = useSessionContext();
  const [canModerate, setCanModerate] = useState<boolean | null>(null);

  const {
    loading,
    postReports,
    commentReports,
    profileReports,
    warnings,
    auditLogs,
    getProfile,
    getPost,
    getComment,
    handleReportAction,
    handleDeleteContent,
    handleWarnUser,
  } = useModeration();

  const {
    tab,
    search,
    reportFilter,
    setTab,
    setSearch,
    setReportFilter,
    filterReports,
    filterWarnings,
    filterLogs,
  } = useModerationFilters();

  const [selectedReport, setSelectedReport] = useState<any>(null);
  const [reportType, setReportType] = useState<"post" | "comment" | "profile">(
    "post",
  );
  const [actionLoading, setActionLoading] = useState(false);

  const [warnDialog, setWarnDialog] = useState<{
    userId: string;
    userName: string;
  } | null>(null);

  // Check moderation permission via AuthorizationEngine
  useEffect(() => {
    if (!activeProfile) {
      setCanModerate(false);
      return;
    }
    AuthorizationEngine.canProfilePerformAction(
      activeProfile.id,
      "moderateContent",
      {},
    ).then(setCanModerate);
  }, [activeProfile?.id]);

  // Validação de admin
  if (canModerate === false) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-red-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Acesso Negado</h1>
          <p className="text-gray-400">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  const postReportsPending = postReports.filter(
    (r) => r.status === "pendente",
  ).length;
  const commentReportsPending = commentReports.filter(
    (r) => r.status === "pendente",
  ).length;
  const profileReportsPending = profileReports.filter(
    (r) => r.status === "pendente",
  ).length;
  const totalPending =
    postReportsPending + commentReportsPending + profileReportsPending;

  const currentReports =
    tab === "posts"
      ? postReports
      : tab === "comments"
        ? commentReports
        : tab === "profiles"
          ? profileReports
          : [];

  const filteredReports = filterReports(
    currentReports,
    tab,
    getPost,
    getComment,
    getProfile,
  );
  const filteredWarningsList = filterWarnings(warnings, getProfile);
  const filteredLogsList = filterLogs(auditLogs);

  const handleReportView = (
    report: any,
    type: "post" | "comment" | "profile",
  ) => {
    setSelectedReport(report);
    setReportType(type);
  };

  const handleReportActionWrapper = async (
    reportId: string,
    table: string,
    status: string,
    notes: string,
  ) => {
    setActionLoading(true);
    const success = await handleReportAction(reportId, table, status, notes);
    setActionLoading(false);
    return success;
  };

  const handleDeleteWrapper = async (
    type: "post" | "comment",
    id: string,
    report: any,
    notes: string,
  ) => {
    setActionLoading(true);
    const success = await handleDeleteContent(type, id, report, notes);
    setActionLoading(false);
    return success;
  };

  const handleWarnWrapper = async (
    userId: string,
    type: "advertencia" | "suspensao_7d" | "suspensao_permanente",
    motivo: string,
  ) => {
    setActionLoading(true);
    const success = await handleWarnUser(userId, type, motivo);
    setActionLoading(false);
    return success;
  };

  const getReportContent = () => {
    if (!selectedReport) return { content: null, author: null, table: "" };

    let content: any = null;
    let authorProfileId: string | null = null;
    const table =
      reportType === "post"
        ? "posts"
        : reportType === "comment"
          ? "comments"
          : "profiles";

    if (reportType === "post") {
      content = getPost(selectedReport.post_id);
      authorProfileId = content?.autor_id;
    } else if (reportType === "comment") {
      content = getComment(selectedReport.comment_id);
      authorProfileId = content?.autor_id;
    } else {
      content = getProfile(selectedReport.profile_id);
      authorProfileId = selectedReport.profile_id;
    }

    const author = authorProfileId ? getProfile(authorProfileId) : null;

    return { content, author, table };
  };

  const { content, author, table } = getReportContent();

  return (
    <div>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
        <div>
          <h1 className="text-2xl font-bold font-display">Moderação</h1>
          <p className="text-sm text-muted-foreground">
            Gerencie conteúdo e denúncias da comunidade
          </p>
        </div>
        {totalPending > 0 && (
          <Badge variant="destructive" className="self-start">
            {totalPending} pendente{totalPending > 1 ? "s" : ""}
          </Badge>
        )}
      </div>

      <ModerationTabs
        currentTab={tab}
        postReportsPending={postReportsPending}
        commentReportsPending={commentReportsPending}
        profileReportsPending={profileReportsPending}
        warningsCount={warnings.length}
        onTabChange={setTab}
      />

      {(tab === "posts" ||
        tab === "comments" ||
        tab === "profiles") && (
        <StatusFilter
          currentFilter={reportFilter}
          onFilterChange={setReportFilter}
        />
      )}

      <div className="relative mb-4">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <Input
          placeholder="Buscar..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="pl-9 h-9"
        />
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : tab === "posts" ||
        tab === "comments" ||
        tab === "profiles" ? (
        <div className="space-y-2">
          {filteredReports.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-12">
              Nenhuma denúncia encontrada.
            </p>
          ) : (
            filteredReports.map((r) => {
              let content: any = null;
              let authorProfileId: string | null = null;

              if (tab === "posts") {
                content = getPost(r.post_id);
                authorProfileId = content?.autor_id;
              } else if (tab === "comments") {
                content = getComment(r.comment_id);
                authorProfileId = content?.autor_id;
              } else if (tab === "profiles") {
                content = getProfile(r.profile_id);
                authorProfileId = r.profile_id;
              }

              const author = authorProfileId
                ? getProfile(authorProfileId)
                : null;

              return (
                <ReportCard
                  key={r.id}
                  report={r}
                  content={content}
                  author={author}
                  type={
                    tab === "posts"
                      ? "post"
                      : tab === "comments"
                        ? "comment"
                        : "profile"
                  }
                  onView={() =>
                    handleReportView(
                      r,
                      tab === "posts"
                        ? "post"
                        : tab === "comments"
                          ? "comment"
                          : "profile",
                    )
                  }
                />
              );
            })
          )}
        </div>
      ) : tab === "warnings" ? (
        <div className="space-y-2">
          {filteredWarningsList.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-12">
              Nenhuma advertência registrada.
            </p>
          ) : (
            filteredWarningsList.map((w) => (
              <WarningCard
                key={w.id}
                warning={w}
                targetUser={getProfile(w.user_id)}
                adminUser={getProfile(w.admin_id)}
              />
            ))
          )}
        </div>
      ) : (
        <div className="space-y-2">
          {filteredLogsList.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-12">
              Nenhum registro de auditoria.
            </p>
          ) : (
            filteredLogsList.map((l) => (
              <AuditLogCard
                key={l.id}
                log={l}
                adminUser={getProfile(l.admin_id)}
              />
            ))
          )}
        </div>
      )}

      <ReportDetailDialog
        report={selectedReport}
        content={content}
        author={author}
        type={reportType}
        table={table}
        isOpen={!!selectedReport}
        isLoading={actionLoading}
        onClose={() => setSelectedReport(null)}
        onAction={handleReportActionWrapper}
        onDelete={handleDeleteWrapper}
        onWarn={(userId, userName) => setWarnDialog({ userId, userName })}
      />

      <WarnUserDialog
        isOpen={!!warnDialog}
        userId={warnDialog?.userId || ""}
        userName={warnDialog?.userName || ""}
        isLoading={actionLoading}
        onClose={() => setWarnDialog(null)}
        onWarn={handleWarnWrapper}
      />
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useSessionContext } from "@/core/session";
import { ModerationService } from "@/core/moderation/services/ModerationService";
import { adminCommunityService } from "@/core/admin";
import type { ModerationStats, CommunityPost, PostFlag } from "@/core/admin";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import {
  Shield,
  Flag,
  CheckCircle2,
  XCircle,
  Trash2,
  Eye,
  AlertTriangle,
  Clock,
  TrendingUp,
  Users,
  MessageSquare,
  RefreshCw,
  Filter,
} from "lucide-react";
import { cn } from "@/shared/utils/cn";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/shared/components/ui/dialog";
import { Textarea } from "@/shared/components/ui/textarea";
import { Label } from "@/shared/components/ui/label";
import { RIDE_STATUS, USER_ROLE } from "@/shared/types/constants";
import { logger } from "@/shared/utils/logger";

type FilterStatus = "all" | "pending" | "flagged" | "approved" | "rejected";
type ModerationAction = "approve" | "reject" | "flag" | "delete";

const statusConfig = {
  pending: {
    label: "Pendente",
    color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
    icon: Clock,
  },
  approved: {
    label: "Aprovado",
    color: "bg-green-500/20 text-green-400 border-green-500/30",
    icon: CheckCircle2,
  },
  rejected: {
    label: "Rejeitado",
    color: "bg-red-500/20 text-red-400 border-red-500/30",
    icon: XCircle,
  },
  flagged: {
    label: "Denunciado",
    color: "bg-orange-500/20 text-orange-400 border-orange-500/30",
    icon: Flag,
  },
};

const flagReasons = {
  spam: "Spam",
  inappropriate: "Conteúdo Inapropriado",
  fake: "Informação Falsa",
  offensive: "Ofensivo",
  other: "Outro",
};

export default function AdminModeracaoComunidade() {
  const { user } = useSessionContext();
  const [stats, setStats] = useState<ModerationStats | null>(null);
  const [posts, setPosts] = useState<CommunityPost[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<FilterStatus>("all");

  // Modal de ação
  const [actionModal, setActionModal] = useState<{
    open: boolean;
    post: CommunityPost | null;
    action: ModerationAction | null;
  }>({ open: false, post: null, action: null });
  const [actionReason, setActionReason] = useState("");

  // Modal de detalhes
  const [detailsModal, setDetailsModal] = useState<{
    open: boolean;
    post: CommunityPost | null;
    flags: PostFlag[];
  }>({ open: false, post: null, flags: [] });

  // Buscar estatísticas
  const fetchStats = async () => {
    const data = await adminCommunityService.getModerationStats();
    if (data) {
      setStats(data);
    }
  };

  // Buscar postagens
  const fetchPosts = async () => {
    try {
      setLoading(true);

      const filterValue =
        filter === "all"
          ? undefined
          : (filter as "pending" | "approved" | "rejected" | "flagged");
      const data = await adminCommunityService.getCommunityPosts(filterValue);
      setPosts(data);
    } catch (err) {
      logger.error("Erro ao buscar postagens:", err);
      toast.error("Erro ao carregar postagens");
    } finally {
      setLoading(false);
    }
  };

  // Buscar denúncias de uma postagem
  const fetchFlags = async (postId: string): Promise<PostFlag[]> => {
    try {
      return await adminCommunityService.getPostFlags(postId);
    } catch (error) {
      logger.error("Erro ao buscar denúncias:", error);
      return [];
    }
  };

  // Executar ação de moderação
  const executeAction = async () => {
    if (!actionModal.post || !actionModal.action || !user) return;

    try {
      await ModerationService.moderatePost(
        actionModal.post.id,
        user.id,
        actionModal.action,
        actionReason || undefined,
      );

      toast.success(
        `Postagem ${actionModal.action === "approve" ? "aprovada" : actionModal.action === "reject" ? "rejeitada" : actionModal.action === "delete" ? "deletada" : "marcada"}!`,
      );

      setActionModal({ open: false, post: null, action: null });
      setActionReason("");

      fetchPosts();
      fetchStats();
    } catch (err) {
      logger.error("Erro ao moderar:", err);
      toast.error("Erro ao executar ação");
    }
  };

  // Abrir modal de detalhes
  const openDetails = async (post: CommunityPost) => {
    const flags = await fetchFlags(post.id);
    setDetailsModal({ open: true, post, flags });
  };

  useEffect(() => {
    fetchStats();
    fetchPosts();
  }, [filter]);

  // Verificar se é admin
  if (!user) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-red-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Acesso Negado</h1>
          <p className="text-gray-400">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0A0F14] p-4 md:p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
              <Shield className="h-6 w-6 text-teal-400" />
              Moderação da Comunidade
            </h1>
            <p className="text-sm text-gray-400 mt-1">
              Gerencie postagens e denúncias do feed da comunidade
            </p>
          </div>
          <Button
            size="sm"
            onClick={() => {
              fetchPosts();
              fetchStats();
            }}
            className="bg-white/10 text-white hover:bg-white/20"
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Atualizar
          </Button>
        </div>

        {/* Stats */}
        {stats && (
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-3">
            <StatCard
              label="Total"
              value={stats.total_posts}
              icon={MessageSquare}
              color="text-gray-400"
            />
            <StatCard
              label="Pendentes"
              value={stats.pending_posts}
              icon={Clock}
              color="text-yellow-400"
            />
            <StatCard
              label="Aprovados"
              value={stats.approved_posts}
              icon={CheckCircle2}
              color="text-green-400"
            />
            <StatCard
              label="Rejeitados"
              value={stats.rejected_posts}
              icon={XCircle}
              color="text-red-400"
            />
            <StatCard
              label="Denunciados"
              value={stats.flagged_posts}
              icon={Flag}
              color="text-orange-400"
            />
            <StatCard
              label="Denúncias"
              value={stats.total_flags}
              icon={AlertTriangle}
              color="text-amber-400"
            />
            <StatCard
              label="Com Denúncias"
              value={stats.posts_with_flags}
              icon={TrendingUp}
              color="text-purple-400"
            />
          </div>
        )}

        {/* Filters */}
        <div className="flex items-center gap-2 overflow-x-auto pb-2">
          {[
            { key: "all", label: "Todos", count: stats?.total_posts || 0 },
            {
              key: RIDE_STATUS.PENDING,
              label: "Pendentes",
              count: stats?.pending_posts || 0,
            },
            {
              key: "flagged",
              label: "Denunciados",
              count: stats?.flagged_posts || 0,
            },
            {
              key: "approved",
              label: "Aprovados",
              count: stats?.approved_posts || 0,
            },
            {
              key: "rejected",
              label: "Rejeitados",
              count: stats?.rejected_posts || 0,
            },
          ].map((f) => (
            <button
              key={f.key}
              onClick={() => setFilter(f.key as FilterStatus)}
              className={cn(
                "flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold transition-all whitespace-nowrap",
                filter === f.key
                  ? "bg-teal-500 text-white"
                  : "bg-white/5 text-gray-400 hover:bg-white/10",
              )}
            >
              {f.label}
              <span className="px-2 py-0.5 rounded-full bg-white/10 text-xs">
                {f.count}
              </span>
            </button>
          ))}
        </div>

        {/* Posts List */}
        {loading ? (
          <div className="text-center py-12">
            <RefreshCw className="h-8 w-8 text-teal-400 animate-spin mx-auto mb-3" />
            <p className="text-gray-400">Carregando postagens...</p>
          </div>
        ) : posts.length === 0 ? (
          <div className="text-center py-12">
            <MessageSquare className="h-12 w-12 text-gray-600 mx-auto mb-3" />
            <p className="text-gray-400">Nenhuma postagem encontrada</p>
          </div>
        ) : (
          <div className="space-y-3">
            {posts.map((post) => (
              <PostCard
                key={post.id}
                post={post}
                onAction={(action) =>
                  setActionModal({ open: true, post, action })
                }
                onDetails={() => openDetails(post)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Action Modal */}
      <Dialog
        open={actionModal.open}
        onOpenChange={(open) =>
          !open && setActionModal({ open: false, post: null, action: null })
        }
      >
        <DialogContent className="bg-[#1E2529] border-white/10 text-white">
          <DialogHeader>
            <DialogTitle>
              {actionModal.action === "approve" && "✅ Aprovar Postagem"}
              {actionModal.action === "reject" && "❌ Rejeitar Postagem"}
              {actionModal.action === "flag" && "🚩 Marcar Postagem"}
              {actionModal.action === "delete" && "🗑️ Deletar Postagem"}
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              {actionModal.post?.content}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3">
            <div>
              <Label className="text-xs text-gray-400">Motivo (opcional)</Label>
              <Textarea
                value={actionReason}
                onChange={(e) => setActionReason(e.target.value)}
                placeholder="Descreva o motivo da ação..."
                className="bg-white/5 border-white/10 text-white mt-1"
                rows={3}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() =>
                setActionModal({ open: false, post: null, action: null })
              }
              className="border-white/10 text-gray-400"
            >
              Cancelar
            </Button>
            <Button
              onClick={executeAction}
              className={cn(
                "text-white",
                actionModal.action === "approve" &&
                  "bg-green-500 hover:bg-green-600",
                actionModal.action === "reject" &&
                  "bg-red-500 hover:bg-red-600",
                actionModal.action === "flag" &&
                  "bg-orange-500 hover:bg-orange-600",
                actionModal.action === "delete" &&
                  "bg-red-600 hover:bg-red-700",
              )}
            >
              Confirmar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Details Modal */}
      <Dialog
        open={detailsModal.open}
        onOpenChange={(open) =>
          !open && setDetailsModal({ open: false, post: null, flags: [] })
        }
      >
        <DialogContent className="bg-[#1E2529] border-white/10 text-white max-w-2xl">
          <DialogHeader>
            <DialogTitle>Detalhes da Postagem</DialogTitle>
          </DialogHeader>
          <DialogDescription className="sr-only">
            Moderar conteúdo da comunidade
          </DialogDescription>

          {detailsModal.post && (
            <div className="space-y-4">
              <div>
                <p className="text-sm text-gray-400">Conteúdo:</p>
                <p className="text-white mt-1">{detailsModal.post.content}</p>
              </div>

              <div className="grid grid-cols-2 gap-3 text-sm">
                <div>
                  <p className="text-gray-400">Autor:</p>
                  <p className="text-white">{detailsModal.post.author_name}</p>
                </div>
                <div>
                  <p className="text-gray-400">Bairro:</p>
                  <p className="text-white">
                    {detailsModal.post.author_neighborhood}
                  </p>
                </div>
                <div>
                  <p className="text-gray-400">Destino:</p>
                  <p className="text-white">{detailsModal.post.destination}</p>
                </div>
                <div>
                  <p className="text-gray-400">Interessados:</p>
                  <p className="text-white">
                    {detailsModal.post.interested_count}
                  </p>
                </div>
              </div>

              {detailsModal.flags.length > 0 && (
                <div>
                  <p className="text-sm font-semibold text-white mb-2">
                    Denúncias ({detailsModal.flags.length})
                  </p>
                  <div className="space-y-2">
                    {detailsModal.flags.map((flag) => (
                      <div
                        key={flag.id}
                        className="p-3 rounded-lg bg-white/5 border border-white/10"
                      >
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-xs font-semibold text-orange-400">
                            {
                              flagReasons[
                                flag.reason as keyof typeof flagReasons
                              ]
                            }
                          </span>
                          <span className="text-xs text-gray-500">
                            {new Date(flag.created_at).toLocaleDateString(
                              "pt-BR",
                            )}
                          </span>
                        </div>
                        <p className="text-xs text-gray-400">
                          Por: {flag.flagged_by_name}
                        </p>
                        {flag.description && (
                          <p className="text-xs text-gray-300 mt-1">
                            {flag.description}
                          </p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StatCard({
  label,
  value,
  icon: Icon,
  color,
}: {
  label: string;
  value: number;
  icon: any;
  color: string;
}) {
  return (
    <div className="p-4 rounded-xl bg-white/5 border border-white/10">
      <div className="flex items-center justify-between mb-2">
        <Icon className={cn("h-4 w-4", color)} />
        <span className="text-2xl font-bold text-white">{value}</span>
      </div>
      <p className="text-xs text-gray-400">{label}</p>
    </div>
  );
}

function PostCard({
  post,
  onAction,
  onDetails,
}: {
  post: CommunityPost;
  onAction: (action: ModerationAction) => void;
  onDetails: () => void;
}) {
  const config = statusConfig[post.moderation_status];
  const StatusIcon = config.icon;

  return (
    <div className="p-4 rounded-xl bg-white/5 border border-white/10 hover:border-white/20 transition-all">
      <div className="flex items-start gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-2">
            <Badge className={cn("text-xs border", config.color)}>
              <StatusIcon className="h-3 w-3 mr-1" />
              {config.label}
            </Badge>
            {post.flag_count > 0 && (
              <Badge className="text-xs bg-orange-500/20 text-orange-400 border-orange-500/30">
                <Flag className="h-3 w-3 mr-1" />
                {post.flag_count} denúncia{post.flag_count > 1 ? "s" : ""}
              </Badge>
            )}
            <span className="text-xs text-gray-500">
              {new Date(post.created_at).toLocaleString("pt-BR")}
            </span>
          </div>

          <p className="text-sm text-white mb-2">{post.content}</p>

          <div className="flex items-center gap-4 text-xs text-gray-400">
            <span>👤 {post.author_name}</span>
            <span>📍 {post.destination}</span>
            <span>❤️ {post.interested_count} interessados</span>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={onDetails}
            className="h-8 w-8 p-0 text-gray-400 hover:text-white"
          >
            <Eye className="h-4 w-4" />
          </Button>
          {post.moderation_status !== "approved" && (
            <Button
              size="sm"
              onClick={() => onAction("approve")}
              className="h-8 bg-green-500/20 text-green-400 hover:bg-green-500/30"
            >
              <CheckCircle2 className="h-4 w-4" />
            </Button>
          )}
          {post.moderation_status !== "rejected" && (
            <Button
              size="sm"
              onClick={() => onAction("reject")}
              className="h-8 bg-red-500/20 text-red-400 hover:bg-red-500/30"
            >
              <XCircle className="h-4 w-4" />
            </Button>
          )}
          <Button
            size="sm"
            onClick={() => onAction("delete")}
            className="h-8 bg-red-600/20 text-red-400 hover:bg-red-600/30"
          >
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import {
  AlertCircle,
  ArrowRight,
  Car,
  CheckCircle2,
  Database,
  Loader2,
  RefreshCw,
  Settings2,
  Shield,
} from "lucide-react";
import {
  AdminDataState,
  AdminErrorState,
  AdminPageHeader,
  AdminSectionCard,
  AdminStatsCard,
  AdminStatsGrid,
  AdminTable,
} from "@/modules/admin/components";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Label } from "@/shared/components/ui/label";
import { Switch } from "@/shared/components/ui/switch";
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/components/ui/table";
import { useToast } from "@/shared/hooks/use-toast";
import { useAdminGuard } from "@/modules/admin/hooks/useAdminGuard";
import { useLocationContext } from "@/core/location";
import { mobilityRolloutService } from "@/shared/services/mobilityAdmin";
import { RolloutSource, RolloutStatus } from "@/core/rollout/types";
import {
  operationalDiagnosticsService,
  type OperationalTable,
  type OperationalTableResult,
} from "@/modules/admin/services";
import { logger } from "@/shared/utils/logger";

const RUNTIME_CHECK_TABLES: OperationalTable[] = [
  { table: "module_rollouts", label: "Rollout de modulos", required: true },
  { table: "locations", label: "Hierarquia territorial", required: true },
  { table: "driver_profiles", label: "Cadastros de motoristas", required: true },
  { table: "driver_data", label: "Status operacional de motoristas", required: true },
  { table: "ride_requests", label: "Corridas e entregas", required: true },
  { table: "ride_reports", label: "Reports de corrida", required: true },
  { table: "driver_moderation_events", label: "Historico de moderacao de motoristas", required: true },
  { table: "pricing_rules", label: "Regras de pricing", required: false },
];

const OPTIONAL_NOT_PROVISIONED: OperationalTableResult[] = [
  {
    table: "pickup_points",
    label: "Pontos de embarque",
    required: false,
    state: "not_provisioned",
    detail: "Modulo opcional nao provisionado neste schema",
  },
];

const QUICK_TOOLS = [
  { label: "Gestao de Motoristas", to: "/admin/motoristas" },
  { label: "Operacoes Motoboy", to: "/admin/motoboy-operacoes" },
  { label: "Identidade", to: "/admin/identidade" },
  { label: "Mapa", to: "/admin/mapa" },
  { label: "Pricing", to: "/admin/pricing" },
  { label: "Territorios", to: "/admin/territory-management" },
  { label: "Locations", to: "/admin/locations" },
  { label: "Notificacoes", to: "/admin/notifications" },
  { label: "Verificacoes", to: "/admin/verificacoes" },
  { label: "Roles e Permissoes", to: "/admin/roles" },
];

function describeRolloutSource(source: RolloutSource | null): string {
  if (source === RolloutSource.LOCAL) return "local";
  if (source === RolloutSource.INHERITED) return "herdado";
  if (source === RolloutSource.DEFAULT) return "padrao";
  return "indefinido";
}

function tableStateBadge(item: OperationalTableResult) {
  if (item.state === "ok") {
    return <Badge className="bg-emerald-600 hover:bg-emerald-600">Disponivel</Badge>;
  }

  if (item.state === "missing") {
    return <Badge variant="destructive">Ausente</Badge>;
  }

  if (item.state === "error") {
    return <Badge variant="destructive">Erro</Badge>;
  }

  return <Badge variant="outline">Nao provisionada</Badge>;
}

export default function AdminOperacoes() {
  const { canModerate, isChecking } = useAdminGuard();
  const { toast } = useToast();
  const { activeLocation } = useLocationContext();
  const activeLocationId = activeLocation?.id ?? null;

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [moduleEnabled, setModuleEnabled] = useState(false);
  const [motoboyEnabled, setMotoboyEnabled] = useState(false);
  const [source, setSource] = useState<RolloutSource | null>(null);
  const [tableResults, setTableResults] = useState<OperationalTableResult[]>([]);
  const [tableCheckRunning, setTableCheckRunning] = useState(false);
  const [pageError, setPageError] = useState<string | null>(null);
  const [diagnosticsError, setDiagnosticsError] = useState<string | null>(null);

  const requiredTables = useMemo(
    () => tableResults.filter((item) => item.required),
    [tableResults],
  );

  const missingRequiredTables = useMemo(
    () => requiredTables.filter((item) => item.state !== "ok"),
    [requiredTables],
  );

  const optionalTables = useMemo(
    () => tableResults.filter((item) => !item.required),
    [tableResults],
  );

  const loadMobilityState = useCallback(async () => {
    if (!activeLocationId) {
      setModuleEnabled(false);
      setMotoboyEnabled(false);
      setSource(null);
      return;
    }

    const [rollout, motoboy] = await Promise.all([
      mobilityRolloutService.getMobilityRolloutForLocation(activeLocationId),
      mobilityRolloutService.isMotoboyEnabled(activeLocationId),
    ]);

    setModuleEnabled(rollout?.status === RolloutStatus.ACTIVE);
    setMotoboyEnabled(motoboy);
    setSource(rollout?.source ?? null);
  }, [activeLocationId]);

  const checkOperationalTables = useCallback(async () => {
    setTableCheckRunning(true);
    setDiagnosticsError(null);
    try {
      const checks = await operationalDiagnosticsService.checkTables(
        RUNTIME_CHECK_TABLES,
      );

      setTableResults([...checks, ...OPTIONAL_NOT_PROVISIONED]);
    } catch (error) {
      logger.error("AdminOperacoes: erro ao validar tabelas operacionais", error as Error);
      setDiagnosticsError("Nao foi possivel consolidar o diagnostico das tabelas operacionais.");
      toast({
        title: "Falha no diagnostico",
        description: "Nao foi possivel verificar as tabelas operacionais.",
        variant: "destructive",
      });
    } finally {
      setTableCheckRunning(false);
    }
  }, [toast]);

  const refreshAll = useCallback(async () => {
    setIsLoading(true);
    setPageError(null);
    try {
      await Promise.all([loadMobilityState(), checkOperationalTables()]);
    } catch (error) {
      logger.error("AdminOperacoes: erro ao recarregar superficie operacional", error as Error);
      setPageError("Nao foi possivel recarregar os controles operacionais desta superficie.");
      toast({
        title: "Falha ao atualizar",
        description: "Revise a conectividade e tente atualizar novamente.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  }, [checkOperationalTables, loadMobilityState]);

  useEffect(() => {
    if (!isChecking && canModerate) {
      void refreshAll();
    }
  }, [canModerate, isChecking, refreshAll]);

  const saveMobilityControls = async () => {
    if (!activeLocationId) {
      toast({
        title: "Localizacao obrigatoria",
        description: "Selecione uma localizacao ativa para salvar os controles.",
        variant: "destructive",
      });
      return;
    }

    setIsSaving(true);
    try {
      await mobilityRolloutService.setMobilityEnabled(activeLocationId, moduleEnabled);
      await mobilityRolloutService.setMotoboyEnabled(activeLocationId, motoboyEnabled);
      await loadMobilityState();

      toast({
        title: "Operacao salva",
        description: "Controles de mobilidade atualizados com sucesso.",
      });
    } catch (error) {
      logger.error("AdminOperacoes: erro ao salvar controles de mobilidade", error as Error);
      toast({
        title: "Falha ao salvar",
        description: "Nao foi possivel persistir os controles de mobilidade.",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  if (!isChecking && !canModerate) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="mx-auto mb-4 h-16 w-16 text-red-400" />
          <h1 className="mb-2 text-2xl font-bold text-white">Acesso Negado</h1>
          <p className="text-gray-400">Apenas administradores podem acessar esta pagina.</p>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AdminPageHeader
        title="Operacoes do Sistema"
        description="Controles administrativos criticos, rollout de mobilidade e diagnostico de prontidao operacional."
        icon={Settings2}
        actions={
          <Button variant="outline" onClick={refreshAll} disabled={tableCheckRunning || isSaving}>
            {tableCheckRunning ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <RefreshCw className="mr-2 h-4 w-4" />
            )}
            Atualizar
          </Button>
        }
      />

      <AdminStatsGrid>
        <AdminStatsCard
          title="Rollout mobility"
          value={moduleEnabled ? "Ativo" : "Desligado"}
          subtitle={`Fonte: ${describeRolloutSource(source)}`}
          icon={Car}
        />
        <AdminStatsCard
          title="Modo motoboy"
          value={motoboyEnabled ? "Ativo" : "Desligado"}
          subtitle={activeLocation?.name ?? "Nenhuma localizacao ativa"}
          icon={Settings2}
          iconColor="text-sky-600"
        />
        <AdminStatsCard
          title="Tabelas obrigatorias"
          value={`${requiredTables.filter((item) => item.state === "ok").length}/${requiredTables.length || 0}`}
          subtitle={`${missingRequiredTables.length} pendencia(s) critica(s)`}
          icon={Database}
          iconColor={missingRequiredTables.length ? "text-red-600" : "text-emerald-600"}
        />
        <AdminStatsCard
          title="Ferramentas operacionais"
          value={QUICK_TOOLS.length}
          subtitle={`${optionalTables.length} tabela(s) opcional(is) no diagnostico`}
          icon={Shield}
          iconColor="text-violet-600"
        />
      </AdminStatsGrid>

      {pageError ? (
        <AdminErrorState
          title="Falha ao atualizar operacoes do sistema"
          description={pageError}
          onRetry={() => {
            void refreshAll();
          }}
        />
      ) : null}

      <div className="grid gap-4 xl:grid-cols-[minmax(0,2fr),minmax(320px,1fr)]">
        <div className="space-y-4">
          <AdminSectionCard
            title="Mobilidade por localizacao"
            description="Controle oficial do rollout mobility e do modo motoboy no admin."
            icon={Car}
            actions={<Badge variant="outline">{activeLocation?.name ?? "Nenhuma localizacao ativa"}</Badge>}
          >
            <div className="space-y-4">
              <div className="flex items-center justify-between gap-4 rounded-lg border p-4">
                <div>
                  <Label htmlFor="mobility-module-enabled" className="font-semibold">
                    Modulo de mobilidade habilitado
                  </Label>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Fonte atual do rollout: {describeRolloutSource(source)}.
                  </p>
                </div>
                <Switch
                  id="mobility-module-enabled"
                  checked={moduleEnabled}
                  onCheckedChange={setModuleEnabled}
                  disabled={!activeLocationId || isSaving}
                />
              </div>

              <div className="flex items-center justify-between gap-4 rounded-lg border p-4">
                <div>
                  <Label htmlFor="motoboy-mode-enabled" className="font-semibold">
                    Modo motoboy habilitado
                  </Label>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Quando desligado, novas solicitacoes de entrega por motoboy ficam bloqueadas.
                  </p>
                </div>
                <Switch
                  id="motoboy-mode-enabled"
                  checked={motoboyEnabled}
                  onCheckedChange={setMotoboyEnabled}
                  disabled={!activeLocationId || isSaving}
                />
              </div>

              <div className="flex justify-end">
                <Button onClick={saveMobilityControls} disabled={!activeLocationId || isSaving}>
                  {isSaving ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                  Salvar controles
                </Button>
              </div>
            </div>
          </AdminSectionCard>

          <AdminSectionCard
            title="Diagnostico de tabelas operacionais"
            description="Visao objetiva do que esta pronto no banco para administracao do sistema."
            icon={Database}
          >
            {diagnosticsError && !tableResults.length ? (
              <AdminErrorState
                title="Falha ao carregar diagnostico operacional"
                description={diagnosticsError}
                onRetry={() => {
                  void checkOperationalTables();
                }}
              />
            ) : (
              <AdminDataState
                loading={tableCheckRunning && !tableResults.length}
                isEmpty={!tableCheckRunning && !tableResults.length}
                emptyTitle="Sem diagnostico operacional"
                emptyDescription="Nao foi possivel consolidar as tabelas operacionais deste ambiente."
              >
                <div className="space-y-3">
                  {diagnosticsError ? (
                    <AdminErrorState
                      title="Diagnostico parcialmente indisponivel"
                      description={diagnosticsError}
                      onRetry={() => {
                        void checkOperationalTables();
                      }}
                    />
                  ) : null}

                  <AdminTable>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Recurso</TableHead>
                        <TableHead>Detalhe</TableHead>
                        <TableHead>Criticidade</TableHead>
                        <TableHead>Status</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {tableResults.map((item) => (
                        <TableRow key={item.table}>
                          <TableCell className="min-w-[220px]">
                            <div className="space-y-1">
                              <div className="font-medium">{item.label}</div>
                              <div className="font-mono text-[11px] text-muted-foreground">
                                {item.table}
                              </div>
                            </div>
                          </TableCell>
                          <TableCell className="min-w-[320px] text-sm text-muted-foreground">
                            {item.detail ?? "Sem detalhes"}
                          </TableCell>
                          <TableCell>
                            {item.required ? (
                              <Badge variant="secondary">Obrigatoria</Badge>
                            ) : (
                              <Badge variant="outline">Opcional</Badge>
                            )}
                          </TableCell>
                          <TableCell>{tableStateBadge(item)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </AdminTable>

                  {missingRequiredTables.length > 0 ? (
                    <div className="flex gap-2 rounded-lg border border-red-500/30 bg-red-500/5 p-3 text-sm text-red-700 dark:text-red-300">
                      <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
                      <p>
                        Existem tabelas obrigatorias ausentes ou com erro. Corrija o schema antes de considerar o admin operacional em 100%.
                      </p>
                    </div>
                  ) : (
                    <div className="flex gap-2 rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-3 text-sm text-emerald-700 dark:text-emerald-300">
                      <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
                      <p>
                        Infraestrutura minima de operacao administrativa validada para as tabelas obrigatorias.
                      </p>
                    </div>
                  )}
                </div>
              </AdminDataState>
            )}
          </AdminSectionCard>
        </div>

        <div className="space-y-4">
          <AdminSectionCard
            title="Ferramentas administrativas"
            description="Acesso rapido para operacao diaria do sistema."
            icon={Settings2}
          >
            <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-1">
              {QUICK_TOOLS.map((tool) => (
                <Button key={tool.to} variant="outline" className="justify-between" asChild>
                  <Link to={tool.to}>
                    <span>{tool.label}</span>
                    <ArrowRight className="h-4 w-4" />
                  </Link>
                </Button>
              ))}
            </div>
          </AdminSectionCard>

          <AdminSectionCard
            title="Leitura objetiva"
            description="Resumo do estado operacional atual e do que ainda bloqueia prontidao plena."
            icon={Shield}
            contentClassName="space-y-2 text-sm text-muted-foreground"
          >
            <p>
              Esta superficie concentra controles criticos de rollout e diagnostico de schema sem acessar tabelas sensiveis diretamente da page.
            </p>
            <p>
              Ownership canonico: o admin central governa rollout/moderacao/politicas globais; dashboards de negocio e mobilidade permanecem responsaveis por operacao do proprio perfil e execucao diaria.
            </p>
            <p>
              Prontidao total depende de zerar tabelas obrigatorias ausentes ou com erro e consolidar a leitura operacional hoje ainda vinculada a `operationalDiagnosticsService` dentro de `core/admin`.
            </p>
          </AdminSectionCard>
        </div>
      </div>
    </div>
  );
}

import React from "react";

import { useState, useEffect } from "react";
import { toast } from "sonner";
import {
  CheckCircle,
  XCircle,
  Clock,
  Building2,
  User,
  MessageSquare,
  Shield,
} from "lucide-react";
import { adminBusinessService } from "@/core/admin";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import { Card } from "@/shared/components/ui/card";
import { Skeleton } from "@/shared/components/ui/skeleton";
import { obterNicho } from "@/shared/utils/urlUtils";
import { BusinessUrlService } from "@/core/business/services/BusinessUrlService";
import { useAdminGuard } from "@/modules/admin/hooks/useAdminGuard";
import { notificationService, NotificationType, NotificationPriority } from "@/core/notifications";
import { profileService } from "@/core/profiles/services/ProfileService";
import { logger } from "@/shared/utils/logger";

interface Claim {
  id: string;
  user_id: string;
  business_id: string;
  mensagem: string | null;
  status: string;
  created_at: string;
  resolved_at: string | null;
  user_name?: string;
  business_name?: string;
  business_slug?: string;
  business_category?: string;
  business_is_premium?: boolean;
}

export default function AdminReivindicacoes() {
  const { canModerate, isChecking } = useAdminGuard();
  const [claims, setClaims] = useState<Claim[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<
    "pendente" | "aprovada" | "rejeitada" | "todos"
  >("pendente");
  const [processing, setProcessing] = useState<string | null>(null);

  const fetchClaims = async () => {
    setLoading(true);
    const data = await adminBusinessService.getBusinessClaims(
      filter !== "todos" ? filter : undefined,
    );
    if (!data) {
      toast.error("Error load reivindicações");
      setLoading(false);
      return;
    }

    // Enrich with user and business names using ProfileService
    const enriched = await Promise.all(
      (data || []).map(async (claim) => {
        const [profile, biz] = await Promise.all([
          profileService.getProfileById(claim.user_id),
          adminBusinessService.getBusinessClaimDetails(claim.business_id),
        ]);
        return {
          ...claim,
          user_name: profile?.name || "Desconhecido",
          business_name:
            (Array.isArray(biz?.profiles) ? biz.profiles?.[0] : biz?.profiles)
              ?.name || "Removida",
        };
      }),
    );

    setClaims(enriched);
    setLoading(false);
  };

  useEffect(() => {
    if (!isChecking && canModerate) {
      fetchClaims();
    }
  }, [filter, canModerate, isChecking]);

  // Validação de admin
  if (!isChecking && !canModerate) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-red-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Acesso Negado</h1>
          <p className="text-gray-400">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  const handleAction = async (
    claimId: string,
    action: "aprovada" | "rejeitada",
  ) => {
    setProcessing(claimId);
    const claim = claims.find((c) => c.id === claimId);
    if (!claim) return;

    const ok = await adminBusinessService.updateClaimStatus(claimId, action);
    if (!ok) {
      toast.error("Erro ao atualizar reivindicação");
      setProcessing(null);
      return;
    }

    // Gerar URL canônica da business para notificação
    let businessUrl: string | null = null;
    if (claim.business_slug && claim.business_id) {
      try {
        // Buscar business completa para obter dados territoriais reais
        const businessDetails = await adminBusinessService.getBusinessClaimDetails(claim.business_id);
        if (businessDetails?.uf && businessDetails?.city) {
          // Só gerar URL canônica com dados territoriais reais
          businessUrl = BusinessUrlService.getCanonicalUrl({
            slug: claim.business_slug,
            uf: businessDetails.uf,
            city: businessDetails.city,
          });
        }
      } catch (error) {
        // Se falhar, não gerar URL (businessUrl permanece null)
        logger.error("Erro ao buscar dados da business para URL:", error);
      }
    }

    const msg =
      action === "aprovada"
        ? `Sua reivindicação da empresa "${claim.business_name}" foi aprovada!`
        : `Sua reivindicação da empresa "${claim.business_name}" foi rejeitada.`;

    await notificationService.createNotification({
      user_id: claim.user_id,
      type: "system" as const,
      title:
        action === "aprovada"
          ? "✅ Reivindicação aprovada"
          : "❌ Reivindicação rejeitada",
      message: msg,
      priority: "high" as const,
      metadata: businessUrl ? {
        action_url: businessUrl,
        action_label: "Ver empresa",
      } : undefined,
    });

    toast.success(
      action === "aprovada"
        ? "Reivindicação aprovada!"
        : "Reivindicação rejeitada.",
    );
    setProcessing(null);
    fetchClaims();
  };

  const statusBadge = (s: string) => {
    if (s === "aprovada")
      return (
        <Badge className="bg-green-500/15 text-green-600 border-0">
          <CheckCircle className="h-3 w-3 mr-1" />
          Aprovada
        </Badge>
      );
    if (s === "rejeitada")
      return (
        <Badge variant="destructive" className="border-0">
          <XCircle className="h-3 w-3 mr-1" />
          Rejeitada
        </Badge>
      );
    return (
      <Badge variant="secondary">
        <Clock className="h-3 w-3 mr-1" />
        Pendente
      </Badge>
    );
  };

  const pendingCount = claims.filter((c) => c.status === "pendente").length;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-xl font-bold font-display">
          Reivindicações de Empresas
        </h1>
        <p className="text-sm text-muted-foreground">
          Gerencie solicitações de usuários que desejam gerenciar empresas.
        </p>
      </div>

      {/* Filters */}
      <div className="flex gap-2 flex-wrap">
        {(["pendente", "aprovada", "rejeitada", "todos"] as const).map((f) => (
          <Button
            key={f}
            size="sm"
            variant={filter === f ? "default" : "outline"}
            onClick={() => setFilter(f)}
            className="capitalize"
          >
            {f === "pendente" && pendingCount > 0 && filter !== "pendente" && (
              <span className="mr-1.5 h-4 min-w-4 px-1 rounded-full bg-destructive text-destructive-foreground text-[10px] font-bold inline-flex items-center justify-center">
                {pendingCount}
              </span>
            )}
            {f}
          </Button>
        ))}
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-28 w-full rounded-xl" />
          ))}
        </div>
      ) : claims.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <Building2 className="h-10 w-10 mx-auto mb-2 opacity-40" />
          <p className="text-sm">
            Nenhuma reivindicação {filter !== "todos" ? filter : ""} encontrada.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {claims.map((claim) => (
            <Card key={claim.id} className="p-4 space-y-3">
              <div className="flex items-start justify-between gap-3">
                <div className="space-y-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <Building2 className="h-4 w-4 text-primary shrink-0" />
                    <span className="font-semibold text-sm truncate">
                      {claim.business_name}
                    </span>
                    {statusBadge(claim.status)}
                  </div>
                  <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                    <User className="h-3 w-3" />
                    <span>{claim.user_name}</span>
                    <span>·</span>
                    <span>
                      {new Date(claim.created_at).toLocaleDateString("pt-BR")}
                    </span>
                  </div>
                </div>
              </div>

              {claim.mensagem && (
                <div className="flex items-start gap-2 bg-muted/50 rounded-lg p-3">
                  <MessageSquare className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                  <p className="text-xs text-muted-foreground">
                    {claim.mensagem}
                  </p>
                </div>
              )}

              {claim.status === "pendente" && (
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    className="flex-1 gap-1"
                    disabled={processing === claim.id}
                    onClick={() => handleAction(claim.id, "aprovada")}
                  >
                    <CheckCircle className="h-4 w-4" /> Aprovar
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="flex-1 gap-1 text-destructive hover:text-destructive"
                    disabled={processing === claim.id}
                    onClick={() => handleAction(claim.id, "rejeitada")}
                  >
                    <XCircle className="h-4 w-4" /> Rejeitar
                  </Button>
                </div>
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

 
import React from "react";

import { useState, useEffect } from "react";
import { useToast } from "@/shared/hooks/use-toast";
import {
  Check,
  X,
  Trash2,
  Eye,
  Star,
  Search,
  Filter,
  MessageSquare,
  Shield,
} from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Badge } from "@/shared/components/ui/badge";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/shared/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/shared/components/ui/dialog";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/shared/components/ui/avatar";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";
import { adminCommunityService } from "@/core/admin/services/AdminCommunityService";
import { profileService } from "@/core/profiles/services/ProfileService";
import { ProfessionalService } from "@/core/professional/services/ProfessionalService";
import { ReviewsService } from "@/core/reviews/services/ReviewsService";
import { useAdminGuard } from "@/modules/admin/hooks/useAdminGuard";

interface Professional {
  id: string;
  profile_id?: string;
  name: string;
  photo: string;
  service: string;
  category: string;
  neighborhood: string;
  whatsapp: string;
  rating: number;
  total_avaliacoes: number;
  status: string;
  created_at: string;
}

interface Review {
  id: string;
  professional_id: string;
  rating: number;
  comment: string;
  created_at: string;
  reviewer: { name: string; avatar_url: string } | null;
  professional: { name: string } | null;
}

interface Report {
  id: string;
  professional_id: string;
  motivo: string;
  detalhes: string;
  status: string;
  created_at: string;
  professional: { name: string } | null;
}

export default function AdminServicos() {
  const { canModerate, isChecking } = useAdminGuard();
  const { toast } = useToast();
  const [professionals, setProfessionals] = useState<Professional[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [reports, setReports] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState("todos");
  const [selectedPro, setSelectedPro] = useState<Professional | null>(null);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{
    type: "professional" | "review";
    id: string;
  } | null>(null);

  const loadData = async () => {
    setLoading(true);
    try {
      // Load professionals via AdminCommunityService
      const pros = await adminCommunityService.getAllProfessionals();
      setProfessionals((pros as Professional[]) || []);

      // Load reviews via ReviewsService (SSOT)
      const revs = await ReviewsService.getAllReviews("professional", 100);

      if (revs.length > 0) {
        const reviewerIds = [...new Set(revs.map((r) => r.reviewer_profile_id))];
        const proIds = [...new Set(revs.map((r) => r.reviewed_profile_id))];

        const profiles =
          reviewerIds.length > 0
            ? await profileService.getProfilesSummary(reviewerIds as string[])
            : [];
        const prosData =
          proIds.length > 0
            ? await ProfessionalService.getProfessionalsByIdsSimple(
                proIds as string[],
              )
            : [];

        const profileMap = new Map(
          profiles.map((p) => [p.id, { name: p.name, avatar_url: p.avatarUrl }]),
        );
        const proMap = new Map(
          (prosData || []).map((p: any) => [p.id, p] as [string, any]),
        );

        setReviews(
          revs.map((r: any) => ({
            ...r,
            reviewer: (profileMap.get(r.reviewer_profile_id) as any) || {
              name: "Usuário",
              avatar_url: "",
            },
            professional: (proMap.get(r.reviewed_profile_id) as any) || {
              name: "Desconhecido",
            },
          })),
        );
      } else {
        setReviews([]);
      }

      // Load reports via AdminCommunityService
      const reps = await adminCommunityService.getProfessionalReports();

      if (reps && reps.length > 0) {
        const proIds = [...new Set(reps.map((r) => r.professional_id))];
        const prosData =
          proIds.length > 0
            ? await ProfessionalService.getProfessionalsByIdsSimple(
                proIds as string[],
              )
            : [];
        const proMap = new Map(
          (prosData || []).map((p: any) => [p.id, p] as [string, any]),
        );

        setReports(
          reps.map((r) => ({
            ...r,
            professional: proMap.get(r.professional_id) || null,
          })),
        );
      } else {
        setReports([]);
      }
    } catch (error) {
      toast({
        title: "Erro ao carregar serviços",
        description: "Não foi possível carregar os dados de moderação.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!isChecking && canModerate) {
      loadData();
    }
  }, [canModerate, isChecking]);

  // Validação de admin
  if (!isChecking && !canModerate) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-red-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Acesso Negado</h1>
          <p className="text-gray-400">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  const updateStatus = async (id: string, status: string) => {
    setActionLoading(true);
    try {
      await ProfessionalService.updateProfessionalStatus(id, status);
      toast({
        title:
          status === "aprovado"
            ? "Profissional aprovado!"
            : "Profissional rejeitado",
      });
      await loadData();
    } catch {
      toast({
        title: "Erro ao atualizar status",
        description: "Não foi possível concluir esta ação.",
        variant: "destructive",
      });
    } finally {
      setActionLoading(false);
    }
  };

  const deleteProfessional = async (id: string) => {
    setActionLoading(true);
    try {
      await ProfessionalService.deleteProfessional(id);
      toast({ title: "Profissional removido" });
      await loadData();
    } catch {
      toast({
        title: "Erro ao remover profissional",
        description: "Não foi possível concluir esta ação.",
        variant: "destructive",
      });
    } finally {
      setActionLoading(false);
    }
  };

  const deleteReview = async (id: string) => {
    setActionLoading(true);
    try {
      await ProfessionalService.deleteProfessionalReview(id);
      toast({ title: "Avaliação removida" });
      await loadData();
    } catch {
      toast({
        title: "Erro ao remover avaliação",
        description: "Não foi possível concluir esta ação.",
        variant: "destructive",
      });
    } finally {
      setActionLoading(false);
    }
  };

  const resolveReport = async (id: string, status: string) => {
    setActionLoading(true);
    try {
      await ProfessionalService.updateProfessionalReport(id, status);
      toast({ title: "Denúncia resolvida" });
      await loadData();
    } catch {
      toast({
        title: "Erro ao atualizar denúncia",
        description: "Não foi possível concluir esta ação.",
        variant: "destructive",
      });
    } finally {
      setActionLoading(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    if (deleteTarget.type === "professional") {
      await deleteProfessional(deleteTarget.id);
    } else {
      await deleteReview(deleteTarget.id);
    }
    setShowDeleteDialog(false);
    setDeleteTarget(null);
  };

  const filteredPros = professionals.filter((p) => {
    if (filterStatus !== "todos" && p.status !== filterStatus) return false;
    if (
      search &&
      !p.name.toLowerCase().includes(search.toLowerCase()) &&
      !p.service.toLowerCase().includes(search.toLowerCase())
    )
      return false;
    return true;
  });

  const pendingCount = professionals.filter(
    (p) => p.status === "pendente",
  ).length;
  const pendingReports = reports.filter((r) => r.status === "pendente").length;

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-2xl font-bold font-display">Serviços</h1>
        <p className="text-muted-foreground">
          Gerencie prestadores de serviço e avaliações
        </p>
      </div>

      <Tabs defaultValue="professionals">
        <TabsList>
          <TabsTrigger value="professionals" className="gap-1">
            Profissionais
            {pendingCount > 0 && (
              <Badge variant="destructive" className="h-5 px-1.5">
                {pendingCount}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="reviews">Avaliações</TabsTrigger>
          <TabsTrigger value="reports" className="gap-1">
            Denúncias
            {pendingReports > 0 && (
              <Badge variant="destructive" className="h-5 px-1.5">
                {pendingReports}
              </Badge>
            )}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="professionals" className="space-y-4">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9"
              />
            </div>
            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger className="w-36">
                <Filter className="h-4 w-4 mr-1" />
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="todos">Todos</SelectItem>
                <SelectItem value="pendente">Pendentes</SelectItem>
                <SelectItem value="aprovado">Aprovados</SelectItem>
                <SelectItem value="rejeitado">Rejeitados</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left p-3">Profissional</th>
                  <th className="text-left p-3">Serviço</th>
                  <th className="text-left p-3">Bairro</th>
                  <th className="text-center p-3">Avaliação</th>
                  <th className="text-center p-3">Status</th>
                  <th className="text-right p-3">Ações</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan={6}
                      className="p-4 text-center text-muted-foreground"
                    >
                      Carregando serviços...
                    </td>
                  </tr>
                ) : filteredPros.length === 0 ? (
                  <tr>
                    <td
                      colSpan={6}
                      className="p-4 text-center text-muted-foreground"
                    >
                      Nenhum resultado
                    </td>
                  </tr>
                ) : (
                  filteredPros.map((pro) => (
                    <tr key={pro.id} className="border-t">
                      <td className="p-3">
                        <div className="flex items-center gap-2">
                          <Avatar className="h-8 w-8">
                            <AvatarImage src={pro.photo} />
                            <AvatarFallback>{(pro.name ?? '?')[0]}</AvatarFallback>
                          </Avatar>
                          <span className="font-medium">{pro.name ?? 'Nome não informado'}</span>
                        </div>
                      </td>
                      <td className="p-3">{pro.service ?? 'N/A'}</td>
                      <td className="p-3">{pro.neighborhood ?? 'N/A'}</td>
                      <td className="p-3 text-center">
                        <span className="flex items-center justify-center gap-0.5">
                          <Star className="h-3 w-3 text-warning fill-warning" />
                          {Number(pro.rating).toFixed(1)} (
                          {pro.total_avaliacoes})
                        </span>
                      </td>
                      <td className="p-3 text-center">
                        <Badge
                          variant={
                            pro.status === "aprovado"
                              ? "default"
                              : pro.status === "pendente"
                                ? "secondary"
                                : "destructive"
                          }
                        >
                          {pro.status}
                        </Badge>
                      </td>
                      <td className="p-3">
                        <div className="flex justify-end gap-1">
                          <Button
                            size="icon"
                            variant="ghost"
                            disabled={actionLoading}
                            onClick={() => setSelectedPro(pro)}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          {pro.status === "pendente" && (
                            <>
                              <Button
                                size="icon"
                                variant="ghost"
                                className="text-success"
                                disabled={actionLoading}
                                onClick={() => updateStatus(pro.id, "aprovado")}
                              >
                                <Check className="h-4 w-4" />
                              </Button>
                              <Button
                                size="icon"
                                variant="ghost"
                                className="text-destructive"
                                disabled={actionLoading}
                                onClick={() =>
                                  updateStatus(pro.id, "rejeitado")
                                }
                              >
                                <X className="h-4 w-4" />
                              </Button>
                            </>
                          )}
                          <Button
                            size="icon"
                            variant="ghost"
                            className="text-destructive"
                            disabled={actionLoading}
                            onClick={() => {
                              setDeleteTarget({
                                type: "professional",
                                id: pro.profile_id || pro.id,
                              });
                              setShowDeleteDialog(true);
                            }}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </TabsContent>

        <TabsContent value="reviews" className="space-y-4">
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left p-3">Avaliador</th>
                  <th className="text-left p-3">Profissional</th>
                  <th className="text-center p-3">Nota</th>
                  <th className="text-left p-3">Comentário</th>
                  <th className="text-left p-3">Data</th>
                  <th className="text-right p-3">Ações</th>
                </tr>
              </thead>
              <tbody>
                {reviews.length === 0 ? (
                  <tr>
                    <td
                      colSpan={6}
                      className="p-4 text-center text-muted-foreground"
                    >
                      Nenhuma avaliação
                    </td>
                  </tr>
                ) : (
                  reviews.map((rev) => (
                    <tr key={rev.id} className="border-t">
                      <td className="p-3">{rev.reviewer?.name || "Anônimo"}</td>
                      <td className="p-3">{rev.professional?.name || "-"}</td>
                      <td className="p-3 text-center">
                        <span className="flex items-center justify-center gap-0.5">
                          {rev.rating}{" "}
                          <Star className="h-3 w-3 text-warning fill-warning" />
                        </span>
                      </td>
                      <td className="p-3 max-w-xs truncate">
                        {rev.comment || "-"}
                      </td>
                      <td className="p-3 text-muted-foreground">
                        {formatDistanceToNow(new Date(rev.created_at), {
                          addSuffix: true,
                          locale: ptBR,
                        })}
                      </td>
                      <td className="p-3 text-right">
                        <Button
                          size="icon"
                          variant="ghost"
                          className="text-destructive"
                          disabled={actionLoading}
                          onClick={() => {
                            setDeleteTarget({ type: "review", id: rev.id });
                            setShowDeleteDialog(true);
                          }}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </TabsContent>

        <TabsContent value="reports" className="space-y-4">
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left p-3">Profissional</th>
                  <th className="text-left p-3">Motivo</th>
                  <th className="text-left p-3">Detalhes</th>
                  <th className="text-center p-3">Status</th>
                  <th className="text-right p-3">Ações</th>
                </tr>
              </thead>
              <tbody>
                {reports.length === 0 ? (
                  <tr>
                    <td
                      colSpan={5}
                      className="p-4 text-center text-muted-foreground"
                    >
                      Nenhuma denúncia
                    </td>
                  </tr>
                ) : (
                  reports.map((rep) => (
                    <tr key={rep.id} className="border-t">
                      <td className="p-3">{rep.professional?.name || "-"}</td>
                      <td className="p-3">{rep.motivo}</td>
                      <td className="p-3 max-w-xs truncate">
                        {rep.detalhes || "-"}
                      </td>
                      <td className="p-3 text-center">
                        <Badge
                          variant={
                            rep.status === "pendente" ? "secondary" : "default"
                          }
                        >
                          {rep.status}
                        </Badge>
                      </td>
                      <td className="p-3 text-right">
                        {rep.status === "pendente" && (
                          <div className="flex justify-end gap-1">
                            <Button
                              size="sm"
                              variant="outline"
                              disabled={actionLoading}
                              onClick={() => resolveReport(rep.id, "resolvido")}
                            >
                              Resolver
                            </Button>
                            <Button
                              size="sm"
                              variant="destructive"
                              disabled={actionLoading}
                              onClick={() => resolveReport(rep.id, "ignorado")}
                            >
                              Ignorar
                            </Button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </TabsContent>
      </Tabs>

      {/* View professional dialog */}
      <Dialog open={!!selectedPro} onOpenChange={() => setSelectedPro(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Detalhes do Profissional</DialogTitle>
          </DialogHeader>
          <DialogDescription className="sr-only">
            Gerenciar serviços profissionais
          </DialogDescription>
          {selectedPro && (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <Avatar className="h-16 w-16">
                  <AvatarImage src={selectedPro.photo} />
                  <AvatarFallback>{(selectedPro.name ?? '?')[0]}</AvatarFallback>
                </Avatar>
                <div>
                  <p className="font-bold">{selectedPro.name ?? 'Nome não informado'}</p>
                  <p className="text-sm text-muted-foreground">
                    {selectedPro.service ?? 'N/A'}
                  </p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <div>
                  <span className="text-muted-foreground">Categoria:</span>{" "}
                  {selectedPro.category ?? 'N/A'}
                </div>
                <div>
                  <span className="text-muted-foreground">Bairro:</span>{" "}
                  {selectedPro.neighborhood ?? 'N/A'}
                </div>
                <div>
                  <span className="text-muted-foreground">WhatsApp:</span>{" "}
                  {selectedPro.whatsapp || "-"}
                </div>
                <div>
                  <span className="text-muted-foreground">Avaliação:</span>{" "}
                  {Number(selectedPro.rating ?? 0).toFixed(1)} (
                  {selectedPro.total_avaliacoes ?? 0})
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Delete confirmation */}
      <Dialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirmar exclusão</DialogTitle>
            <DialogDescription>
              Esta ação não pode ser desfeita. Deseja continuar?
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              disabled={actionLoading}
              onClick={() => setShowDeleteDialog(false)}
            >
              Cancelar
            </Button>
            <Button variant="destructive" disabled={actionLoading} onClick={confirmDelete}>
              Excluir
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React from "react";

import { useState, useEffect } from "react";
import { Card } from "@/shared/components/ui/card";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/shared/components/ui/tabs";
import {
  Construction,
  CheckCircle,
  XCircle,
  Clock,
  Flame,
  Eye,
  MessageCircle,
  Users,
  TrendingUp,
  Download,
  Shield,
} from "lucide-react";
import { toast } from "sonner";
import { adminCommunityService } from "@/core/admin/services/AdminCommunityService";
import { cn } from "@/shared/utils/cn";
import { USER_ROLE } from "@/shared/types/constants";
import { useSessionContext } from "@/core/session";
import { AuthorizationEngine } from "@/core/authorization";
import { logger } from "@/shared/utils/logger";

interface CivicReport {
  id: string;
  problem_type: string;
  title: string;
  description: string;
  images: string[];
  status: "pendente" | "em_analise" | "resolvido" | "rejeitado";
  supporters_count: number;
  is_critical: boolean;
  neighborhood: string;
  created_at: string;
  reporter_name: string;
}

const STATUS_OPTIONS = [
  { value: "pendente", label: "Pendente", icon: Clock, color: "bg-yellow-500" },
  { value: "em_analise", label: "Em Análise", icon: Eye, color: "bg-blue-500" },
  {
    value: "resolvido",
    label: "Resolvido",
    icon: CheckCircle,
    color: "bg-green-500",
  },
  {
    value: "rejeitado",
    label: "Rejeitado",
    icon: XCircle,
    color: "bg-red-500",
  },
];

export default function AdminZeladoria() {
  const { activeProfile } = useSessionContext();
  const [canModerate, setCanModerate] = useState<boolean | null>(null);
  const [reports, setReports] = useState<CivicReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("pendente");
  const [stats, setStats] = useState({
    total: 0,
    pendente: 0,
    em_analise: 0,
    resolvido: 0,
    rejeitado: 0,
    critical: 0,
  });

  useEffect(() => {
    fetchReports();
    fetchStats();
  }, [activeTab]);

  // Check moderation permission via AuthorizationEngine
  useEffect(() => {
    if (!activeProfile) {
      setCanModerate(false);
      return;
    }
    AuthorizationEngine.canProfilePerformAction(
      activeProfile.id,
      "moderateContent",
      {},
    ).then(setCanModerate);
  }, [activeProfile?.id]);

  // Validação de admin
  if (canModerate === false) {
    return (
      <div className="min-h-screen bg-[#0A0F14] flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-red-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Acesso Negado</h1>
          <p className="text-gray-400">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  const fetchReports = async () => {
    setLoading(true);
    try {
      const mapped = await adminCommunityService.getCivicReports(activeTab);
      setReports(mapped as any);
    } catch (error) {
      logger.error("Erro ao buscar reportes:", error);
      toast.error("Erro ao carregar reportes");
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const stats = await adminCommunityService.getCivicReportStats();
      setStats(stats as any);
    } catch (error) {
      logger.error("Erro ao buscar estatísticas:", error);
    }
  };

  const updateStatus = async (reportId: string, newStatus: string) => {
    try {
      await adminCommunityService.updateCivicReportStatus(reportId, newStatus);
      toast.success("Status atualizado!");
      fetchReports();
      fetchStats();
    } catch (error) {
      logger.error("Erro ao atualizar status:", error);
      toast.error("Erro ao atualizar status");
    }
  };

  return (
    <div className="container mx-auto p-6">
      <div className="mb-6">
        <h1 className="text-3xl font-bold flex items-center gap-2">
          <Construction className="w-8 h-8 text-orange-500" />
          Administração de Zeladoria
        </h1>
        <p className="text-muted-foreground mt-2">
          Gerencie reportes de problemas urbanos da comunidade
        </p>
      </div>

      {/* Estatísticas */}
      <div className="grid grid-cols-2 md:grid-cols-6 gap-4 mb-6">
        <Card className="p-4">
          <div className="text-2xl font-bold">{stats.total}</div>
          <div className="text-xs text-muted-foreground">Total</div>
        </Card>
        <Card className="p-4 border-yellow-500/30">
          <div className="text-2xl font-bold text-yellow-500">
            {stats.pendente}
          </div>
          <div className="text-xs text-muted-foreground">Pendentes</div>
        </Card>
        <Card className="p-4 border-blue-500/30">
          <div className="text-2xl font-bold text-blue-500">
            {stats.em_analise}
          </div>
          <div className="text-xs text-muted-foreground">Em Análise</div>
        </Card>
        <Card className="p-4 border-green-500/30">
          <div className="text-2xl font-bold text-green-500">
            {stats.resolvido}
          </div>
          <div className="text-xs text-muted-foreground">Resolvidos</div>
        </Card>
        <Card className="p-4 border-red-500/30">
          <div className="text-2xl font-bold text-red-500">
            {stats.rejeitado}
          </div>
          <div className="text-xs text-muted-foreground">Rejeitados</div>
        </Card>
        <Card className="p-4 border-orange-500/30 bg-gradient-to-br from-orange-500/10 to-red-500/10">
          <div className="text-2xl font-bold text-orange-500 flex items-center gap-1">
            <Flame className="w-5 h-5" />
            {stats.critical}
          </div>
          <div className="text-xs text-muted-foreground">Críticos</div>
        </Card>
      </div>

      {/* Tabs por Status */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="pendente">Pendentes</TabsTrigger>
          <TabsTrigger value="em_analise">Em Análise</TabsTrigger>
          <TabsTrigger value="resolvido">Resolvidos</TabsTrigger>
          <TabsTrigger value="rejeitado">Rejeitados</TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab} className="mt-6">
          {loading ? (
            <div className="text-center py-12 text-muted-foreground">
              Carregando reportes...
            </div>
          ) : reports.length === 0 ? (
            <Card className="p-12 text-center">
              <p className="text-muted-foreground">
                Nenhum reporte neste status
              </p>
            </Card>
          ) : (
            <div className="space-y-4">
              {reports.map((report) => (
                <ReportCard
                  key={report.id}
                  report={report}
                  onUpdateStatus={updateStatus}
                />
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

interface ReportCardProps {
  report: CivicReport;
  onUpdateStatus: (id: string, status: string) => void;
}

function ReportCard({ report, onUpdateStatus }: ReportCardProps) {
  return (
    <Card
      className={cn(
        "p-4",
        report.is_critical &&
          "border-2 border-orange-500/50 bg-gradient-to-br from-orange-500/5 to-transparent",
      )}
    >
      <div className="flex gap-4">
        {/* Imagem */}
        {report.images[0] && (
          <img
            src={report.images[0]}
            alt={report.title}
            className="w-32 h-32 object-cover rounded-lg flex-shrink-0"
          />
        )}

        {/* Conteúdo */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between mb-2">
            <div>
              <h3 className="font-bold text-lg flex items-center gap-2">
                {report.title}
                {report.is_critical && (
                  <Badge className="bg-gradient-to-r from-orange-500 to-red-500 text-white border-0">
                    <Flame className="w-3 h-3 mr-1" />
                    CRÍTICO
                  </Badge>
                )}
              </h3>
              <p className="text-sm text-muted-foreground">
                {report.neighborhood} • {report.reporter_name}
              </p>
            </div>
          </div>

          <p className="text-sm mb-3 line-clamp-2">{report.description}</p>

          <div className="flex items-center gap-4 mb-3 text-sm text-muted-foreground">
            <div className="flex items-center gap-1">
              <Users className="w-4 h-4" />
              <span className="font-semibold">{report.supporters_count}</span>
              <span>apoios</span>
            </div>
            <div className="flex items-center gap-1">
              <MessageCircle className="w-4 h-4" />
              <span>0 comentários</span>
            </div>
          </div>

          {/* Ações */}
          <div className="flex gap-2">
            {STATUS_OPTIONS.filter((s) => s.value !== report.status).map(
              (status) => {
                const Icon = status.icon;
                return (
                  <Button
                    key={status.value}
                    size="sm"
                    variant="outline"
                    onClick={() => onUpdateStatus(report.id, status.value)}
                    className="gap-2"
                  >
                    <Icon className="w-4 h-4" />
                    {status.label}
                  </Button>
                );
              },
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

import React, { useState, useEffect } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Plus,
  Edit,
  Trash2,
  Eye,
  EyeOff,
  ExternalLink,
  Upload,
  Image as ImageIcon,
} from "lucide-react";
import { useToast } from "@/shared/hooks/use-toast";
import { logger } from "@/shared/utils/logger";
import { SessionService } from "@/core/session/services/SessionService";
import { BannerService, type Banner } from "@/core/banners/services/BannerService";

export default function BannersPage() {
  const [banners, setBanners] = useState<Banner[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingBanner, setEditingBanner] = useState<Banner | null>(null);
  const [uploading, setUploading] = useState(false);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string>("");
  const { toast } = useToast();

  // Form state
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    image_url: "",
    link_url: "",
    position: "top",
    page: "home",
    priority: 0,
    is_active: true,
    start_date: "",
    end_date: "",
    background_color: "#ffffff",
    text_color: "#000000",
  });

  useEffect(() => {
    loadBanners();
  }, []);

  async function loadBanners() {
    try {
      const data = await BannerService.getAllBanners();
      setBanners(data);
    } catch (error) {
      logger.error("Error loading banners", error as Error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os banners",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    try {
      const user = await SessionService.getCurrentUser();
      if (!user) throw new Error("Não autenticado");

      let imageUrl = formData.image_url;

      // Se tem arquivo novo, fazer upload
      if (imageFile) {
        setUploading(true);
        imageUrl = await BannerService.uploadBannerImage(imageFile);
        setUploading(false);
      }

      const bannerData = {
        ...formData,
        image_url: imageUrl,
        created_by_user_id: user.id,
        start_date: formData.start_date || null,
        end_date: formData.end_date || null,
      };

      if (editingBanner) {
        await BannerService.updateBanner(editingBanner.id, bannerData);
        toast({ title: "Banner atualizado com sucesso!" });
      } else {
        await BannerService.createBanner(bannerData);
        toast({ title: "Banner criado com sucesso!" });
      }

      resetForm();
      loadBanners();
    } catch (error) {
      logger.error("Error saving banner", error as Error);
      toast({
        title: "Erro",
        description: "Não foi possível salvar o banner",
        variant: "destructive",
      });
    } finally {
      setUploading(false);
    }
  }

  async function handleDelete(id: string) {
    if (!confirm("Tem certeza que deseja excluir este banner?")) return;

    try {
      await BannerService.deleteBanner(id);
      toast({ title: "Banner excluído com sucesso!" });
      loadBanners();
    } catch (error) {
      logger.error("Error deleting banner", error as Error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o banner",
        variant: "destructive",
      });
    }
  }

  async function toggleActive(banner: Banner) {
    try {
      await BannerService.toggleBannerStatus(banner.id, !banner.is_active);
      toast({
        title: banner.is_active ? "Banner desativado" : "Banner ativado",
      });
      loadBanners();
    } catch (error) {
      logger.error("Error toggling banner", error as Error);
      toast({
        title: "Erro",
        description: "Não foi possível alterar o status",
        variant: "destructive",
      });
    }
  }

  function resetForm() {
    setFormData({
      title: "",
      description: "",
      image_url: "",
      link_url: "",
      position: "top",
      page: "home",
      priority: 0,
      is_active: true,
      start_date: "",
      end_date: "",
      background_color: "#ffffff",
      text_color: "#000000",
    });
    setEditingBanner(null);
    setShowForm(false);
    setImageFile(null);
    setImagePreview("");
  }

  function handleImageChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  }

  function startEdit(banner: Banner) {
    setFormData({
      title: banner.title,
      description: banner.description || "",
      image_url: banner.image_url,
      link_url: banner.link_url || "",
      position: banner.position,
      page: banner.page,
      priority: banner.priority,
      is_active: banner.is_active,
      start_date: banner.start_date ? banner.start_date.split("T")[0] : "",
      end_date: banner.end_date ? banner.end_date.split("T")[0] : "",
      background_color: banner.background_color,
      text_color: banner.text_color,
    });
    setEditingBanner(banner);
    setImagePreview(banner.image_url);
    setShowForm(true);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Banners</h1>
          <p className="text-muted-foreground">
            Gerencie os banners exibidos no app
          </p>
        </div>
        <Button onClick={() => setShowForm(!showForm)}>
          <Plus className="h-4 w-4 mr-2" />
          Novo Banner
        </Button>
      </div>

      {showForm && (
        <div className="bg-card p-6 rounded-lg border">
          <h2 className="text-xl font-bold mb-4">
            {editingBanner ? "Editar Banner" : "Novo Banner"}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Preview da Imagem */}
            {imagePreview && (
              <div className="mb-4">
                <label className="block text-sm font-medium mb-2">
                  Preview
                </label>
                <img
                  src={imagePreview}
                  alt="Preview"
                  className="w-full max-h-64 object-cover rounded-lg"
                />
              </div>
            )}

            {/* Upload de Imagem */}
            <div>
              <label className="block text-sm font-medium mb-2">
                Imagem do Banner * {uploading && "(Enviando...)"}
              </label>
              <div className="flex items-center gap-4">
                <label className="flex-1 cursor-pointer">
                  <div className="border-2 border-dashed rounded-lg p-8 text-center hover:border-primary transition-colors">
                    <Upload className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">
                      Clique para selecionar ou arraste a imagem
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      PNG, JPG ou WEBP (máx. 5MB)
                    </p>
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageChange}
                    className="hidden"
                    required={!editingBanner && !imagePreview}
                  />
                </label>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium mb-2">
                  Título *
                </label>
                <input
                  type="text"
                  required
                  value={formData.title}
                  onChange={(e) =>
                    setFormData({ ...formData, title: e.target.value })
                  }
                  className="w-full px-3 py-2 border rounded-lg"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Link (opcional)
                </label>
                <input
                  type="url"
                  value={formData.link_url}
                  onChange={(e) =>
                    setFormData({ ...formData, link_url: e.target.value })
                  }
                  className="w-full px-3 py-2 border rounded-lg"
                  placeholder="https://..."
                />
              </div>
            </div>

            {/* Seleção Visual de Página */}
            <div>
              <label className="block text-sm font-medium mb-2">Página *</label>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {[
                  { value: "all", label: "Todas", icon: "🌐" },
                  { value: "home", label: "Home", icon: "🏠" },
                  { value: "community", label: "Comunidade", icon: "👥" },
                  { value: "mobility", label: "Mobilidade", icon: "🚗" },
                  { value: "business", label: "Negócios", icon: "🏢" },
                  { value: "events", label: "Eventos", icon: "📅" },
                ].map((page) => (
                  <button
                    key={page.value}
                    type="button"
                    onClick={() =>
                      setFormData({ ...formData, page: page.value })
                    }
                    className={`p-4 border-2 rounded-lg text-center transition-all ${
                      formData.page === page.value
                        ? "border-primary bg-primary/10"
                        : "border-gray-200 hover:border-primary/50"
                    }`}
                  >
                    <div className="text-3xl mb-1">{page.icon}</div>
                    <div className="text-sm font-medium">{page.label}</div>
                  </button>
                ))}
              </div>
            </div>

            {/* Seleção Visual de Posição */}
            <div>
              <label className="block text-sm font-medium mb-2">
                Posição *
              </label>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {[
                  { value: "top", label: "Topo", icon: "⬆️" },
                  { value: "middle", label: "Meio", icon: "↔️" },
                  { value: "bottom", label: "Rodapé", icon: "⬇️" },
                  { value: "sidebar", label: "Sidebar", icon: "➡️" },
                ].map((pos) => (
                  <button
                    key={pos.value}
                    type="button"
                    onClick={() =>
                      setFormData({ ...formData, position: pos.value })
                    }
                    className={`p-3 border-2 rounded-lg text-center transition-all ${
                      formData.position === pos.value
                        ? "border-primary bg-primary/10"
                        : "border-gray-200 hover:border-primary/50"
                    }`}
                  >
                    <div className="text-2xl mb-1">{pos.icon}</div>
                    <div className="text-sm font-medium">{pos.label}</div>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium mb-2">
                  Prioridade
                </label>
                <input
                  type="number"
                  value={formData.priority}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      priority: parseInt(e.target.value),
                    })
                  }
                  className="w-full px-3 py-2 border rounded-lg"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Maior número = maior prioridade
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Status</label>
                <div className="flex items-center gap-2 h-10">
                  <input
                    type="checkbox"
                    id="is_active"
                    checked={formData.is_active}
                    onChange={(e) =>
                      setFormData({ ...formData, is_active: e.target.checked })
                    }
                    className="w-4 h-4"
                  />
                  <label htmlFor="is_active" className="text-sm font-medium">
                    {formData.is_active ? "✅ Ativo" : "❌ Inativo"}
                  </label>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Data Início
                </label>
                <input
                  type="date"
                  value={formData.start_date}
                  onChange={(e) =>
                    setFormData({ ...formData, start_date: e.target.value })
                  }
                  className="w-full px-3 py-2 border rounded-lg"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Data Fim
                </label>
                <input
                  type="date"
                  value={formData.end_date}
                  onChange={(e) =>
                    setFormData({ ...formData, end_date: e.target.value })
                  }
                  className="w-full px-3 py-2 border rounded-lg"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Descrição
              </label>
              <textarea
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                className="w-full px-3 py-2 border rounded-lg"
                rows={3}
                placeholder="Descrição opcional do banner..."
              />
            </div>

            <div className="flex gap-2">
              <Button type="submit" disabled={uploading}>
                {uploading
                  ? "Enviando..."
                  : editingBanner
                    ? "Atualizar"
                    : "Criar"}
              </Button>
              <Button type="button" variant="outline" onClick={resetForm}>
                Cancelar
              </Button>
            </div>
          </form>
        </div>
      )}

      <div className="grid gap-4">
        {banners.map((banner) => (
          <div
            key={banner.id}
            className="bg-card p-4 rounded-lg border flex items-center gap-4"
          >
            <img
              src={banner.image_url}
              alt={banner.title}
              className="w-32 h-20 object-cover rounded"
            />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h3 className="font-bold">{banner.title}</h3>
                {banner.is_active ? (
                  <span className="text-xs bg-green-500/20 text-green-400 px-2 py-1 rounded">
                    Ativo
                  </span>
                ) : (
                  <span className="text-xs bg-gray-500/20 text-gray-400 px-2 py-1 rounded">
                    Inativo
                  </span>
                )}
              </div>
              <p className="text-sm text-muted-foreground">
                {banner.description}
              </p>
              <div className="flex gap-4 text-xs text-muted-foreground mt-2">
                <span>Página: {banner.page}</span>
                <span>Posição: {banner.position}</span>
                <span>Prioridade: {banner.priority}</span>
                <span>👁️ {banner.views_count}</span>
                <span>🖱️ {banner.clicks_count}</span>
              </div>
            </div>
            <div className="flex gap-2">
              <Button
                size="sm"
                variant="outline"
                onClick={() => toggleActive(banner)}
              >
                {banner.is_active ? (
                  <EyeOff className="h-4 w-4" />
                ) : (
                  <Eye className="h-4 w-4" />
                )}
              </Button>
              {banner.link_url && (
                <Button size="sm" variant="outline" asChild>
                  <a
                    href={banner.link_url}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <ExternalLink className="h-4 w-4" />
                  </a>
                </Button>
              )}
              <Button
                size="sm"
                variant="outline"
                onClick={() => startEdit(banner)}
              >
                <Edit className="h-4 w-4" />
              </Button>
              <Button
                size="sm"
                variant="destructive"
                onClick={() => handleDelete(banner.id)}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          </div>
        ))}

        {banners.length === 0 && (
          <div className="text-center py-12 text-muted-foreground">
            Nenhum banner cadastrado
          </div>
        )}
      </div>
    </div>
  );
}

import { Building2, Check, ChevronDown, Filter as FilterIcon, Globe, Grid3x3, GraduationCap, Layers, MapPin, Rows, School, Search, Shield, Target, Users, X } from 'lucide-react';
