  const { id } = useParams();
  const navigate = useNavigate();
  const appUrls = useAppUrls(); // ✅ SSOT URLs
  const { toast } = useToast();
  const { user } = useAuth();

  const [post, setPost] = useState<Post | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [commentText, setCommentText] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [reportOpen, setReportOpen] = useState(false);

  useEffect(() => {
    loadPost();
  }, [id]);

  async function loadPost() {
    if (!id) return;
    const data = await lostFoundService.getPostById(id);

    if (!data) {
      setNotFound(true);
      setLoading(false);
      return;
    }

    const profile = await profileServiceInstance.getProfileById(data.autor_id);

    setPost({
      id: data.id,
      tipo: data.tipo,
      category: data.categoria || "",
      titulo: data.titulo,
      description: data.descricao || "",
      photo_url: data.imagens?.[0] || "",
      neighborhood: "",
      localizacao_aprox: data.local_perdido || "",
      latitude: null,
      longitude: null,
      date_ocorrido: data.data_perdido || "",
      resolvido: data.resolvido || false,
      created_at: data.created_at || "",
      autor_id: data.autor_id,
      autor: profile
        ? {
            name: profile.name,
            avatar_url: profile.avatar_url || "",
            whatsapp: (profile as any).whatsapp || "",
          }
        : null,
    });

    await loadComments();
    setLoading(false);
  }

  async function loadComments() {
    if (!id) return;
    const data = await lostFoundService.getComments(id);

    if (!data) return;

    const autorIds = [...new Set(data.map((c: any) => c.autor_id))];
    const profiles =
      autorIds.length > 0
        ? await profileServiceInstance.getProfilesSummary(autorIds)
        : [];

    const profileMap = new Map(
      profiles.map((p: any) => [
        p.id,
        { name: p.name, avatar_url: p.avatarUrl || p.avatar_url || "" },
      ]),
    );
    setComments(
      data.map((c: any) => ({
        id: c.id,
        texto: c.texto,
        created_at: c.created_at || "",
        autor: (profileMap.get(c.autor_id) as {
          name: string;
          avatar_url: string;
        }) || { name: "Usuário", avatar_url: "" },
      })),
    );
  }

  async function handleComment() {
    if (!user) {
      toast({ title: "Faça login para comentar", variant: "destructive" });
      return;
    }
    if (!commentText.trim()) return;

    setSubmitting(true);
    try {
      await lostFoundService.createComment({
        post_id: id,
        autor_id: user.id,
        conteudo: commentText.trim(),
      });
      setCommentText("");
      toast({ title: "Comentário enviado!" });
      await loadComments();
    } catch {
      toast({ title: "Error comentar", variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  }

  async function handleMarkResolved() {
    if (!post || post.autor_id !== user?.id) return;
    await lostFoundService.toggleResolved(post.id);
    toast({
      title: post.resolvido
        ? "Marcado como não resolvido"
        : "Marcado como resolvido!",
    });
    loadPost();
  }

  if (loading)
    return (
      <div className="px-4 pt-16 space-y-4">
        <Skeleton className="h-48 w-full rounded-xl" />
        <Skeleton className="h-6 w-3/4" />
        <Skeleton className="h-4 w-1/2" />
      </div>
    );

  if (notFound || !post)
    return (
      <div className="p-4 text-center">
        <p>Publicação não encontrada.</p>
        <Button
          variant="outline"
          onClick={() => navigate(appUrls.community.lostAndFound)} // ✅ SSOT
          className="mt-4"
        >
          Voltar
        </Button>
      </div>
    );

  const isAuthor = user?.id === post.autor_id;
  const hasLocation = post.latitude !== null && post.longitude !== null;

  return (
    <div className="flex flex-col lg:flex-row pb-24 gap-6 max-w-7xl mx-auto">
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-3 px-4 py-3 border-b sticky top-0 bg-background z-10">
          <button
            onClick={() => navigate(-1)}
            className="h-9 w-9 rounded-full bg-secondary flex items-center justify-center"
          >
            <ArrowLeft className="h-5 w-5" />
          </button>
          <h1 className="text-lg font-bold font-display">
            {post.tipo === "perdido" ? "Item Perdido" : "Item Encontrado"}
          </h1>
          <button
            onClick={() => setReportOpen(true)}
            className="ml-auto h-9 w-9 rounded-full bg-secondary flex items-center justify-center"
          >
            <Flag className="h-4 w-4 text-muted-foreground" />
          </button>
        </div>

        {post.photo_url ? (
          <img
            src={post.photo_url}
            alt={post.titulo}
            className="w-full h-56 object-cover"
          />
        ) : (
          <div className="w-full h-40 bg-secondary flex items-center justify-center text-5xl">
            {CAT_ICONS[post.category] || "❓"}
          </div>
        )}

        <div className="px-4 py-4 space-y-4">
          <div className="flex items-center gap-2">
            <Badge
              variant={post.tipo === "perdido" ? "destructive" : "default"}
            >
              {post.tipo === "perdido" ? "🔴 Perdido" : "🟢 Encontrado"}
            </Badge>
            <Badge variant="secondary">
              {CAT_ICONS[post.category]} {post.category}
            </Badge>
            {post.resolvido && (
              <Badge
                variant="secondary"
                className="gap-0.5 text-success border-success/30"
              >
                <CheckCircle2 className="h-3 w-3" /> Resolvido
              </Badge>
            )}
          </div>

          <h2 className="text-lg font-bold font-display">{post.titulo}</h2>

          {post.description && (
            <p className="text-sm text-muted-foreground leading-relaxed">
              {post.description}
            </p>
          )}

          <div className="flex flex-col gap-2 text-sm">
            {post.neighborhood && (
              <div className="flex items-center gap-2">
                <MapPin className="h-4 w-4 text-muted-foreground" />
                <span>
                  {post.neighborhood}
                  {post.localizacao_aprox ? ` - ${post.localizacao_aprox}` : ""}
                </span>
              </div>
            )}
            {post.date_ocorrido && (
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                <span>
                  {format(
                    new Date(post.date_ocorrido + "T12:00:00"),
                    "dd 'de' MMMM 'de' yyyy",
                    { locale: ptBR },
                  )}
                </span>
              </div>
            )}
          </div>

          <div className="flex items-center gap-3 py-3 border-t border-b">
            <Avatar className="h-10 w-10">
              <AvatarImage src={post.autor?.avatar_url} />
              <AvatarFallback>{post.autor?.name?.[0] || "?"}</AvatarFallback>
            </Avatar>
            <div className="flex-1">
              <p className="text-sm font-medium">
                {post.autor?.name || "Anônimo"}
              </p>
              <p className="text-xs text-muted-foreground">
                {formatDistanceToNow(new Date(post.created_at), {
                  addSuffix: true,
                  locale: ptBR,
                })}
              </p>
            </div>
            {post.autor?.whatsapp && (
              <Button
                asChild
                size="sm"
                className="bg-success hover:bg-success/90"
              >
                <a
                  href={`https://wa.me/55${post.autor.whatsapp}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <MessageCircle className="h-4 w-4 mr-1" /> WhatsApp
                </a>
              </Button>
            )}
          </div>

          {isAuthor && (
            <Button
              variant={post.resolvido ? "outline" : "default"}
              className="w-full"
              onClick={handleMarkResolved}
            >
              <CheckCircle2 className="h-4 w-4 mr-2" />
              {post.resolvido
                ? "Desmarcar como resolvido"
                : "Marcar como resolvido"}
            </Button>
          )}

          <div>
            <h3 className="text-sm font-bold mb-3">
              Comentários ({comments.length})
            </h3>
            {comments.length === 0 ? (
              <p className="text-sm text-muted-foreground">
                Nenhum comentário ainda.
              </p>
            ) : (
              <div className="space-y-3">
                {comments.map((c, i) => (
                  <motion.div
                    key={c.id}
                    initial={{ opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.03 }}
                    className="bg-card rounded-lg border p-3"
                  >
                    <div className="flex items-center gap-2 mb-1">
                      <Avatar className="h-6 w-6">
                        <AvatarImage src={c.autor?.avatar_url} />
                        <AvatarFallback>
                          {c.autor?.name?.[0] || "?"}
                        </AvatarFallback>
                      </Avatar>
                      <span className="text-xs font-medium">
                        {c.autor?.name || "Anônimo"}
                      </span>
                      <span className="text-xs text-muted-foreground ml-auto">
                        {formatDistanceToNow(new Date(c.created_at), {
                          addSuffix: true,
                          locale: ptBR,
                        })}
                      </span>
                    </div>
                    <p className="text-sm">{c.texto}</p>
                  </motion.div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="fixed bottom-0 left-0 right-0 bg-background border-t px-4 py-3 z-20">
          <div className="flex gap-2">
            <Textarea
              value={commentText}
              onChange={(e) => setCommentText(e.target.value.slice(0, 500))}
              placeholder="Deixe um comentário..."
              className="min-h-[40px] max-h-[80px] text-sm resize-none flex-1"
              rows={1}
            />
            <Button
              size="icon"
              className="flex-shrink-0 h-10 w-10"
              onClick={handleComment}
              disabled={submitting || !commentText.trim()}
            >
              {submitting ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Send className="h-4 w-4" />
              )}
            </Button>
          </div>
        </div>

        <ReportContentDialog
          open={reportOpen}
          onOpenChange={setReportOpen}
          targetType="post"
          targetId={post.id}
        />
      </div>

      <div className="hidden lg:block lg:w-[380px] lg:sticky lg:top-4 lg:self-start">
        <div className="space-y-4">
          {hasLocation ? (
            <LostFoundMiniMap
              latitude={post.latitude!}
              longitude={post.longitude!}
              title={post.titulo}
              tipo={post.tipo as "perdido" | "encontrado"}
              className="h-[400px]"
            />
          ) : (
            <LostFoundLocationCard
              neighborhood={post.neighborhood}
              localizacaoAprox={post.localizacao_aprox}
            />
          )}

          <div className="bg-card rounded-xl border p-4 space-y-3">
            <h3 className="font-semibold text-sm">Informações</h3>
            <div className="space-y-2 text-sm">
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Status:</span>
                <Badge
                  variant={post.resolvido ? "secondary" : "default"}
                  className="text-xs"
                >
                  {post.resolvido ? "Resolvido" : "Em aberto"}
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Tipo:</span>
                <Badge
                  variant={post.tipo === "perdido" ? "destructive" : "default"}
                  className="text-xs"
                >
                  {post.tipo === "perdido" ? "Perdido" : "Encontrado"}
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Categoria:</span>
                <span className="font-medium">
                  {CAT_ICONS[post.category]} {post.category}
                </span>
              </div>
              {post.neighborhood && (
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Bairro:</span>
                  <span className="font-medium">{post.neighborhood}</span>
                </div>
              )}
              {post.date_ocorrido && (
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Data:</span>
                  <span className="font-medium">
                    {format(
                      new Date(post.date_ocorrido + "T12:00:00"),
                      "dd/MM/yyyy",
                    )}
                  </span>
                </div>
              )}
            </div>
          </div>

          <div className="bg-blue-500/10 border border-blue-500/20 rounded-xl p-4">
            <p className="text-xs text-blue-500 leading-relaxed">
              💡 <strong>Dica:</strong>{" "}
              {post.tipo === "perdido"
                ? "Se você encontrou este item, entre em contato com o autor pelo WhatsApp."
                : "Se este item é seu, entre em contato com quem encontrou para combinar a devolução."}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React from "react";

import { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import {
  Search,
  Plus,
  MapPin,
  CheckCircle2,
  Loader2,
  Eye,
  EyeOff,
  Users,
} from "lucide-react";
import { Input } from "@/shared/components/ui/input";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import { Skeleton } from "@/shared/components/ui/skeleton";
import { TooltipProvider } from "@/shared/components/ui/tooltip";
import { useAppUrls } from "@/core/routing/hooks"; // ✅ SSOT URLs
import { useUserTerritory } from "@/core/location/hooks/useUserTerritory";
import { useSessionContext } from "@/core/session";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { cn } from "@/shared/utils/cn";
import { motion } from "framer-motion";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import {
  useInfiniteScroll,
  usePaginatedState,
} from "@/shared/hooks/useInfiniteScroll";
import { lostFoundService } from "@/modules/community/lostfound/services/LostFoundService";
import { ViewOnMapButton } from "@/core/maps/components/ViewOnMapButton";

const CATEGORIAS = [
  { id: "todos", label: "Todos", icon: "🔍" },
  { id: "animal", label: "Animal", icon: "🐾" },
  { id: "celular", label: "Celular", icon: "📱" },
  { id: "documentos", label: "Documentos", icon: "📄" },
  { id: "chaves", label: "Chaves", icon: "🔑" },
  { id: "carteira", label: "Carteira", icon: "👛" },
  { id: "objetos", label: "Objetos", icon: "📦" },
  { id: "outro", label: "Outro", icon: "❓" },
];

interface LostFoundItem {
  id: string;
  tipo: string;
  category: string;
  titulo: string;
  description: string;
  photo_url: string;
  neighborhood: string;
  date_ocorrido: string;
  resolvido: boolean;
  created_at: string;
  latitude?: number;
  longitude?: number;
}

export default function AchadosPerdidosPage() {
  const navigate = useNavigate();
  const appUrls = useAppUrls(); // ✅ SSOT URLs
  const [search, setSearch] = useState("");
  const [filterTipo, setFilterTipo] = useState("todos");
  const [filterCategoria, setFilterCategoria] = useState("todos");

  // ✅ Verificação de autenticação
  const { activeProfile } = useSessionContext();
  const { hasHome, loading: territoryLoading } = useUserTerritory();

  const {
    items,
    page,
    hasMore,
    loading,
    initialLoading,
    setLoading,
    setInitialLoading,
    appendItems,
    nextPage,
    reset,
    PAGE_SIZE,
  } = usePaginatedState<LostFoundItem>();

  const fetchPage = useCallback(
    async (pageNum: number) => {
      setLoading(true);
      const from = pageNum * PAGE_SIZE;
      const to = from + PAGE_SIZE - 1;

      // ✅ LOTE 9A - Usar lostFoundService.getPostsPage (SSOT para lost_found_posts)
      const data = await lostFoundService.getPostsPage(
        { tipo: filterTipo, categoria: filterCategoria },
        from,
        to,
      );

      if (data) {
        appendItems(
          data.map((p) => ({
            id: p.id,
            tipo: p.tipo,
            category: p.category,
            titulo: p.titulo,
            description: p.description || "",
            photo_url: p.photo_url || "",
            neighborhood: p.neighborhood || "",
            date_ocorrido: p.data_ocorrido || "",
            resolvido: p.resolvido || false,
            created_at: p.created_at || "",
            latitude: p.latitude,
            longitude: p.longitude,
          })),
          pageNum === 0,
        );
      }
      setLoading(false);
      setInitialLoading(false);
    },
    [
      filterTipo,
      filterCategoria,
      PAGE_SIZE,
      setLoading,
      setInitialLoading,
      appendItems,
    ],
  );

  useEffect(() => {
    reset();
    fetchPage(0);
  }, [filterTipo, filterCategoria]);
  useEffect(() => {
    if (page > 0) fetchPage(page);
  }, [page]);

  const { sentinelRef } = useInfiniteScroll({
    hasMore,
    loading,
    onLoadMore: nextPage,
  });

  const searchLower = search.toLowerCase();
  const filtered = items.filter(
    (p) =>
      !search ||
      p.titulo.toLowerCase().includes(searchLower) ||
      p.description.toLowerCase().includes(searchLower) ||
      p.neighborhood.toLowerCase().includes(searchLower),
  );

  const getCatIcon = (cat: string) =>
    CATEGORIAS.find((c) => c.id === cat)?.icon || "❓";

  // Bloquear se não estiver logado
  if (!activeProfile) {
    return (
      <TooltipProvider>
        <div className="min-h-screen bg-[#12181B] flex items-center justify-center" role="main">
          <div className="text-center p-8 max-w-md">
            <Users className="h-16 w-16 text-teal-400 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-white mb-4">
              Faça login para acessar achados e perdidos
            </h2>
            <p className="text-gray-400 mb-6">
              Os achados e perdidos são exclusivos para moradores cadastrados do bairro.
            </p>
            <Button onClick={() => window.location.href = appUrls.auth.login} className="bg-teal-500 hover:bg-teal-400">
              Fazer Login
            </Button>
          </div>
        </div>
      </TooltipProvider>
    );
  }

  // Aguardar resolução do território
  if (territoryLoading) {
    return (
      <div className="min-h-screen bg-[#12181B] flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-teal-400 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  // Bloquear se não tiver bairro cadastrado
  if (!hasHome) {
    return (
      <TooltipProvider>
        <div className="min-h-screen bg-[#12181B] flex items-center justify-center" role="main">
          <div className="text-center p-8 max-w-md">
            <Users className="h-16 w-16 text-amber-400 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-white mb-4">
              Complete seu cadastro
            </h2>
            <p className="text-gray-400 mb-6">
              Para acessar os achados e perdidos, você precisa cadastrar seu bairro no perfil.
            </p>
            <Button onClick={() => window.location.href = appUrls.profile.central} className="bg-teal-500 hover:bg-teal-400">
              Completar Perfil
            </Button>
          </div>
        </div>
      </TooltipProvider>
    );
  }

  return (
    <div className="flex flex-col pb-20">
      <div className="px-4 pt-4 pb-2">
        <div className="flex items-center justify-between mb-1">
          <div>
            <h1 className="text-xl font-bold font-display">
              Achados e Perdidos
            </h1>
            <p className="text-sm text-muted-foreground">
              Ajude a comunidade a encontrar o que perdeu
            </p>
          </div>
          <Button size="sm" onClick={() => navigate(appUrls.community.newLostAndFound)}> {/* ✅ SSOT */}
            <Plus className="h-4 w-4 mr-1" /> Publicar
          </Button>
        </div>
        <div className="relative mt-2">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar itens..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-9 text-sm"
          />
        </div>
      </div>

      {/* Tipo filter */}
      <div className="flex gap-2 px-4 py-2">
        {[
          { id: "todos", label: "Todos", color: "" },
          { id: "perdido", label: "🔴 Perdido", color: "text-destructive" },
          { id: "encontrado", label: "🟢 Encontrado", color: "text-success" },
        ].map((t) => (
          <button
            key={t.id}
            onClick={() => setFilterTipo(t.id)}
            className={cn(
              "px-3 py-1.5 rounded-full border text-xs font-medium transition-all",
              filterTipo === t.id
                ? "bg-primary/10 border-primary text-primary"
                : "bg-card border-border",
            )}
          >
            {t.label}
          </button>
        ))}
      </div>

      {/* Categoria filter */}
      <div className="flex gap-2 px-4 pb-2 overflow-x-auto">
        {CATEGORIAS.map((cat) => (
          <button
            key={cat.id}
            onClick={() => setFilterCategoria(cat.id)}
            className={cn(
              "flex items-center gap-1 px-2.5 py-1 rounded-full border text-xs font-medium transition-all flex-shrink-0",
              filterCategoria === cat.id
                ? "bg-primary/10 border-primary text-primary"
                : "bg-card border-border",
            )}
          >
            {cat.icon} {cat.label}
          </button>
        ))}
      </div>

      {/* List */}
      <div className="flex flex-col gap-3 px-4 py-2">
        {initialLoading ? (
          Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-28 w-full rounded-xl" />
          ))
        ) : filtered.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-4xl mb-3">🔎</p>
            <p className="text-sm text-muted-foreground mb-3">
              Nenhum item publicado ainda.
            </p>
            <Button
              variant="outline"
              onClick={() => navigate(appUrls.community.newLostAndFound)} // ✅ SSOT
            >
              Publicar item
            </Button>
          </div>
        ) : (
          filtered.map((item, i) => (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: Math.min(i, 5) * 0.04 }}
              onClick={() => navigate(`/achados-perdidos/${item.id}`)}
              className={cn(
                "flex gap-3 bg-card rounded-xl border p-3 cursor-pointer hover:shadow-md transition-shadow",
                item.resolvido && "opacity-60",
              )}
            >
              {item.photo_url ? (
                <img
                  src={item.photo_url}
                  alt={item.titulo}
                  className="h-20 w-20 rounded-xl object-cover flex-shrink-0"
                  loading="lazy"
                />
              ) : (
                <div className="h-20 w-20 rounded-xl bg-secondary flex items-center justify-center text-3xl flex-shrink-0">
                  {getCatIcon(item.category)}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-0.5">
                  <Badge
                    variant={
                      item.tipo === "perdido" ? "destructive" : "default"
                    }
                    className="text-[10px] px-1.5 py-0"
                  >
                    {item.tipo === "perdido" ? "Perdido" : "Encontrado"}
                  </Badge>
                  {item.resolvido && (
                    <Badge
                      variant="secondary"
                      className="text-[10px] px-1.5 py-0 gap-0.5"
                    >
                      <CheckCircle2 className="h-2.5 w-2.5" /> Resolvido
                    </Badge>
                  )}
                </div>
                <h3 className="text-sm font-bold truncate">{item.titulo}</h3>
                <p className="text-xs text-muted-foreground line-clamp-1 mt-0.5">
                  {item.description}
                </p>
                <div className="flex items-center gap-3 mt-1.5 text-xs text-muted-foreground">
                  <span className="flex items-center gap-0.5">
                    <MapPin className="h-3 w-3" />
                    {item.neighborhood || "Não informado"}
                  </span>
                  {item.date_ocorrido && (
                    <span>
                      {format(
                        new Date(item.date_ocorrido + "T12:00:00"),
                        "dd/MM/yyyy",
                      )}
                    </span>
                  )}
                </div>
                {item.latitude && item.longitude && (
                  <div className="mt-2">
                    <ViewOnMapButton
                      latitude={item.latitude}
                      longitude={item.longitude}
                      itemId={item.id}
                      itemType="achado_perdido"
                      itemName={item.titulo}
                      variant="outline"
                      size="sm"
                      className="w-full h-7 text-[10px]"
                      onClick={() => {}}
                    />
                  </div>
                )}
              </div>
            </motion.div>
          ))
        )}
        {loading && !initialLoading && (
          <div className="flex justify-center py-4">
            <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
          </div>
        )}
        <div ref={sentinelRef} className="h-1" />
      </div>
    </div>
  );
}

/**
 * TouristPointsMap — Mapa interativo de pontos turísticos.
 * Engine: MapLibre GL JS (via SSOT de mapa).
 */

import { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { MapPin, Star } from 'lucide-react';
import type { TouristPoint } from '../types';
import { CATEGORY_ICONS, CATEGORY_LABELS } from '../types';
import { DEFAULT_TILE_STYLE } from '@/core/maps/providers/MapProvider';

interface TouristPointsMapProps {
  points: TouristPoint[];
  selectedId?: string;
  onSelect?: (point: TouristPoint) => void;
  className?: string;
}

export function TouristPointsMap({ points, selectedId, onSelect, className = '' }: TouristPointsMapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef       = useRef<maplibregl.Map | null>(null);
  const markersRef   = useRef<Map<string, maplibregl.Marker>>(new Map());

  const withCoords = points.filter(p => p.latitude && p.longitude);

  useEffect(() => {
    if (!containerRef.current || mapRef.current || withCoords.length === 0) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: DEFAULT_TILE_STYLE.styleUrl,
      center: [-38.5014, -12.9714],
      zoom: 13,
      attributionControl: false,
    });

    map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-left');
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');

    map.on('load', () => {
      withCoords.forEach(point => {
        const emoji   = point.icon_emoji || CATEGORY_ICONS[point.category];
        const bgColor = point.is_featured ? '#f59e0b' : 'hsl(var(--primary, 221 83% 53%))';

        const el = document.createElement('div');
        el.style.cssText = `width:36px;height:36px;background:${bgColor};border-radius:50% 50% 50% 0;transform:rotate(-45deg);border:2px solid white;box-shadow:0 2px 8px rgba(0,0,0,0.3);display:flex;align-items:center;justify-content:center;cursor:pointer;`;
        const inner = document.createElement('span');
        inner.style.cssText = 'transform:rotate(45deg);font-size:16px;line-height:1;';
        inner.textContent = emoji;
        el.appendChild(inner);

        el.addEventListener('click', () => onSelect?.(point));

        const popup = new maplibregl.Popup({ offset: 20, closeButton: false, maxWidth: '240px' }).setHTML(`
          <div style="padding:4px;min-width:180px">
            ${point.photo_url ? `<img src="${point.photo_url}" alt="${point.name}" style="width:100%;height:96px;object-fit:cover;border-radius:8px;margin-bottom:8px"/>` : ''}
            <div style="display:flex;align-items:flex-start;gap:8px">
              <span style="font-size:20px;flex-shrink:0">${emoji}</span>
              <div>
                <p style="font-weight:700;font-size:13px;line-height:1.2">${point.name}</p>
                <p style="font-size:11px;color:#6b7280;margin-top:2px">${CATEGORY_LABELS[point.category]}</p>
                ${point.neighborhood ? `<p style="font-size:11px;color:#6b7280;margin-top:4px">📍 ${point.neighborhood}</p>` : ''}
                ${point.rating > 0 ? `<p style="font-size:11px;color:#d97706;margin-top:4px;font-weight:600">⭐ ${point.rating.toFixed(1)}</p>` : ''}
                ${point.visiting_hours ? `<p style="font-size:11px;color:#6b7280;margin-top:4px">🕐 ${point.visiting_hours}</p>` : ''}
              </div>
            </div>
          </div>
        `);

        const marker = new maplibregl.Marker({ element: el, anchor: 'bottom' })
          .setLngLat([point.longitude!, point.latitude!])
          .setPopup(popup)
          .addTo(map);

        markersRef.current.set(point.id, marker);
      });

      // Ajustar câmera para cobrir todos os pontos
      if (withCoords.length === 1) {
        map.flyTo({ center: [withCoords[0].longitude!, withCoords[0].latitude!], zoom: 15 });
      } else {
        const lngs = withCoords.map(p => p.longitude!);
        const lats = withCoords.map(p => p.latitude!);
        map.fitBounds(
          [[Math.min(...lngs), Math.min(...lats)], [Math.max(...lngs), Math.max(...lats)]],
          { padding: 40 }
        );
      }
    });

    mapRef.current = map;
    return () => {
      markersRef.current.clear();
      map.remove();
      mapRef.current = null;
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Abrir popup do ponto selecionado externamente
  useEffect(() => {
    if (!selectedId) return;
    markersRef.current.get(selectedId)?.togglePopup();
  }, [selectedId]);

  if (withCoords.length === 0) {
    return (
      <div className={`flex flex-col items-center justify-center bg-muted/30 border border-border rounded-2xl text-muted-foreground ${className}`}>
        <MapPin className="h-8 w-8 mb-2 opacity-40" />
        <p className="text-sm">Nenhum ponto com coordenadas cadastradas</p>
      </div>
    );
  }

  return <div ref={containerRef} className={`rounded-2xl border border-border z-0 ${className}`} style={{ minHeight: '100%' }} />;
}

/**
 * RideRequestForm Component (AAA)
 * 
 * Formulário principal de solicitação de corrida com hierarquia correta:
 * 1. Origem/Destino (foco principal)
 * 2. Estimativa de preço (destacada)
 * 3. Tipo de corrida (tabs compactas)
 * 4. Preferências de confiança (chips)
 * 5. Opções avançadas (accordion)
 * 
 * @module mobility/components/ride-request/RideRequestForm
 * @version 2.0.0 (AAA)
 */
import { logger } from '@/shared/utils/logger';
import React, { memo, useCallback, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, MapPin } from 'lucide-react';
import { Button } from '@/shared/components/ui/button';
import { cn } from '@/shared/utils/cn';
import { toast } from 'sonner';
import { AddressInput } from './AddressInput';
import { RideTypeSelector } from './RideTypeSelector';
import { TrustPreferenceChips } from './TrustPreferenceChips';
import { AdvancedOptions } from './AdvancedOptions';
import { RouteEstimateCardEnhanced } from '../RouteEstimateCardEnhanced';
import { BoardingPointsPanel, type BoardingPoint } from '../BoardingPointsPanel';
import { useRideRequestForm } from '@/modules/mobility/hooks/useRideRequestForm';
import { usePriceEstimate } from '@/core/pricing/hooks/usePriceEstimate';
import type { PriceEstimateRequest } from '@/core/pricing/types';
import type { CreateRideRequestData } from '@/modules/mobility/hooks/useMobilidade';
import { AddressService } from '@/core/address/services/AddressService';
import type { GeolocationCoordinates } from '@/modules/mobility/hooks/useGeolocation';

export interface RideRequestFormProps {
  /** Callback ao submeter formulário */
  onSubmit: (data: CreateRideRequestData) => void | Promise<void>;
  /** Classe CSS adicional */
  className?: string;
}

/**
 * Formulário de solicitação de corrida com hierarquia otimizada
 * 
 * @example
 * ```tsx
 * <RideRequestForm
 *   onSubmit={async (data) => {
 *     await createRide(data);
 *   }}
 * />
 * ```
 */
export const RideRequestForm = memo<RideRequestFormProps>(function RideRequestForm({
  onSubmit,
  className,
}) {
  const { state, actions, validation } = useRideRequestForm();
  const addressService = new AddressService();
  
  const [showBoardingPoints, setShowBoardingPoints] = React.useState(false);

  // Auto-preencher horário para viagens imediatas
  useEffect(() => {
    if (state.type !== 'agendada' && !state.departureTime) {
      const now = new Date();
      now.setMinutes(now.getMinutes() + 5);
      actions.setDepartureTime(now.toISOString().slice(0, 16));
    }
  }, [state.type, state.departureTime, actions]);

  // Estimativa de preço
  const priceEstimateRequest: PriceEstimateRequest | null = React.useMemo(() => {
    if (!state.origin.coords || !state.destination.coords) return null;
    return {
      mode: state.type === 'entrega' ? 'delivery' : 'ride',
      origin: {
        latitude: state.origin.coords.latitude,
        longitude: state.origin.coords.longitude,
      },
      destination: {
        latitude: state.destination.coords.latitude,
        longitude: state.destination.coords.longitude,
      },
      options: { includeBreakdown: true, applyPeakHours: true },
    };
  }, [state.origin.coords, state.destination.coords, state.type]);

  const { data: priceEstimate } = usePriceEstimate(priceEstimateRequest, {
    enabled: !!priceEstimateRequest,
  });

  // Auto-preencher preço sugerido
  useEffect(() => {
    if (priceEstimate && !state.userEditedPrice) {
      actions.setSuggestedPrice(priceEstimate.estimatedPrice.toFixed(2));
    }
  }, [priceEstimate, state.userEditedPrice, actions]);

  // Reset userEditedPrice quando coords mudam
  useEffect(() => {
    actions.setUserEditedPrice(false);
  }, [state.origin.coords, state.destination.coords, actions]);

  // Criar address canônico
  const createAddress = useCallback(
    async (
      locationId: string,
      street: string,
      coords: GeolocationCoordinates | null
    ): Promise<string> => {
      const hasCoords = !!(coords?.latitude && coords?.longitude);
      const hasText = street.trim().length > 0;
      const addressType: 'exact' | 'approximate' | 'gps_only' =
        hasCoords && !hasText ? 'gps_only' : 'approximate';

      const addr = await addressService.createAddress({
        location_id: locationId,
        street: addressType !== 'gps_only' ? street : null,
        address_type: addressType,
        latitude: coords?.latitude || null,
        longitude: coords?.longitude || null,
        geocoding_source: hasCoords ? 'gps' : 'manual',
      });
      return addr.id;
    },
    [addressService]
  );

  // Submit handler
  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();

      if (!validation.canSubmit) {
        toast.error(validation.errors[0] || 'Preencha todos os campos obrigatórios');
        return;
      }

      actions.setSubmitting(true);

      try {
        const finalOrigin = state.selectedBoardingPoint
          ? `${state.selectedBoardingPoint.name} — ${state.selectedBoardingPoint.address}`
          : state.origin.text;

        // Criar addresses canônicos
        const [pickupAddressId, dropoffAddressId] = await Promise.all([
          createAddress(state.origin.locationId, finalOrigin, state.origin.coords),
          createAddress(
            state.destination.locationId,
            state.destination.text,
            state.destination.coords
          ),
        ]);

        // Montar observação com preferência de confiança
        const obs = [
          state.observation || '',
          state.trustPreference !== 'qualquer'
            ? `[Preferência: ${
                state.trustPreference === 'verificado'
                  ? 'Motorista Verificado'
                  : 'Vizinho do Bairro'
              }]`
            : '',
        ]
          .filter(Boolean)
          .join(' ');

        // Submeter
        await onSubmit({
          origin: finalOrigin,
          destination: state.destination.text,
          departure_time: new Date(state.departureTime || Date.now()).toISOString(),
          suggested_price: state.suggestedPrice ? parseFloat(state.suggestedPrice) : undefined,
          type: state.type,
          payment_method: state.paymentMethod,
          observation: obs || undefined,
          available_seats:
            state.type === 'carona_compartilhada' ? state.seats : undefined,
          origin_lat: state.origin.coords!.latitude,
          origin_lng: state.origin.coords!.longitude,
          destination_lat: state.destination.coords!.latitude,
          destination_lng: state.destination.coords!.longitude,
          search_radius_km: 5,
          pickup_address_id: pickupAddressId,
          dropoff_address_id: dropoffAddressId,
          pickup_location_id: state.origin.locationId,
          dropoff_location_id: state.destination.locationId,
        });

        // Reset form
        actions.reset();
      } catch (err: any) {
        logger.error('RideRequestForm.handleSubmit', err);
        toast.error(err?.message || 'Erro ao criar corrida. Tente novamente.');
      } finally {
        actions.setSubmitting(false);
      }
    },
    [validation, state, actions, onSubmit, createAddress]
  );

  const selectedRideType = state.type;
  const isDelivery = state.type === 'entrega';

  return (
    <form onSubmit={handleSubmit} className={cn('space-y-4', className)}>
      {/* Boarding Points Panel (se aberto) */}
      <AnimatePresence>
        {showBoardingPoints && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden"
          >
            <BoardingPointsPanel
              selectable
              selectedId={state.selectedBoardingPoint?.id}
              onSelect={(point: BoardingPoint) => {
                actions.setBoardingPoint(point);
                setShowBoardingPoints(false);
              }}
            />
            <Button
              type="button"
              variant="ghost"
              onClick={() => setShowBoardingPoints(false)}
              className="w-full mt-2 text-muted-foreground rounded-xl"
            >
              ← Voltar
            </Button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main Form (se não estiver mostrando boarding points) */}
      {!showBoardingPoints && (
        <>
          {/* ── FOCO PRINCIPAL ── */}
          
          {/* Origem */}
          <AddressInput
            label={isDelivery ? 'Local de retirada' : 'Origem'}
            placeholder="Digite o endereço de origem"
            showGPS
            autoCaptureGPS
            onValidated={(result) => {
              actions.setOrigin({
                text: result.text,
                coords: result.coords,
                locationId: result.locationId,
                isValid: true,
                isLoading: false,
              });
            }}
            icon={<div className="w-2 h-2 rounded-full bg-primary" />}
            iconColor="text-primary"
            required
          />

          {/* Ponto de Embarque (apenas viagem/compartilhada) */}
          {!isDelivery && (
            <motion.button
              type="button"
              onClick={() => setShowBoardingPoints(true)}
              className={cn(
                'w-full flex items-center gap-2 p-2.5 rounded-xl border transition-all text-left text-xs',
                state.selectedBoardingPoint
                  ? 'border-warning/40 bg-warning/10 text-warning'
                  : 'border-dashed border-border text-muted-foreground hover:border-border/80'
              )}
              whileHover={{ scale: 1.01 }}
              whileTap={{ scale: 0.99 }}
            >
              <MapPin className="h-3.5 w-3.5 flex-shrink-0" />
              {state.selectedBoardingPoint ? (
                <span className="font-medium">
                  {state.selectedBoardingPoint.name} — {state.selectedBoardingPoint.address}
                </span>
              ) : (
                <span>Ou escolher ponto de embarque do bairro →</span>
              )}
            </motion.button>
          )}

          {/* Destino */}
          <AddressInput
            label={isDelivery ? 'Destino da entrega' : 'Destino'}
            placeholder="Para onde você vai?"
            onValidated={(result) => {
              actions.setDestination({
                text: result.text,
                coords: result.coords,
                locationId: result.locationId,
                isValid: true,
                isLoading: false,
              });
            }}
            icon={<div className="w-2 h-2 rounded-sm bg-warning" />}
            iconColor="text-warning"
            required
          />

          {/* Estimativa de Rota */}
          <AnimatePresence>
            {priceEstimate && state.origin.coords && state.destination.coords && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
              >
                <RouteEstimateCardEnhanced
                  estimate={{
                    distance: priceEstimate.metadata.distanceKm,
                    duration: priceEstimate.metadata.durationMinutes,
                    price: priceEstimate.estimatedPrice,
                    eta: `${priceEstimate.metadata.durationMinutes} min`,
                    fare: {
                      base: priceEstimate.breakdown?.baseFare || 0,
                      distance: priceEstimate.breakdown?.distanceFare || 0,
                      time: priceEstimate.breakdown?.timeFare || 0,
                      total: priceEstimate.estimatedPrice,
                      formatted: `R$ ${priceEstimate.estimatedPrice.toFixed(2)}`,
                    },
                  }}
                  variant="compact"
                />
                {priceEstimate.metadata.peakHourMultiplier > 1 && (
                  <p className="text-xs text-warning mt-1">
                    ⚠️ Horário de pico ({priceEstimate.metadata.peakHourMultiplier}x)
                  </p>
                )}
              </motion.div>
            )}
          </AnimatePresence>

          {/* ── OPÇÕES RÁPIDAS ── */}

          {/* Tipo de Corrida */}
          <RideTypeSelector value={state.type} onChange={actions.setRideType} />

          {/* Preferências de Confiança (apenas não-entrega) */}
          {!isDelivery && (
            <TrustPreferenceChips
              value={state.trustPreference}
              onChange={actions.setTrustPreference}
            />
          )}

          {/* ── OPÇÕES AVANÇADAS ── */}

          <AdvancedOptions
            rideType={state.type}
            suggestedPrice={state.suggestedPrice}
            onSuggestedPriceChange={actions.setSuggestedPrice}
            paymentMethod={state.paymentMethod}
            onPaymentMethodChange={actions.setPaymentMethod}
            observation={state.observation}
            onObservationChange={actions.setObservation}
            departureTime={state.departureTime}
            onDepartureTimeChange={actions.setDepartureTime}
            seats={state.seats}
            onSeatsChange={actions.setSeats}
            estimatedPrice={priceEstimate?.estimatedPrice}
          />

          {/* ── CTA (STICKY) ── */}

          <Button
            type="submit"
            disabled={!validation.canSubmit}
            className={cn(
              'w-full text-primary-foreground font-semibold rounded-xl h-11 shadow-lg sticky bottom-4',
              selectedRideType === 'viagem' &&
                'bg-gradient-to-r from-primary to-accent hover:from-primary/90 hover:to-accent/90 shadow-primary/20',
              selectedRideType === 'entrega' &&
                'bg-gradient-to-r from-warning to-warning/80 hover:from-warning/90 hover:to-warning/70 shadow-warning/20',
              selectedRideType === 'agendada' &&
                'bg-gradient-to-r from-accent to-accent/80 hover:from-accent/90 hover:to-accent/70 shadow-accent/20',
              selectedRideType === 'carona_compartilhada' &&
                'bg-gradient-to-r from-secondary to-secondary/80 hover:from-secondary/90 hover:to-secondary/70 shadow-secondary/20'
            )}
          >
            {state.isSubmitting ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <>
                {selectedRideType === 'viagem' && '🚗'}
                {selectedRideType === 'entrega' && '📦'}
                {selectedRideType === 'agendada' && '📅'}
                {selectedRideType === 'carona_compartilhada' && '👥'}
              </>
            )}
            <span className="ml-2">
              {state.isSubmitting
                ? 'Solicitando...'
                : `Solicitar ${
                    selectedRideType === 'viagem'
                      ? 'Viagem'
                      : selectedRideType === 'entrega'
                      ? 'Entrega'
                      : selectedRideType === 'agendada'
                      ? 'Agendada'
                      : 'Compartilhada'
                  }`}
            </span>
          </Button>
        </>
      )}
    </form>
  );
});

RideRequestForm.displayName = 'RideRequestForm';

/**
 * 🚧 MIGRATION WARNING BANNER
 *
 * Componente temporário para indicar módulos que ainda não foram migrados
 * para a nova arquitetura feature-first.
 *
 * @version 1.0.0
 * @temporary Remover após conclusão da migração
 */

import React from "react";
import { AlertTriangle, Info } from "lucide-react";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "@/shared/components/ui/alert";

interface MigrationWarningBannerProps {
  moduleName: string;
  expectedMigrationPhase?: string;
  showInProduction?: boolean;
}

export function MigrationWarningBanner({
  moduleName,
  expectedMigrationPhase,
  showInProduction = false,
}: MigrationWarningBannerProps) {
  // Não mostrar em produção por padrão
  if (import.meta.env.PROD && !showInProduction) {
    return null;
  }

  return (
    <Alert className="mb-4 border-yellow-500/50 bg-yellow-500/10">
      <AlertTriangle className="h-4 w-4 text-yellow-500" />
      <AlertTitle className="text-yellow-500">🚧 Módulo em Migração</AlertTitle>
      <AlertDescription className="text-sm text-muted-foreground">
        <p className="mb-2">
          O módulo <strong>{moduleName}</strong> ainda não foi migrado para a
          nova arquitetura feature-first.
        </p>
        {expectedMigrationPhase && (
          <p className="text-xs">
            <Info className="inline h-3 w-3 mr-1" />
            Migração prevista: {expectedMigrationPhase}
          </p>
        )}
        <p className="text-xs mt-2 opacity-75">
          Este aviso é temporário e será removido após a conclusão da migração.
        </p>
      </AlertDescription>
    </Alert>
  );
}

/**
 * Hook para verificar se um módulo foi migrado
 */
export function useModuleMigrationStatus(moduleName: string): {
  isMigrated: boolean;
  phase: string | null;
} {
  // Módulos já migrados
  const migratedModules = new Set([
    "dashboard",
    "profile",
    "community",
    "notifications",
  ]);

  // Fases de migração planejadas
  const migrationPhases: Record<string, string> = {
    business: "Fase 6 - Semana 4 (Dias 1-2)",
    services: "Fase 6 - Semana 4 (Dias 3-4)",
    classifieds: "Fase 6 - Semana 5 (Dia 1)",
    mobility: "Fase 6 - Semana 5 (Dias 2-3)",
    admin: "Fase 6 - Semana 5 (Dias 4-5)",
  };

  return {
    isMigrated: migratedModules.has(moduleName),
    phase: migrationPhases[moduleName] || null,
  };
}

import React, { createContext, useContext, useEffect, useState } from "react";

interface AccessibilityContextType {
  announceToScreenReader: (message: string) => void;
  focusElement: (elementId: string) => void;
  isHighContrast: boolean;
  toggleHighContrast: () => void;
  fontSize: "normal" | "large" | "extra-large";
  setFontSize: (size: "normal" | "large" | "extra-large") => void;
}

const AccessibilityContext = createContext<
  AccessibilityContextType | undefined
>(undefined);

export function AccessibilityProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [isHighContrast, setIsHighContrast] = useState(false);
  const [fontSize, setFontSize] = useState<"normal" | "large" | "extra-large">(
    "normal",
  );

  // Load preferences from localStorage
  useEffect(() => {
    const savedContrast = localStorage.getItem("accessibility-high-contrast");
    const savedFontSize = localStorage.getItem("accessibility-font-size");

    if (savedContrast === "true") {
      setIsHighContrast(true);
    }

    if (
      savedFontSize &&
      ["normal", "large", "extra-large"].includes(savedFontSize)
    ) {
      setFontSize(savedFontSize as "normal" | "large" | "extra-large");
    }
  }, []);

  // Apply accessibility classes to body
  useEffect(() => {
    const body = document.body;

    // High contrast
    if (isHighContrast) {
      body.classList.add("accessibility-high-contrast");
    } else {
      body.classList.remove("accessibility-high-contrast");
    }

    // Font size
    body.classList.remove(
      "accessibility-font-large",
      "accessibility-font-extra-large",
    );
    if (fontSize === "large") {
      body.classList.add("accessibility-font-large");
    } else if (fontSize === "extra-large") {
      body.classList.add("accessibility-font-extra-large");
    }
  }, [isHighContrast, fontSize]);

  const announceToScreenReader = (message: string) => {
    const announcement = document.createElement("div");
    announcement.setAttribute("aria-live", "polite");
    announcement.setAttribute("aria-atomic", "true");
    announcement.className = "sr-only";
    announcement.textContent = message;

    document.body.appendChild(announcement);

    // Remove after announcement
    setTimeout(() => {
      document.body.removeChild(announcement);
    }, 1000);
  };

  const focusElement = (elementId: string) => {
    const element = document.getElementById(elementId);
    if (element) {
      element.focus();
      element.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  };

  const toggleHighContrast = () => {
    const newValue = !isHighContrast;
    setIsHighContrast(newValue);
    localStorage.setItem("accessibility-high-contrast", newValue.toString());
    announceToScreenReader(
      newValue ? "Alto contraste ativado" : "Alto contraste desativado",
    );
  };

  const handleSetFontSize = (size: "normal" | "large" | "extra-large") => {
    setFontSize(size);
    localStorage.setItem("accessibility-font-size", size);

    const sizeLabels = {
      normal: "Tamanho normal",
      large: "Tamanho grande",
      "extra-large": "Tamanho extra grande",
    };

    announceToScreenReader(`Fonte alterada para ${sizeLabels[size]}`);
  };

  return (
    <AccessibilityContext.Provider
      value={{
        announceToScreenReader,
        focusElement,
        isHighContrast,
        toggleHighContrast,
        fontSize,
        setFontSize: handleSetFontSize,
      }}
    >
      {children}
    </AccessibilityContext.Provider>
  );
}

export function useAccessibility() {
  const context = useContext(AccessibilityContext);
  if (!context) {
    throw new Error(
      "useAccessibility must be used within AccessibilityProvider",
    );
  }
  return context;
}

