/**
 * LocationAutocomplete - Componente de seleção hierárquica de localização
 * 
 * Permite seleção de Estado → Cidade → Bairro usando dados oficiais do IBGE
 * 
 * @version 1.0.0
 */

import { useState, useEffect, useCallback } from "react";
import { Check, ChevronsUpDown, MapPin } from "lucide-react";
import { cn } from "@/shared/utils/cn";
import { Button } from "@/shared/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
} from "@/shared/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/shared/components/ui/popover";
import { Label } from "@/shared/components/ui/label";
import { IBGEService, type Estado, type Municipio, type Distrito } from "@/shared/services/IBGEService";
import { logger } from "@/shared/utils/logger";

// ============================================================================
// TYPES
// ============================================================================

export interface LocationValue {
  estado?: string;
  estadoNome?: string;
  cidade?: string;
  cidadeId?: number;
  bairro?: string;
}

interface LocationAutocompleteProps {
  value: LocationValue;
  onChange: (value: LocationValue) => void;
  disabled?: boolean;
  required?: boolean;
  showBairro?: boolean;
  className?: string;
}

// ============================================================================
// COMPONENT
// ============================================================================

export function LocationAutocomplete({
  value,
  onChange,
  disabled = false,
  required = false,
  showBairro = true,
  className,
}: LocationAutocompleteProps) {
  // Estados
  const [estados, setEstados] = useState<Estado[]>([]);
  const [municipios, setMunicipios] = useState<Municipio[]>([]);
  const [distritos, setDistritos] = useState<Distrito[]>([]);

  // Loading states
  const [loadingEstados, setLoadingEstados] = useState(false);
  const [loadingMunicipios, setLoadingMunicipios] = useState(false);
  const [loadingDistritos, setLoadingDistritos] = useState(false);

  // Popover states
  const [openEstado, setOpenEstado] = useState(false);
  const [openCidade, setOpenCidade] = useState(false);
  const [openBairro, setOpenBairro] = useState(false);

  // ============================================================================
  // EFFECTS
  // ============================================================================

  // Carregar estados ao montar
  useEffect(() => {
    loadEstados();
  }, []);

  // Carregar municípios quando estado mudar
  useEffect(() => {
    if (value.estado) {
      loadMunicipios(value.estado);
    } else {
      setMunicipios([]);
      setDistritos([]);
    }
  }, [value.estado]);

  // Carregar distritos quando cidade mudar
  useEffect(() => {
    if (value.cidadeId && showBairro) {
      loadDistritos(value.cidadeId);
    } else {
      setDistritos([]);
    }
  }, [value.cidadeId, showBairro]);

  // ============================================================================
  // HANDLERS
  // ============================================================================

  const loadEstados = useCallback(async () => {
    setLoadingEstados(true);
    try {
      const data = await IBGEService.getEstados();
      setEstados(data);
    } catch (error) {
      logger.error("Erro ao carregar estados", error as Error);
    } finally {
      setLoadingEstados(false);
    }
  }, []);

  const loadMunicipios = useCallback(async (uf: string) => {
    setLoadingMunicipios(true);
    try {
      const data = await IBGEService.getMunicipiosPorEstado(uf);
      setMunicipios(data);
    } catch (error) {
      logger.error("Erro ao carregar municípios", error as Error);
    } finally {
      setLoadingMunicipios(false);
    }
  }, []);

  const loadDistritos = useCallback(async (municipioId: number) => {
    setLoadingDistritos(true);
    try {
      const data = await IBGEService.getDistritosPorMunicipio(municipioId);
      setDistritos(data);
    } catch (error) {
      logger.error("Erro ao carregar distritos", error as Error);
    } finally {
      setLoadingDistritos(false);
    }
  }, []);

  const handleEstadoSelect = useCallback((estado: Estado) => {
    onChange({
      estado: estado.sigla,
      estadoNome: estado.nome,
      cidade: undefined,
      cidadeId: undefined,
      bairro: undefined,
    });
    setOpenEstado(false);
  }, [onChange]);

  const handleCidadeSelect = useCallback((municipio: Municipio) => {
    onChange({
      ...value,
      cidade: municipio.nome,
      cidadeId: municipio.id,
      bairro: undefined,
    });
    setOpenCidade(false);
  }, [onChange, value]);

  const handleBairroSelect = useCallback((distrito: Distrito) => {
    onChange({
      ...value,
      bairro: distrito.nome,
    });
    setOpenBairro(false);
  }, [onChange, value]);

  // ============================================================================
  // RENDER
  // ============================================================================

  return (
    <div className={cn("space-y-4", className)}>
      {/* Estado */}
      <div className="space-y-2">
        <Label htmlFor="estado">
          Estado {required && <span className="text-destructive">*</span>}
        </Label>
        <Popover open={openEstado} onOpenChange={setOpenEstado}>
          <PopoverTrigger asChild>
            <Button
              id="estado"
              variant="outline"
              role="combobox"
              aria-expanded={openEstado}
              className="w-full justify-between"
              disabled={disabled || loadingEstados}
            >
              {value.estadoNome || "Selecione o estado..."}
              <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-full p-0">
            <Command>
              <CommandInput placeholder="Buscar estado..." />
              <CommandEmpty>Nenhum estado encontrado.</CommandEmpty>
              <CommandGroup className="max-h-64 overflow-auto">
                {estados.map((estado) => (
                  <CommandItem
                    key={estado.id}
                    value={estado.nome}
                    onSelect={() => handleEstadoSelect(estado)}
                  >
                    <Check
                      className={cn(
                        "mr-2 h-4 w-4",
                        value.estado === estado.sigla
                          ? "opacity-100"
                          : "opacity-0"
                      )}
                    />
                    {estado.nome} ({estado.sigla})
                  </CommandItem>
                ))}
              </CommandGroup>
            </Command>
          </PopoverContent>
        </Popover>
      </div>

      {/* Cidade */}
      <div className="space-y-2">
        <Label htmlFor="cidade">
          Cidade {required && <span className="text-destructive">*</span>}
        </Label>
        <Popover open={openCidade} onOpenChange={setOpenCidade}>
          <PopoverTrigger asChild>
            <Button
              id="cidade"
              variant="outline"
              role="combobox"
              aria-expanded={openCidade}
              className="w-full justify-between"
              disabled={disabled || !value.estado || loadingMunicipios}
            >
              {value.cidade || "Selecione a cidade..."}
              <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-full p-0">
            <Command>
              <CommandInput placeholder="Buscar cidade..." />
              <CommandEmpty>Nenhuma cidade encontrada.</CommandEmpty>
              <CommandGroup className="max-h-64 overflow-auto">
                {municipios.map((municipio) => (
                  <CommandItem
                    key={municipio.id}
                    value={municipio.nome}
                    onSelect={() => handleCidadeSelect(municipio)}
                  >
                    <Check
                      className={cn(
                        "mr-2 h-4 w-4",
                        value.cidade === municipio.nome
                          ? "opacity-100"
                          : "opacity-0"
                      )}
                    />
                    {municipio.nome}
                  </CommandItem>
                ))}
              </CommandGroup>
            </Command>
          </PopoverContent>
        </Popover>
      </div>

      {/* Bairro (opcional) */}
      {showBairro && (
        <div className="space-y-2">
          <Label htmlFor="bairro">
            Bairro/Distrito
            <span className="text-muted-foreground text-xs ml-2">(opcional)</span>
          </Label>
          <Popover open={openBairro} onOpenChange={setOpenBairro}>
            <PopoverTrigger asChild>
              <Button
                id="bairro"
                variant="outline"
                role="combobox"
                aria-expanded={openBairro}
                className="w-full justify-between"
                disabled={disabled || !value.cidadeId || loadingDistritos}
              >
                {value.bairro || "Selecione o bairro..."}
                <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-full p-0">
              <Command>
                <CommandInput placeholder="Buscar bairro..." />
                <CommandEmpty>
                  {distritos.length === 0
                    ? "Nenhum distrito cadastrado para esta cidade."
                    : "Nenhum bairro encontrado."}
                </CommandEmpty>
                <CommandGroup className="max-h-64 overflow-auto">
                  {distritos.map((distrito) => (
                    <CommandItem
                      key={distrito.id}
                      value={distrito.nome}
                      onSelect={() => handleBairroSelect(distrito)}
                    >
                      <Check
                        className={cn(
                          "mr-2 h-4 w-4",
                          value.bairro === distrito.nome
                            ? "opacity-100"
                            : "opacity-0"
                        )}
                      />
                      {distrito.nome}
                    </CommandItem>
                  ))}
                </CommandGroup>
              </Command>
            </PopoverContent>
          </Popover>
          {distritos.length === 0 && value.cidadeId && !loadingDistritos && (
            <p className="text-xs text-muted-foreground flex items-center gap-1">
              <MapPin className="h-3 w-3" />
              Esta cidade não possui distritos cadastrados no IBGE
            </p>
          )}
        </div>
      )}
    </div>
  );
}

import React from "react";
import { useEffect, useState } from "react";
import { WifiOff, Wifi, Download } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { DRIVER_STATUS } from "@/shared/types/constants";
import { logger } from "@/shared/utils/logger";

export function OfflineIndicator() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showIndicator, setShowIndicator] = useState(false);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      setShowIndicator(true);

      // Esconder após 3 segundos
      setTimeout(() => setShowIndicator(false), 3000);
    };

    const handleOffline = () => {
      setIsOnline(false);
      setShowIndicator(true);
    };

    window.addEventListener(DRIVER_STATUS.ONLINE, handleOnline);
    window.addEventListener(DRIVER_STATUS.OFFLINE, handleOffline);

    // Mostrar indicador se já estiver offline
    if (!navigator.onLine) {
      setShowIndicator(true);
    }

    return () => {
      window.removeEventListener(DRIVER_STATUS.ONLINE, handleOnline);
      window.removeEventListener(DRIVER_STATUS.OFFLINE, handleOffline);
    };
  }, []);

  return (
    <AnimatePresence>
      {showIndicator && (
        <motion.div
          initial={{ y: -100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: -100, opacity: 0 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
          className={`fixed top-4 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full shadow-lg flex items-center gap-2 ${
            isOnline ? "bg-green-500 text-white" : "bg-red-500 text-white"
          }`}
        >
          {isOnline ? (
            <>
              <Wifi className="w-4 h-4" />
              <span className="text-sm font-medium">Conexão restaurada</span>
            </>
          ) : (
            <>
              <WifiOff className="w-4 h-4" />
              <span className="text-sm font-medium">Você está offline</span>
            </>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export function OfflineBanner() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener(DRIVER_STATUS.ONLINE, handleOnline);
    window.addEventListener(DRIVER_STATUS.OFFLINE, handleOffline);

    return () => {
      window.removeEventListener(DRIVER_STATUS.ONLINE, handleOnline);
      window.removeEventListener(DRIVER_STATUS.OFFLINE, handleOffline);
    };
  }, []);

  if (isOnline) return null;

  return (
    <div className="bg-yellow-500/10 border-b border-yellow-500/30 px-4 py-2">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div className="flex items-center gap-2">
          <WifiOff className="w-4 h-4 text-yellow-500" />
          <span className="text-sm text-yellow-500 font-medium">
            Modo Offline - Alguns recursos podem estar limitados
          </span>
        </div>
        <button
          onClick={() => window.location.reload()}
          className="text-xs text-yellow-500 hover:text-yellow-400 underline"
        >
          Tentar reconectar
        </button>
      </div>
    </div>
  );
}

export function OfflineDataStatus() {
  const [hasCachedData, setHasCachedData] = useState(false);
  const [cacheSize, setCacheSize] = useState<string>("0 KB");

  useEffect(() => {
    checkCachedData();
  }, []);

  const checkCachedData = async () => {
    try {
      const cache = await caches.open("localconnect-critical-v1");
      const keys = await cache.keys();

      setHasCachedData(keys.length > 0);

      // Estimar tamanho do cache
      if ("storage" in navigator && "estimate" in navigator.storage) {
        const estimate = await navigator.storage.estimate();
        const usage = estimate.usage || 0;
        setCacheSize(formatBytes(usage));
      }
    } catch (error) {
      logger.error("Error verify cache:", error);
    }
  };

  const formatBytes = (bytes: number): string => {
    if (bytes === 0) return "0 KB";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + " " + sizes[i];
  };

  return (
    <div className="flex items-center gap-2 text-sm text-muted-foreground">
      <Download className="w-4 h-4" />
      <span>
        {hasCachedData ? (
          <>Dados offline: {cacheSize}</>
        ) : (
          <>Nenhum dado offline salvo</>
        )}
      </span>
    </div>
  );
}

/**
 * SafeHtml - Componente seguro para renderizar HTML
 * 
 * ✅ ÚNICO lugar permitido para renderizar HTML de usuário
 * ✅ Sanitização automática com DOMPurify
 * ✅ Configuração vem do SSOT (security.config.ts)
 * 
 * @example
 * ```tsx
 * // ✅ CORRETO
 * <SafeHtml content={userContent} />
 * 
 * // ❌ ERRADO - Nunca faça isso
 * <div dangerouslySetInnerHTML={{__html: userContent}} />
 * ```
 * 
 * @security-critical
 * @ssot src/config/security.config.ts
 */

import DOMPurify from 'dompurify';
import { useMemo } from 'react';
import { HTML_SANITIZATION_CONFIG } from '@/config/security.config';

interface SafeHtmlProps {
  /** Conteúdo HTML a ser sanitizado e renderizado */
  content: string;
  /** Tags HTML permitidas (padrão: vem do SSOT) */
  allowedTags?: string[];
  /** Atributos permitidos (padrão: vem do SSOT) */
  allowedAttributes?: Record<string, string[]>;
  /** Classe CSS do container */
  className?: string;
  /** Elemento wrapper (padrão: div) */
  as?: keyof JSX.IntrinsicElements;
}

/**
 * Sanitiza HTML usando DOMPurify com configuração do SSOT
 * 
 * IMPORTANTE: Configuração vem de security.config.ts (SSOT)
 * NÃO hardcode configurações aqui!
 */
function sanitizeHtml(
  html: string,
  allowedTags?: string[],
  allowedAttributes?: Record<string, string[]>
): string {
  // Configuração vem do SSOT - Single Source of Truth
  return DOMPurify.sanitize(html, {
    // Use custom config if provided, otherwise use SSOT
    ALLOWED_TAGS: allowedTags || HTML_SANITIZATION_CONFIG.ALLOWED_TAGS,
    ALLOWED_ATTR: allowedAttributes || HTML_SANITIZATION_CONFIG.ALLOWED_ATTR,
    ALLOW_DATA_ATTR: HTML_SANITIZATION_CONFIG.ALLOW_DATA_ATTR,
    ALLOW_UNKNOWN_PROTOCOLS: false,
    SAFE_FOR_TEMPLATES: true,
    // Forbidden tags/attrs from SSOT
    FORBID_TAGS: HTML_SANITIZATION_CONFIG.FORBID_TAGS,
    FORBID_ATTR: HTML_SANITIZATION_CONFIG.FORBID_ATTR,
  });
}

export function SafeHtml({
  content,
  allowedTags,
  allowedAttributes,
  className,
  as: Component = 'div'
}: SafeHtmlProps) {
  // Memoiza sanitização para performance
  const sanitizedContent = useMemo(
    () => sanitizeHtml(content, allowedTags, allowedAttributes),
    [content, allowedTags, allowedAttributes]
  );

  return (
    <Component
      className={className}
      dangerouslySetInnerHTML={{ __html: sanitizedContent }}
    />
  );
}

/**
 * Hook para sanitizar HTML sem renderizar
 */
export function useSanitizedHtml(
  html: string,
  allowedTags?: string[],
  allowedAttributes?: Record<string, string[]>
): string {
  return useMemo(
    () => sanitizeHtml(html, allowedTags, allowedAttributes),
    [html, allowedTags, allowedAttributes]
  );
}

/**
 * Sanitiza texto puro (remove TODAS as tags HTML)
 */
export function sanitizePlainText(text: string): string {
  return DOMPurify.sanitize(text, {
    ALLOWED_TAGS: [],
    ALLOWED_ATTR: [],
  });
}

import React from "react";
import { AlertTriangle, RefreshCw } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { logger } from "@/shared/utils/logger";

interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
}

interface ErrorBoundaryProps {
  children: React.ReactNode;
  fallback?: React.ComponentType<{ error?: Error; retry: () => void }>;
}

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    logger.error("ErrorBoundary caught an error:", error, errorInfo);
  }

  retry = () => {
    this.setState({ hasError: false, error: undefined });
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        const FallbackComponent = this.props.fallback;
        return (
          <FallbackComponent error={this.state.error} retry={this.retry} />
        );
      }

      return (
        <DefaultErrorFallback error={this.state.error} retry={this.retry} />
      );
    }

    return this.props.children;
  }
}

function DefaultErrorFallback({
  error,
  retry,
}: {
  error?: Error;
  retry: () => void;
}) {
  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
      <div className="bg-white rounded-lg shadow-md p-8 max-w-md w-full text-center">
        <AlertTriangle className="mx-auto mb-4 text-red-500" size={48} />
        <h2 className="text-2xl font-bold text-gray-900 mb-2">
          Ops! Algo deu errado
        </h2>
        <p className="text-gray-600 mb-6">
          Ocorreu um erro inesperado. Tente novamente ou recarregue a página.
        </p>
        {error && (
          <details className="text-left mb-6">
            <summary className="cursor-pointer text-sm text-gray-500 mb-2">
              Detalhes técnicos
            </summary>
            <pre className="text-xs bg-gray-100 p-2 rounded overflow-auto">
              {error.message}
            </pre>
          </details>
        )}
        <div className="space-y-3">
          <Button onClick={retry} className="w-full">
            <RefreshCw className="mr-2" size={16} />
            Tentar Novamente
          </Button>
          <Button
            variant="outline"
            onClick={() => window.location.reload()}
            className="w-full"
          >
            Reload Página
          </Button>
        </div>
      </div>
    </div>
  );
}

